window.WORKBOOK={"title": "Around the World in 80 Integrals", "course": "Math 23B · Application Worksheets", "version": 1, "accessed": "2026-11-17", "sources": {"noaa": {"title": "NOAA Monterey Harbor tidal datums", "url": "https://tidesandcurrents.noaa.gov/benchmarks/9413450.html", "kind": "Published observation-derived datums", "note": "Station 9413450; epoch 1983–2001; benchmark sheet published October 12, 2011. Meters above MLLW. These are long-term reference levels, not successive tide readings or a forecast.", "headers": ["Datum", "Height above MLLW (m)"], "rows": [["MHHW", "1.626"], ["MHW", "1.412"], ["MTL", "0.873"], ["MSL", "0.862"], ["MLW", "0.333"], ["MLLW", "0.000"]]}, "aquarium": {"title": "Monterey Bay Aquarium facts and figures", "url": "https://www.montereybayaquarium.org/about-us/about-the-aquarium/newsroom/media-kits/facts-and-figures", "kind": "Published dimensions and capacities", "note": "Published exhibit dimensions and capacities, accessed November 17, 2026. They are not a survey of tank shape or a measured spatial velocity field.", "headers": ["Exhibit", "Published dimensions / capacity"], "rows": [["Open Sea", "90 ft across; 52 ft front to back; 35 ft tall; 1,200,000 US gal"], ["Kelp Forest", "28 ft tall; 343,000 US gal"], ["Sea Otters", "15 ft tall; 55,000 US gal"]]}, "imd_grid": {"title": "IMD 0.25° gridded daily rainfall for India (Pai et al., 2014)", "url": "https://mausamjournal.imd.gov.in/index.php/MAUSAM/article/view/851", "kind": "Peer-reviewed dataset description", "note": "D. S. Pai, M. Rajeevan, O. P. Sreejith, B. Mukhopadhyay and N. S. Satbha, MAUSAM 65(1), 1–18, 2014, abstract. The rainfall pattern on the 2 × 2 block of cells used in the problem is a teaching model, not a day from the dataset.", "headers": ["Quantity", "Published value"], "rows": [["Grid spacing", "0.25° latitude × 0.25° longitude"], ["Rain-gauge stations used", "6955"], ["Period covered", "1901–2010 (110 years)"]]}, "imd_terms": {"title": "IMD terminology for heavy rainfall (Hazard Atlas)", "url": "https://www.imdpune.gov.in/hazardatlas/extreme.pdf", "kind": "Official classification", "note": "India Meteorological Department, Pune, Hazard Atlas notes on extreme rainfall events, “terminologies used by the India Meteorological Department”. Amounts are 24-hour rainfall at a station.", "headers": ["Term", "24-hour rainfall (mm)"], "rows": [["Heavy rainfall", "64.5–115.5"], ["Very heavy rainfall", "115.6–204.4"], ["Extremely heavy rainfall", "204.5 or more"]]}, "cpc_oni": {"title": "NOAA CPC Oceanic Niño Index (ERSST.v6)", "url": "https://www.cpc.ncep.noaa.gov/products/analysis_monitoring/enso/oni/v6/", "kind": "Published climate index", "note": "NOAA Climate Prediction Center, accessed November 17, 2026. The ONI is the 3-month running mean of SST anomalies in the Niño 3.4 region; El Niño periods use a threshold of +0.5 °C met for at least five overlapping seasons. CPC now notes that the Relative ONI (RONI) is used for official monitoring. The anomaly maps in the problem are models, not observed fields.", "headers": ["Quantity", "Published value"], "rows": [["Niño 3.4 region", "5°N–5°S, 120°–170°W"], ["Warm/cold threshold", "+0.5 °C (warm) and −0.5 °C (cold)"], ["ONI, Nov–Jan 2015/16", "2.6 °C"], ["ONI, Nov–Jan 1997/98", "2.4 °C"], ["ONI, Nov–Jan 2023/24", "2.0 °C"]]}, "inah_sun": {"title": "Sarabia González, “Los túneles arqueológicos en la pirámide del Sol de Teotihuacán”", "url": "https://revistas.inah.gob.mx/index.php/arqueologia/article/download/18327/19713/39517", "kind": "Peer-reviewed archaeology journal (INAH)", "note": "Alejandro Sarabia González (Zona Arqueológica de Teotihuacán, INAH), Arqueología 61, July 2020, p. 1 (Spanish; translated). Other sources give heights from about 63 m to 75 m, partly because they measure different construction stages. The square base and smooth or stepped shapes in the problem are models.", "headers": ["Quantity", "Published value"], "rows": [["Height today", "66.00 m"], ["Base", "224.00 m"], ["Architectural levels (cuerpos)", "4"], ["Solid volume", "a little over 1,175,000 m³"]]}, "asce_gerd": {"title": "Civil Engineering (ASCE): Giant Ethiopian dam promises greater flood control", "url": "https://www.asce.org/publications-and-news/civil-engineering-source/civil-engineering-magazine/issues/magazine-issue/article/2025/07/giant-ethiopian-dam-promises-greater-flood-control-and-water-management", "kind": "Published engineering description", "note": "ASCE Civil Engineering magazine, July 2025. The article also stresses the Blue Nile’s “substantial sediment load” but gives no number; the sediment profile in the problem is assumed.", "headers": ["Quantity", "Published value"], "rows": [["Dam height and length", "145 m high, 1,780 m long"], ["Storage at full capacity", "74 billion m³"], ["Reservoir area when full", "about 1,874 km²"], ["Full supply level", "640 m above mean sea level"], ["Powerhouse capacity", "5,150 MW"]]}, "wiki_gerd": {"title": "Wikipedia: Grand Ethiopian Renaissance Dam (infobox)", "url": "https://en.wikipedia.org/wiki/Grand_Ethiopian_Renaissance_Dam", "kind": "Secondary source (encyclopedia)", "note": "Secondary, uncited infobox values, accessed November 17, 2026; used only for the depth at the dam and the reservoir length, which the ASCE article does not give.", "headers": ["Quantity", "Reported value"], "rows": [["Maximum water depth", "140 m"], ["Maximum reservoir length", "246 km"]]}, "nasa_ozone": {"title": "NASA Ozone Watch: annual records", "url": "https://ozonewatch.gsfc.nasa.gov/meteorology/annual_data.html", "kind": "Published observation-derived records", "note": "NASA Goddard Ozone Watch, accessed November 17, 2026: maximum daily ozone-hole area and minimum daily ozone for each year. NASA’s facts page defines the hole as “the region over Antarctica with total ozone of 220 Dobson Units or lower.” The circular hole and the coarse square grid in the problem are models.", "headers": ["Year", "Max hole area (million km²), date", "Min ozone (DU), date"], "rows": [["2000", "29.9, 9 Sep", "89, 29 Sep"], ["2006", "29.6, 24 Sep", "84, 8 Oct"], ["2015", "28.2, 2 Oct", "101, 4 Oct"], ["2022", "26.5, 5 Oct", "97, 1 Oct"], ["2023", "26.0, 21 Sep", "99, 3 Oct"]]}, "pilat": {"title": "Syndicat Mixte de la Grande Dune du Pilat: visitor brochure (2023)", "url": "https://ladunedupilat.com/wp-content/uploads/2023/07/Dune_Pilat_depliant_HD_EN_2023.pdf", "kind": "Published site figures", "note": "Official English brochure of the public body that manages the Grand Site de la Dune du Pilat. Figures are rounded; the height is given as about 110 m. The parabola-and-line cross-section in the problem is a model.", "headers": ["Quantity", "Published value"], "rows": [["Width", "600 m"], ["Length", "2,900 m"], ["Height", "about 110 m"], ["Sand", "55 million m³"], ["Movement toward the forest", "1 to 5 m per year"]]}, "khumbu": {"title": "Wikipedia: Khumbu Glacier", "url": "https://en.wikipedia.org/wiki/Khumbu_Glacier", "kind": "Secondary source (encyclopedia)", "note": "Wikipedia, accessed November 17, 2026, citing an ASTER study of supraglacial lakes in the Everest region. Only the length and elevations are published here; the tongue length, width, thickness, and shape in the problem are assumptions for a model, not survey values.", "headers": ["Quantity", "Reported value"], "rows": [["Length of the main glacier", "about 17 km"], ["Elevation of the terminus", "4,900 m"], ["Elevation of the source", "7,600 m"]]}, "turkana": {"title": "Lake Turkana Wind Power Project: Updated ESIA Summary (EIB, 2011)", "url": "https://www.eib.org/attachments/registers/53222536.pdf", "kind": "Published project summary", "note": "European Investment Bank register, Updated Environmental and Social Impact Assessment Summary, November 2011. The wind farm was completed in 2018 with the same 365 V52 turbines. The Weibull wind model and the turbine power curve in the problem are assumptions.", "headers": ["Quantity", "Published value"], "rows": [["Turbines", "365 Vestas V52, 0.850 MW each, hub height 44 m"], ["Installed capacity", "310 MW"], ["Average wind speed", "11 m/s (on-site measurements by DEWI)"], ["Estimated average production", "1,440 GWh per year"]]}, "threegorges": {"title": "Wikipedia: Three Gorges Dam (ship lift)", "url": "https://en.wikipedia.org/wiki/Three_Gorges_Dam", "kind": "Secondary source (encyclopedia)", "note": "Wikipedia, accessed November 17, 2026; the lift height is cited there to the China Three Gorges Project. The smooth-start motion in the problem is an assumption.", "headers": ["Quantity", "Reported value"], "rows": [["Ship lift basin", "120 m × 18 m × 3.5 m"], ["Vertical distance travelled", "113 m"], ["Largest ships lifted", "3,000 tons"]]}, "kspivot": {"title": "Considerations for Nozzle Package Selection for Center Pivots (K-State L908)", "url": "https://bookstore.ksre.ksu.edu/download/considerations-for-nozzle-package-selection-for-center-pivots_L908", "kind": "Published extension guidance and worked example", "note": "D. H. Rogers and M. Alam, Kansas State University Research and Extension publication L908, December 2008. The 128-acre, 650 gpm system is the publication’s worked example, not a particular farm. Treating the irrigated area as one full circle and the nozzle spacing are assumptions.", "headers": ["Quantity", "Published value"], "rows": [["Share of Kansas irrigated acreage watered by center pivots", "approximately 90 percent"], ["Worked example: irrigated area", "128 acres"], ["Worked example: system flow", "650 gpm"], ["Worked example: system irrigation capacity", "0.27 in/day"], ["Why nozzle rates rise outward", "application rate increases with distance from the pivot point as more area is covered by the nozzle"]]}, "graphene": {"title": "Scientific Background on the Nobel Prize in Physics 2010: Graphene", "url": "https://www.nobelprize.org/uploads/2018/06/advanced-physicsprize2010-1.pdf", "kind": "Published physical constants of a material", "note": "Class for Physics of the Royal Swedish Academy of Sciences, 2010. The lattice vectors used in the problem follow from the published carbon–carbon distance; the hammock is the document’s own illustration.", "headers": ["Quantity", "Published value"], "rows": [["Carbon–carbon distance", "0.142 nm"], ["Atoms per unit hexagonal cell", "2"], ["Area of the unit cell", "0.052 nm²"], ["Density", "0.77 mg/m²"], ["1 m² hammock: load it could hold", "approximately 4 kg (a cat)"]]}, "neowise": {"title": "JPL Small-Body Database and Horizons: comet C/2020 F3 (NEOWISE)", "url": "https://ssd.jpl.nasa.gov/tools/sbdb_lookup.html#/?sstr=C%2F2020%20F3", "kind": "Published orbit solution and ephemeris", "note": "NASA JPL Solar System Dynamics, orbit solution JPL#31 (epoch 2020-Jul-06), accessed November 17, 2026. Heliocentric distances are from a Horizons vector ephemeris (centre: Sun). 1 au = 149,597,870.7 km.", "headers": ["Quantity", "Published value"], "rows": [["Perihelion distance q", "0.29465 au"], ["Eccentricity e", "0.99918"], ["Time of perihelion", "JD 2459034.179 TDB (2020 July 3.68)"], ["Distance from Sun, 2020-Aug-09 00:00 TDB", "148,741,645 km"], ["Distance from Sun, 2020-Aug-10 00:00 TDB", "151,791,397 km"]]}, "boxmuller": {"title": "Box–Muller Transformation (Wolfram MathWorld)", "url": "https://mathworld.wolfram.com/Box-MullerTransformation.html", "kind": "Published method (secondary reference)", "note": "E. W. Weisstein, MathWorld, accessed November 17, 2026; secondary source for the method of G. E. P. Box and M. E. Muller, Ann. Math. Statist. 29 (1958), 610–611. No measured data are involved.", "headers": ["Item", "Published form"], "rows": [["Inputs", "two independent uniform random numbers in (0, 1)"], ["First output", "$\\sqrt{-2\\ln x_1}\\cos(2\\pi x_2)$"], ["Second output", "$\\sqrt{-2\\ln x_1}\\sin(2\\pi x_2)$"], ["Result", "two independent standard normal numbers"]]}, "snyder": {"title": "Map Projections: A Working Manual (USGS Professional Paper 1395)", "url": "https://pubs.usgs.gov/pp/1395/report.pdf", "kind": "Published projection formulas", "note": "J. P. Snyder, U.S. Geological Survey, 1987, chapter 7 (Mercator) and chapter 10 (cylindrical equal-area), spherical forms.", "headers": ["Projection", "Published formula"], "rows": [["Mercator", "$x=R(\\lambda-\\lambda_0)$, $y=R\\ln\\tan(\\pi/4+\\phi/2)$"], ["Mercator scale factor", "$h=k=\\sec\\phi$"], ["Mercator areal scale factor", "$\\sec^2\\phi$"], ["Cylindrical equal-area (standard parallel 0°)", "$x=R(\\lambda-\\lambda_0)$, $y=R\\sin\\phi$"]]}, "unareas": {"title": "UN Demographic Yearbook 2014, Table 3 (surface area)", "url": "https://unstats.un.org/unsd/Demographic/products/dyb/dyb2014/Table03.pdf", "kind": "Published national surface areas", "note": "United Nations Statistics Division. Surface area includes land and inland waters.", "headers": ["Country or area", "Surface area (km²)"], "rows": [["Greenland", "2,166,086"], ["Democratic Republic of the Congo", "2,344,858"]]}, "gatewayarch": {"title": "Gateway Arch Fact Sheet (National Park Service)", "url": "https://www.nps.gov/jeff/planyourvisit/gateway-arch-fact-sheet.htm", "kind": "Published structural dimensions", "note": "Gateway Arch National Park, U.S. National Park Service, accessed November 17, 2026. The parabolic outlines and the thickness-based density in the problem are models, not the arch’s design curve.", "headers": ["Quantity", "Published value"], "rows": [["Outer width (outside north leg to outside south leg)", "630 ft (192 m)"], ["Maximum height", "630 ft (192 m)"], ["Shape of arch section", "equilateral triangle"], ["Dimension of arch at base", "54 ft (16.46 m)"], ["Dimension of arch at top", "17 ft (5.18 m)"], ["Concrete between skins", "to 300 ft (91 m)"]]}, "earthfacts": {"title": "NASA Earth Fact Sheet (bulk parameters)", "url": "https://nssdc.gsfc.nasa.gov/planetary/factsheet/earthfact.html", "kind": "Published planetary parameters", "note": "NASA NSSDC, accessed November 17, 2026. The moment of inertia factor is measured from Earth’s response to the torques of the Sun and Moon; the quadratic density profile in the problem is a model.", "headers": ["Quantity", "Published value"], "rows": [["Mass", "5.9722 × 10²⁴ kg"], ["Volumetric mean radius", "6371.000 km"], ["Mean density", "5513 kg/m³"], ["Moment of inertia (I/MR²)", "0.3308"], ["GM", "0.39860 × 10^6 km³/s² (398,600 km³/s²)"], ["Escape velocity", "11.186 km/s"]]}, "fmiradar": {"title": "First experiences of operational use of a dual-polarisation weather radar in Finland", "url": "https://ams.confex.com/ams/35Radar/webprogram/Manuscript/Paper191344/Manuscript.pdf", "kind": "Published radar scan schedule", "note": "L. Nevvonen and E. Saltikoff (Finnish Meteorological Institute), 35th AMS Conference on Radar Meteorology, 2011, Table 1. The schedule repeats every 15 minutes. The flat-Earth, straight-beam geometry in the problem is a simplification.", "headers": ["Scan group", "Elevation angles (deg)", "Range (km)"], "rows": [["A", "0.3, 1.5, 3, 5, 9", "250"], ["B", "0.3, 2, 4", "100"], ["C", "2, 7, 11, 15, 25, 45", "100"], ["RHI", "0.0 to 60.0", "150"]]}, "walker1977": {"title": "The effects of urban lighting on the brightness of the night sky", "url": "https://articles.adsabs.harvard.edu/pdf/1977PASP...89..405W", "kind": "Published observations and empirical law", "note": "M. F. Walker (Lick Observatory, UC Santa Cruz), Publications of the Astronomical Society of the Pacific 89 (1977) 405–409, Table III, column (1). Sky brightness at 45° altitude toward Salinas, in units of the natural sky brightness. Uniformly spread lights in the problem are a model.", "headers": ["Distance from Salinas (km)", "Visual intensity", "Blue intensity"], "rows": [["8.0", "2.41", "2.36"], ["10.5", "1.91", "1.91"], ["14.2", "1.23", "1.18"], ["16.9", "0.59", "0.64"], ["18.7", "0.68", "0.68"], ["24.5", "0.27", "0.27"], ["32.2", "0.14", "0.09"], ["35.7", "0.09", "0.05"]]}, "taipeidamper": {"title": "Guinness World Records: largest tuned mass damper", "url": "https://www.guinnessworldrecords.com/world-records/774616-largest-tuned-mass-damper", "kind": "Published record entry", "note": "Guinness World Records, record dated December 31, 2004, accessed November 17, 2026. The damper is built of stacked steel plates; treating it as a solid ball of uniform steel is an assumption.", "headers": ["Quantity", "Published value"], "rows": [["Mass of the pendulum weight", "660 tonnes"], ["Hangs between floors", "87th and 92nd"], ["Building height", "508 m"], ["Maximum extension", "1.5 m"]]}, "ggbridge": {"title": "Golden Gate Bridge: design and construction statistics", "url": "https://www.goldengate.org/bridge/history-research/statistics-data/design-construction-stats/", "kind": "Published structural statistics", "note": "Golden Gate Bridge Highway and Transportation District, accessed November 17, 2026. The weight row covers both main cables plus the suspender cables and accessories.", "headers": ["Quantity", "Published value"], "rows": [["Main span (distance between towers)", "4,200 ft (1,280 m)"], ["Diameter of one main cable, with wrapping", "36 3/8 in (0.92 m)"], ["Steel wires in one main cable", "27,572"], ["Length of one main cable (anchorage to anchorage)", "7,650 ft (2,332 m)"]]}, "ggbstatics": {"title": "The Golden Gate Bridge (statics chapter), Table 3.2", "url": "https://www.goldengate.org/assets/1/6/ggb-exhibit-chapter-statistics1.pdf", "kind": "Published structural properties (textbook table)", "note": "Chapter by Thalia Anagnos in Sheppard and Tongue, Statics: Analysis and Design of Systems in Equilibrium (Wiley), hosted by the Bridge District. Its Table 3.2 cites the District and Abdel-Ghaffar and Scanlan (1985). The parabolic shape used in the problem is a model.", "headers": ["Quantity", "Published value"], "rows": [["Length of main span", "1280 m"], ["Maximum sag in main cable", "144 m"], ["Weight of cable per one horizontal meter", "48.7 kN/m"], ["Height of each tower", "227 m"]]}, "acc": {"title": "WHOI Polar Discovery: Antarctic circulation", "url": "https://polardiscovery.whoi.edu/antarctica/circulation-en2.html", "kind": "Published typical current speeds", "note": "Woods Hole Oceanographic Institution, Polar Discovery (2006), map caption. The companion WHOI page divediscover.whoi.edu/polar-regions/antarctic-ocean-circulation describes the current as the West Wind Drift, driven by strong westerly winds. The speed field in the problem is a model, not a measurement.", "headers": ["Quantity", "Published value"], "rows": [["Average speed of the Antarctic Circumpolar Current", "50 cm/s (1 knot)"], ["Range of speeds around Antarctica", "about 10 to 100 cm/s"]]}, "everest": {"title": "J. B. West, “Oxygenless” climbs and barometric pressure", "url": "https://publications.americanalpineclub.org/articles/12198412600", "kind": "Published field measurement", "note": "American Alpine Journal, 1984. The article reports the pressure Chris Pizzo measured on the summit of Mount Everest during the American Medical Research Expedition to Everest, October 1981, and notes it was 17 mm higher than the Standard Atmosphere predicts. 760 mm Hg is one standard atmosphere by definition.", "headers": ["Quantity", "Published value"], "rows": [["Barometric pressure on the summit, October 1981", "253 mm Hg"], ["Standard sea-level pressure (definition of 1 atm)", "760 mm Hg"]]}, "stelvio": {"title": "Südtirol tourism: Passo dello Stelvio", "url": "https://www.suedtirol.info/it/it/informazioni/mobilita/passi-in-alto-adige/passo-dello-stelvio", "kind": "Published elevations and route data", "note": "Official South Tyrol tourism site, accessed November 17, 2026. The page gives 1838 m of climbing for the 25 km bike route; the endpoint elevations below differ by 1842 m.", "headers": ["Quantity", "Published value"], "rows": [["Height of the Stelvio Pass", "2757 m"], ["Height of Prato allo Stelvio", "915 m"], ["Hairpin bends between Prato and the pass", "48"], ["Bike route length", "25 km"]]}, "earthgm": {"title": "NASA Earth Fact Sheet (gravity parameters)", "url": "https://nssdc.gsfc.nasa.gov/planetary/factsheet/earthfact.html", "kind": "Published planetary parameters", "note": "NASA NSSDC, accessed November 17, 2026. GM is the product of the gravitational constant and Earth’s mass. The real Earth is slightly flattened and rotating; the problem uses a non-rotating sphere.", "headers": ["Quantity", "Published value"], "rows": [["GM", "0.39860 million km³/s²"], ["Volumetric mean radius", "6371.000 km"], ["Mean surface gravity", "9.820 m/s²"]]}, "lightning": {"title": "National Weather Service: How powerful is lightning?", "url": "https://www.weather.gov/safety/lightning-power", "kind": "Published typical values", "note": "NOAA National Weather Service, accessed November 17, 2026. The strike frequency is from the NWS page weather.gov/safety/lightning-myths. Real flashes vary widely; the straight, steady channel in the problem is a model.", "headers": ["Quantity", "Published value"], "rows": [["Typical lightning flash current", "about 30,000 A"], ["Typical lightning flash voltage", "about 300 million V"], ["Strikes on the Empire State Building", "about 23 per year on average"]]}, "earth": {"title": "NASA Earth Fact Sheet", "url": "https://nssdc.gsfc.nasa.gov/planetary/factsheet/earthfact.html", "kind": "Published planetary parameters", "note": "NASA NSSDC Earth Fact Sheet, accessed November 17, 2026. The volumetric mean radius is the radius of a sphere with Earth’s volume; the real Earth is slightly flattened at the poles.", "headers": ["Quantity", "Published value"], "rows": [["Volumetric mean radius", "6371.000 km"], ["Obliquity to orbit (axial tilt)", "23.44°"]]}, "alma": {"title": "ALMA Memo 574: 12 m antenna optics", "url": "https://science.nrao.edu/facilities/alma/aboutALMA/Technology/ALMA_Memo_Series/alma574/memo574.pdf", "kind": "Published antenna design parameters", "note": "Sugimoto et al. (NAOJ ALMA project office), ALMA Memo 574, 2007, Table 1. The memo states that the ACA 12 m antenna shares the optics parameters of the 12 m antennas used for ALMA. The tabulated values are for the 12 m prototype design.", "headers": ["Quantity", "Published value"], "rows": [["Primary mirror diameter", "12 m"], ["Primary focal length", "4800 mm"], ["Primary focal ratio f/D", "0.4"], ["Vertex hole diameter", "750 mm"]]}, "cooling": {"title": "Niederaussem natural-draft cooling tower", "url": "https://structurae.net/en/literature/journal-article/world-s-tallest-natural-draft-cooling-tower", "kind": "Published structural dimensions", "note": "Busch, Harte, Krätzig and Montag, Structural Engineering International 11(2), 2001, describe the 200 m tower. The 152 m base diameter and 0.24 m wall thickness come from co-author W. B. Krätzig’s summary on shellbuckling.com. The narrowest radius and exact shape in the problem are assumed.", "headers": ["Quantity", "Published value"], "rows": [["Height", "200 m"], ["Base diameter", "152 m"], ["Shell wall thickness", "about 0.24 m"]]}, "zimbabwe": {"title": "Great Zimbabwe: the Conical Tower", "url": "https://en.wikipedia.org/wiki/Great_Zimbabwe", "kind": "Published approximate dimensions (secondary source)", "note": "Wikipedia’s Great Zimbabwe article, citing P. Garlake, Great Zimbabwe (1973), p. 29, gives the dimensions below. Other descriptions differ by about a metre. The top radius used in the problem is assumed.", "headers": ["Quantity", "Reported value"], "rows": [["Height", "30 ft (about 9 m)"], ["Base diameter", "18 ft (about 5.5 m)"]]}, "iter": {"title": "ITER EDA Newsletter (IAEA), October 2000", "url": "https://www-pub.iaea.org/MTCD/Publications/PDF/Newsletters/ITER-NL-9-10.pdf", "kind": "Published design parameters", "note": "International Atomic Energy Agency, ITER EDA Newsletter Vol. 9 No. 10, lists the plasma parameters below. The real plasma cross-section is D-shaped, not circular.", "headers": ["Quantity", "Published value"], "rows": [["Plasma major radius", "6.2 m"], ["Plasma minor radius", "2.0 m"], ["Plasma volume", "837 m³"]]}, "tsi2011": {"title": "A new, lower value of total solar irradiance (Kopp and Lean, 2011)", "url": "https://espo.nasa.gov/node/30086", "kind": "Published satellite measurement (peer-reviewed)", "note": "G. Kopp and J. Lean, Geophysical Research Letters 38 (2011), doi:10.1029/2010GL045777. Abstract hosted by NASA ESPO, accessed November 17, 2026: “The most accurate value of total solar irradiance during the 2008 solar minimum period is 1360.8 $\\pm$ 0.5 W m$^{-2}$.” The irradiance varies by about 0.1% over a solar cycle.", "headers": ["Quantity", "Published value"], "rows": [["Total solar irradiance at 1 au (2008 solar minimum)", "1360.8 $\\pm$ 0.5 W/m²"]]}, "sunfacts": {"title": "NASA Sun Fact Sheet", "url": "https://nssdc.gsfc.nasa.gov/planetary/factsheet/sunfact.html", "kind": "Published solar parameters", "note": "NASA NSSDC Sun Fact Sheet, accessed November 17, 2026. The luminosity is listed as $382.8\\times10^{24}$ J/s; it is used here only as a check on the flux computation.", "headers": ["Quantity", "Published value"], "rows": [["Mean distance from Earth", "$149.6\\times10^{6}$ km"], ["Luminosity", "$382.8\\times10^{24}$ J/s"]]}, "noor1": {"title": "NREL SolarPACES: NOOR I CSP Project", "url": "https://solarpaces.nlr.gov/project/noor-i", "kind": "Published plant data", "note": "NREL concentrating solar power project database (now hosted at solarpaces.nlr.gov), accessed November 17, 2026. SENER’s NOORo I fact sheet gives the matching figures 160 MWe and “1.3 Mm2 total reflective area.”", "headers": ["Quantity", "Published value"], "rows": [["Location (lat, long)", "30.994, −6.863"], ["Turbine capacity", "160 MW"], ["Solar-field aperture area", "1,308,000 m²"], ["Collector", "SenerTrough parabolic trough"], ["Thermal storage", "3 h, molten salt"], ["Expected generation", "370 GWh/year"]]}, "sentrough": {"title": "Parabolic Trough Collector Overview (Kearney, NREL Parabolic Trough Workshop 2007)", "url": "https://webarchive.library.unt.edu/eot2008/20081106024529/http://www.nrel.gov/csp/troughnet/pdfs/2007/kearney_collector_technology.pdf", "kind": "Published collector design data (workshop slides)", "note": "D. W. Kearney, NREL Parabolic Trough Workshop, March 2007, slide 11 (SENER collector), archived copy. These are SENER’s 2007 collector dimensions; that NOOR I uses exactly this geometry is an assumption.", "headers": ["Quantity", "Published value"], "rows": [["Aperture width", "5.76 m"], ["Focal length", "1.70 m"], ["Length per collector module", "12 m"], ["Length per collector assembly", "150 m"]]}, "usgsrain": {"title": "USGS Water Science School: Precipitation and the Water Cycle", "url": "https://www.usgs.gov/water-science-school/science/precipitation-and-water-cycle", "kind": "Published typical values (secondary table)", "note": "USGS table of typical raindrop properties, which USGS credits to Lull (1959), USDA Forest Service Misc. Publication 768. Values are typical, not measurements of a particular storm.", "headers": ["Precipitation type", "Intensity", "Median drop diameter", "Fall velocity"], "rows": [["Moderate rain", "0.15 in/h (0.38 cm/h)", "1.60 mm", "18.7 ft/s (5.7 m/s)"], ["Heavy rain", "0.60 in/h (1.52 cm/h)", "2.05 mm", "22.0 ft/s (6.7 m/s)"]]}, "bocci2012": {"title": "Whether or not to run in the rain (Bocci, 2012)", "url": "https://iopscience.iop.org/article/10.1088/0143-0807/33/5/1321", "kind": "Peer-reviewed physics paper (abstract)", "note": "F. Bocci, European Journal of Physics 33 (2012) 1321. The abstract states that the best strategy depends on the shape and orientation of the moving body and on the wind. No numbers from the paper are used here.", "headers": ["Item", "Value"], "rows": [["Journal", "Eur. J. Phys. 33, 1321 (2012)"], ["Main finding", "Best strategy depends on body shape, orientation, and wind"]]}, "planck2018": {"title": "Planck 2018 results VI: Cosmological parameters", "url": "https://arxiv.org/abs/1807.06209", "kind": "Published measurement (peer-reviewed)", "note": "Planck Collaboration, Astronomy and Astrophysics 641, A6 (2020). Abstract: “Hubble constant H0 = (67.4 $\\pm$ 0.5) km/s/Mpc,” assuming the base Lambda-CDM model.", "headers": ["Quantity", "Published value"], "rows": [["Hubble constant (from the cosmic microwave background)", "67.4 $\\pm$ 0.5 km/s/Mpc"]]}, "shoes2022": {"title": "A comprehensive measurement of the local value of the Hubble constant (Riess et al., 2022)", "url": "https://arxiv.org/abs/2112.04510", "kind": "Published measurement (peer-reviewed)", "note": "A. G. Riess et al. (SH0ES team), Astrophysical Journal Letters (2022), doi:10.3847/2041-8213/ac5c5b. Abstract: “Our baseline result from the Cepheid-SN sample is H0=73.04+-1.04 km/s/Mpc.”", "headers": ["Quantity", "Published value"], "rows": [["Hubble constant (Cepheids and supernovae)", "73.04 $\\pm$ 1.04 km/s/Mpc"]]}, "pdgastro": {"title": "Particle Data Group: Astrophysical constants and parameters (2016)", "url": "https://ccwww.kek.jp/pdg/2017/reviews/rpp2016-rev-astrophysical-constants.pdf", "kind": "Published unit conversion", "note": "Review of Particle Physics 2016 (mirror at KEK). Used only for the unit conversion of H0 to inverse gigayears.", "headers": ["Quantity", "Published value"], "rows": [["Hubble rate conversion", "$100h$ km/s/Mpc $= h\\times(9.777752$ Gyr$)^{-1}$"], ["Parsec", "$3.08567758149\\times10^{16}$ m"]]}, "saharadust": {"title": "NASA: Satellite reveals how much Saharan dust feeds Amazon’s plants", "url": "https://www.nasa.gov/science-research/earth-science/nasa-satellite-reveals-how-much-saharan-dust-feeds-amazons-plants/", "kind": "Published satellite-based estimates (press release)", "note": "NASA, February 2015, describing H. Yu et al., Geophysical Research Letters (2015), doi:10.1002/2015GL063040, based on CALIPSO observations 2007–2013. Values are multi-year averages; the press release says “tons,” treated here as metric tonnes.", "headers": ["Quantity", "Published value"], "rows": [["Dust carried past the western edge of the Sahara (15°W)", "182 million tons per year"], ["Still airborne near South America’s east coast (35°W)", "132 million tons per year"], ["Falling on the Amazon basin", "27.7 million tons per year"], ["Travelling past 75°W to the Caribbean", "about 43 million tons per year"]]}, "noaastations": {"title": "NOAA CO-OPS tide station metadata", "url": "https://api.tidesandcurrents.noaa.gov/mdapi/prod/webapi/stations/8723214.json", "kind": "Published station coordinates", "note": "NOAA Center for Operational Oceanographic Products and Services metadata API, accessed November 17, 2026: stations 8723214, 2695540, and 9755371 (replace the station number in the link). The stations stand in for the three cities; a flat chart and rounded vertices are modeling choices.", "headers": ["Station", "Latitude", "Longitude"], "rows": [["Virginia Key (Miami), FL", "25.7314° N", "80.1618° W"], ["Bermuda, St. Georges Island", "32.3734° N", "64.7033° W"], ["San Juan, La Puntilla, PR", "18.4589° N", "66.1164° W"]]}, "bermuda": {"title": "NOAA Ocean Service: What is the Bermuda Triangle?", "url": "https://oceanservice.noaa.gov/facts/bermudatri.html", "kind": "Published agency statement", "note": "NOAA National Ocean Service. The vertices Miami, San Juan, and Bermuda come from Vincent Gaddis’s 1964 Argosy article, as summarized in Wikipedia’s article on the Bermuda Triangle (a secondary source), which notes that later writers used other boundaries enclosing 1.3 to 3.9 million km².", "headers": ["Item", "Published statement"], "rows": [["Location", "A region in the western part of the North Atlantic Ocean"], ["Official status", "The U.S. Board on Geographic Names keeps no official file on the area"], ["Disappearances", "No evidence that they occur there with any greater frequency than elsewhere"]]}, "orange": {"title": "The Ancient Theatre Archive: Theatre at Orange (Arausio)", "url": "https://www.whitman.edu/theatre/theatretour/Orange/Orange.home.htm", "kind": "Published dimensions (academic archive)", "note": "Thomas G. Hines, Department of Theatre, Whitman College (2009). The page gives no measurement method; other descriptions give a cavea about 104 m across and an orchestra about 27 m across. The half-ring shape is a model.", "headers": ["Quantity", "Published value"], "rows": [["Seating diameter", "103.63 m"], ["Orchestra diameter", "29.9 m"], ["Seating capacity", "5,850 / 7,300"]]}, "haiyan": {"title": "JMA position table for Typhoon Haiyan (1330)", "url": "https://www.data.jma.go.jp/typhoon/data/T1330.pdf", "kind": "Published best-track values (Regional Specialized Meteorological Center Tokyo)", "note": "Japan Meteorological Agency. Winds are 10-minute averages. JMA defines the storm-force wind area as winds of 25 m/s or more and the gale area as 15 m/s or more (jma.go.jp/jma/kishou/know/typhoon/1-3.html). Agencies that use 1-minute averages reported higher peak winds.", "headers": ["Quantity (peak, Nov. 7, 21 JST to Nov. 8, 03 JST)", "Published value"], "rows": [["Central pressure", "895 hPa"], ["Maximum 10-minute wind", "65 m/s"], ["Storm-force (25 m/s) wind radius", "150 km"], ["Gale (15 m/s) wind radius", "460 km north, 330 km south"]]}, "waterpolo": {"title": "FINA Water Polo Rules 2013–2017, rule WP 3 (The Ball)", "url": "https://dunfermline-wpc.co.uk/coaches_zone/FINA_WP_Rules_2013-2017.pdf", "kind": "Published equipment rules (club-hosted copy)", "note": "FINA (now World Aquatics) rules as reproduced by Dunfermline Water Polo Club. Current World Aquatics rules move these specifications to an appendix. The thin spherical shell is a model of the ball.", "headers": ["Rule", "Published value"], "rows": [["WP 3.2 weight of the ball", "400 to 450 g"], ["WP 3.3 circumference (men)", "0.68 to 0.71 m"], ["WP 3.3 pressure (men)", "90 to 97 kPa"]]}, "agulhas": {"title": "CFOO Sea Atlas: Agulhas rings", "url": "https://cfoo.co.za/seaatlas/agulhasring.php", "kind": "Published typical properties", "note": "Centre for in situ Observational Oceanography (South Africa), Sea Atlas education pages, citing Pichevin, Nof and Lutjeharms (1999) for the drift speed. The swirl profile in the problem is a model.", "headers": ["Quantity", "Published value"], "rows": [["Rings shed per year", "about six"], ["Diameter", "200 to 280 km"], ["Depth reached", "about 1100 m"], ["Sense of rotation", "anticyclonic"], ["Drift speed", "about 5 to 8 km per day"]]}, "iersconst": {"title": "IERS useful constants", "url": "https://hpiers.obspm.fr/eop-pc/models/constants.html", "kind": "Published geodetic constants", "note": "International Earth Rotation and Reference Systems Service (Paris Observatory), accessed November 17, 2026. The nominal angular velocity is exact by definition; the measured mean value agrees to the digits shown.", "headers": ["Quantity", "Published value"], "rows": [["Nominal angular velocity of the Earth", "$7.292115146706\\times10^{-5}$ rad/s"], ["Earth’s equatorial radius", "6,378,136.6 m"]]}, "montereylat": {"title": "NOAA station 9413450, Monterey Harbor: location", "url": "https://tidesandcurrents.noaa.gov/benchmarks/9413450.html", "kind": "Published station coordinates", "note": "NOAA Tides and Currents benchmark sheet for station 9413450 (the same page as the shared tidal-datum source), accessed November 17, 2026.", "headers": ["Quantity", "Published value"], "rows": [["Station", "MONTEREY, MONTEREY HARBOR CA"], ["Latitude", "36° 36.3′ N (36.60500)"], ["Longitude", "121° 53.3′ W (−121.88800)"]]}, "qispec": {"title": "The Qi Wireless Power Transfer System, Power Class 0, Part 4: Reference Designs (v1.2.3)", "url": "https://faculty-web.msoe.edu/johnsontimoj/EE4980/files4980/Qi-PC0-part4-v1.2.3.pdf", "kind": "Published industry specification", "note": "Wireless Power Consortium, February 2017, Section 2.2.2 (Power Transmitter design A2), Table 1; copy hosted on a Milwaukee School of Engineering course page. Other Qi designs use other coils and frequencies.", "headers": ["Quantity (design A2 primary coil)", "Published value"], "rows": [["Outer diameter", "40 $\\pm$ 1 mm"], ["Inner diameter", "19 $\\pm$ 1 mm"], ["Turns", "10 per layer, 2 layers"], ["Operating frequency", "fixed, 140 kHz"]]}, "lhcdesign": {"title": "LHC Design Report, Volume I, Chapter 2: Beam parameters and definitions", "url": "https://indico.cern.ch/event/1001431/contributions/4205544/attachments/2183624/3689221/Vol_1_Chapter_2.pdf", "kind": "Published design parameters", "note": "CERN, LHC Design Report Vol. I (2004), Tables 2.1 and 2.4 (copy on CERN Indico). Collision values for 7 TeV protons.", "headers": ["Quantity", "Published value"], "rows": [["Ring circumference", "26,658.883 m"], ["Number of main bends (dipoles)", "1232"], ["Field of main bends", "8.33 T"], ["Circulating beam current", "0.582 A"], ["Bare inner vacuum screen in arcs", "36.9 mm wide, 46.5 mm high"]]}, "lhcquad": {"title": "Performance of the LHC arc superconducting quadrupoles (EPAC 2006)", "url": "https://proceedings.jacow.org/e06/PAPERS/WEPLS105.PDF", "kind": "Published magnet parameters (conference paper)", "note": "T. Tortschanoff et al. (CERN, CEA Saclay, ACCEL Instruments), Proceedings of EPAC 2006, Edinburgh, paper WEPLS105.", "headers": ["Quantity", "Published value"], "rows": [["Main arc quadrupoles fabricated", "408"], ["Nominal gradient", "223 T/m"]]}, "esacluster": {"title": "ESA Cluster: Electrifying aurorae", "url": "https://sci.esa.int/web/cluster/-/29108-electrifying-aurorae", "kind": "Published research summary", "note": "European Space Agency science pages (last updated September 1, 2019), describing Cluster satellite observations of the regions that accelerate auroral electrons.", "headers": ["Quantity", "Published description"], "rows": [["Electron energies after acceleration", "several keV (thousand electronvolts)"], ["Acceleration structures", "narrow, U-shaped, starting several thousand kilometres up"]]}, "uafelectrojet": {"title": "Alaska Science Forum: Auroral electrojets", "url": "https://gi.alaska.edu/alaska-science-forum/auroral-electrojets", "kind": "Published typical values (science column)", "note": "University of Alaska Fairbanks Geophysical Institute. Typical, storm-dependent values; the current’s geometry is far more complex than a straight line.", "headers": ["Quantity", "Published description"], "rows": [["Direction and altitude", "mostly east–west, near 100 km"], ["Current", "as large as half a million amperes"]]}, "earthheat": {"title": "Earth’s surface heat flux (Davies and Davies, 2010)", "url": "https://se.copernicus.org/articles/1/5/2010/", "kind": "Published global estimate (peer-reviewed)", "note": "J. H. Davies and D. R. Davies, Solid Earth 1, 5–24 (2010). Abstract: “Our final preferred estimate is 47$\\pm$2 TW.” The continental figures are from their preferred analysis (Section 5).", "headers": ["Quantity", "Published value"], "rows": [["Total surface heat flow", "47 $\\pm$ 2 TW"], ["Continents (preferred analysis)", "13.8 TW, mean 73 mW/m²"]]}}, "weeks": [{"week": 2, "title": "Rain, oceans, pyramids, and reservoirs", "subtitle": "A Tale of Two Orders", "skills": ["Build Riemann sums on real data grids and predict whether they over- or underestimate", "Reason about integrals without computing: sign, symmetry, linearity, and bounds", "Integrate piecewise and discontinuous functions by geometry; split a region where a formula changes", "Describe general regions in both orders, find where boundaries meet, and reverse the order (including curved boundaries)", "Use volume $=\\iint(\\text{top}-\\text{bottom})\\,dA$ and check against known formulas"], "formulas": ["$\\displaystyle\\iint_R f\\,dA\\approx\\sum_{i,j}f(x_{ij}^*,y_{ij}^*)\\,\\Delta A$", "$\\displaystyle\\iint_R f\\,dA=\\int_a^b\\!\\!\\int_c^d f\\,dy\\,dx=\\int_c^d\\!\\!\\int_a^b f\\,dx\\,dy$ on $R=[a,b]\\times[c,d]$", "$m\\le f\\le M$ on $D$ $\\Rightarrow$ $m\\cdot\\text{Area}(D)\\le\\iint_D f\\,dA\\le M\\cdot\\text{Area}(D)$", "$\\displaystyle V=\\iint_D(\\text{top}-\\text{bottom})\\,dA$"], "sources": ["imd_grid", "imd_terms", "cpc_oni", "inah_sun", "asce_gerd", "wiki_gerd", "nasa_ozone"], "problems": [{"title": "Weighing a monsoon storm on a 0.25° grid", "context": "When monsoon winds from the Arabian Sea hit the Western Ghats, India’s west-coast mountains, they can dump more than 200 mm of rain in a day. To know how much water fell, the India Meteorological Department turns readings from almost 7,000 rain gauges into a grid of 0.25° cells, one rainfall value per cell. Adding up “depth × cell area” is exactly a Riemann sum.", "model": "The grid spacing, gauge count, and rainfall categories are published. The rainfall pattern on the four cells is a model of one heavy-rain day, not data from the archive.", "sources": ["imd_grid", "imd_terms"], "work": "Sketch the $2\\times2$ block of cells with the $x$- and $y$-axes, and explain where $\\Delta A\\approx730$ km$^2$ comes from. Before computing anything, predict whether the upper-right sum will over- or underestimate, using how $d$ changes in $x$ and $y$. Mark the upper-right and midpoint sample points and classify the four midpoint values with IMD’s terms. After part (c), say in one sentence what $A(x)=\\int_0^2 d(x,y)\\,dy$ measures (draw it as a cross-section of the solid under the graph of $d$), and confirm part (c) by integrating in the other order. Did the midpoint sum over- or underestimate? Explain using the shape of $d$ in $x$.", "questions": [{"prompt": "Find the upper-right Riemann sum for the rain volume over the block, in millions of cubic metres.", "expected": "620*730/1000", "units": "million m³", "kind": "number", "tolerance": 1e-05, "hints": ["Sample d at (1,1), (1,2), (2,1), (2,2) and multiply the total by ΔA = 730 km².", "1 mm of rain on 1 km² is 1000 m³, which is 0.001 million m³."], "id": "w02-p1-a", "label": "a"}, {"prompt": "Find the midpoint Riemann sum for the rain volume, in millions of cubic metres.", "expected": "430*730/1000", "units": "million m³", "kind": "number", "tolerance": 1e-05, "hints": ["The midpoints are (0.5, 0.5), (0.5, 1.5), (1.5, 0.5), (1.5, 1.5).", "Use the same conversion: mm × km² × 0.001 gives millions of m³."], "id": "w02-p1-b", "label": "b"}, {"prompt": "Find the exact rain volume from the model with an iterated integral, in millions of cubic metres.", "expected": "440*730/1000", "units": "million m³", "kind": "number", "tolerance": 1e-05, "hints": ["In cell units, integrate d over [0,2] × [0,2]; each unit square of the (x, y) plane is one cell of 730 km².", "∫₀² x² dx = 8/3."], "id": "w02-p1-c", "label": "c"}], "solution": ["Each cell is $0.25^\\circ$ of latitude, $0.25\\times111.2\\approx27.8$ km, by $0.25^\\circ$ of longitude, $27.8\\cos19^\\circ\\approx26.3$ km, so $\\Delta A\\approx730$ km$^2$. Measuring $x$ and $y$ in cell widths, one unit square in the $(x,y)$-plane is one cell, and $\\text{mm}\\times\\text{km}^2=1000$ m$^3$.", "Because $d=50+30x^2+20y$ increases in both $x$ and $y$ on the block, the upper-right corner is the largest value on every cell, so the upper-right sum must overestimate. Its heights are $d(1,1)=100$, $d(1,2)=120$, $d(2,1)=190$, $d(2,2)=210$; the sum is $620\\times730\\times10^{-3}=452.6$ million m$^3$.", "Midpoint heights: $67.5,\\ 87.5,\\ 127.5,\\ 147.5$ mm (heavy, heavy, very heavy, very heavy). Sum: $430\\times0.73=313.9$ million m$^3$.", "Exactly, $A(x)=\\int_0^2(50+30x^2+20y)\\,dy=140+60x^2$ (the area of the cross-section at fixed $x$: rain volume per unit east–west width), and $\\int_0^2(140+60x^2)\\,dx=280+160=440$ mm·cells, so $V=440\\times0.73=321.2$ million m$^3$. Integrating in $x$ first gives $\\int_0^2(260+40y)\\,dy=440$ too.", "The midpoint sum is low by $10\\times0.73=7.3$ million m$^3$: the linear $20y$ term is integrated exactly by midpoints, but $30x^2$ is convex, and a convex function lies above its value at each cell’s midpoint on average."], "reflection": "IMD’s grid stores one value per 0.25° cell, at the grid point in its centre. Which Riemann sum is a gridded rainfall product effectively computing, and where would it be most biased?", "extension": false, "id": "w02-p1", "discussionSolution": "One value per cell, attached to the cell’s centre, makes a gridded total a midpoint sum. Midpoint sums are exact for parts of the rainfall that vary linearly across a cell, so the bias comes from curvature: near a sharp rain peak (concave down) they overestimate, and in a valley between rain bands (convex) they underestimate. The steep Western Ghats, where rain changes fastest, are where a 0.25° grid is least reliable.", "modelSpec": {"data": ["IMD grid: $0.25^\\circ\\times0.25^\\circ$ cells, built from 6955 rain gauges", "IMD terms (24-hour rainfall): heavy 64.5–115.5 mm, very heavy 115.6–204.4 mm, extremely heavy ≥ 204.5 mm"], "assume": ["A $2\\times2$ block of cells near $19^\\circ$N on the windward side of the Western Ghats", "Each cell has area $\\Delta A\\approx27.8$ km $\\times$ 26.3 km $\\approx730$ km$^2$", "Rain increases eastward toward the mountains and slightly northward; the formula is a model of one heavy-rain day"], "model": ["Rain depth: $d(x,y)=50+30x^2+20y$ mm", "$x$ = cells east of the block’s west edge, $y$ = cells north of its south edge: $0\\le x\\le2$, $0\\le y\\le2$", "Rain volume $V=\\iint d\\,dA$; 1 mm on 1 km$^2$ is 1000 m$^3$"]}, "photo": {"alt": "Monsoon clouds spilling over forested ridges of the Western Ghats near Panchgani, Maharashtra, at sunset", "credit": "Cpangarkar", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "page": "https://commons.wikimedia.org/wiki/File:Monsoon_clouds_in_Western_ghats.jpg", "file": "w02-p1.jpg"}, "figure": {"alt": "A two-by-two block of grid cells shaded by modelled rain depth, with upper-right sample points marked by crosses and midpoints by dots", "caption": "The model: rain depth $d(x,y)$ (mm) over four IMD cells of about 730 km$^2$ each. Crosses: upper-right sample points; dots: midpoints.", "file": "w02-p1"}}, {"title": "Is it El Niño? Reading the Niño 3.4 box", "context": "El Niño, the periodic warming of the tropical Pacific, shifts rain and drought from Peru to Indonesia. Forecasters decide whether one is under way from a single number: the average sea-surface temperature anomaly over a rectangle of ocean called Niño 3.4. An average is an integral divided by an area, and much can be learned about it without computing anything.", "model": "The box and the 0.5 °C threshold are NOAA definitions, and the ONI values are published. The three anomaly maps are models chosen to illustrate the reasoning, not observed fields.", "sources": ["cpc_oni"], "work": "Sketch the box in the scaled coordinates and, for $T_1$, shade where it is warm and where it is cold. Without integrating, explain the sign of its box average by comparing the warm and cold parts along each horizontal line $y=$ constant. For $T_2$, explain which terms integrate to zero and why, by pairing the points $(x,y)$ and $(-x,y)$, or $(x,y)$ and $(x,-y)$. For $T_3$, which has no elementary antiderivative, prove a chain of inequalities $m\\le T_3\\le M$ on the box, conclude $m\\le I_3\\le M$, and decide whether the bound alone proves that $T_3$ is an El Niño state.", "questions": [{"prompt": "For the developing-El Niño snapshot $T_1=1.5(x+0.3)(1-y^2)$, the Niño 3.4 index $I_1$ is", "expected": "0", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["T₁ is cold only for x < −0.3. For each fixed y, compare the cold piece with the warm piece.", "The factor 1 − y² is never negative, so it cannot change the sign on any horizontal line."], "options": ["Positive", "Negative", "Zero, because $T_1$ changes sign", "Impossible to tell without computing"], "id": "w02-p2-a", "label": "a"}, {"prompt": "For $T_2=0.9+1.6x^3-0.8y+0.6(1-x^2)$, find the index $I_2$.", "expected": "0.9+0.6*(2/3)", "units": "°C", "kind": "number", "tolerance": 1e-05, "hints": ["Over the symmetric box, the x³ and y terms cancel: pair (x, y) with (−x, y) or with (x, −y).", "The average of 1 − x² over −1 ≤ x ≤ 1 is 1 − 1/3."], "id": "w02-p2-b", "label": "b"}, {"prompt": "For the warm pool $T_3=3e^{-(x^2+y^2)/2}$, find the best constant lower bound $m$ with $T_3\\ge m$ on the whole box.", "expected": "3*exp(-1)", "units": "°C", "kind": "number", "tolerance": 1e-05, "hints": ["On the box, x² + y² is largest at the corners.", "So −(x² + y²)/2 is at least −1, and the exponential is increasing."], "id": "w02-p2-c", "label": "c"}], "solution": ["Scaled coordinates: $x=$ (degrees east of $145^\\circ$W)$/25$ and $y=$ latitude$/5^\\circ$, so the box is $B=[-1,1]\\times[-1,1]$, of area 4, and $I=\\frac14\\iint_B T\\,dA$. (Over $\\pm5^\\circ$ of latitude, $\\cos(\\text{lat})\\ge0.996$, so equal-area weighting is fine.)", "$T_1$: on each line $y=c$ with $|c|<1$, the cold part $-1\\le x<-0.3$ is a triangle of base $0.7$ and depth $1.5(0.7)(1-c^2)$, while the warm part $-0.3<x\\le1$ is a triangle of base $1.3$ and height $1.5(1.3)(1-c^2)$. The warm triangle is bigger on every line, so $I_1>0$. (Exactly, $I_1=1.5(0.3)(2/3)=0.3$: at the threshold’s edge.)", "$T_2$: $1.6x^3$ is odd in $x$ and $-0.8y$ is odd in $y$ on a box symmetric in both, so they integrate to $0$. By linearity, $I_2=0.9+0.6\\cdot\\frac12\\int_{-1}^1(1-x^2)\\,dx=0.9+0.6\\cdot\\frac23=1.3$ °C.", "$T_3$: on $B$, $0\\le x^2+y^2\\le2$, so $-1\\le-(x^2+y^2)/2\\le0$ and, since $e^s$ is increasing, $3e^{-1}\\le T_3\\le3$. Integrating, $4(3e^{-1})\\le\\iint_BT_3\\,dA\\le12$, so $1.10\\le I_3\\le3$. The lower bound alone shows $I_3>0.5$: El Niño conditions, with no antiderivative needed.", "Sharper: $e^{-s}\\ge1-s$ gives $T_3\\ge3(1-x^2/2)(1-y^2/2)$, whose average is $3(5/6)^2\\approx2.08$. A numerical value is $I_3\\approx2.20$."], "reflection": "The ONI reached 2.6 °C in late 2015. Using $T_1$ as an example, explain how a large positive box average can still hide parts of the box that were colder than normal, and why forecasters still find the average useful.", "extension": false, "id": "w02-p2", "discussionSolution": "An average is a signed integral divided by the area, so warm and cold regions cancel. In $T_1$ the western part of the box is colder than normal even though the index is positive. Forecasters use the box average because El Niño’s effects on the atmosphere respond to the broad, large-scale warming, and averaging removes small eddies that do not matter for that response.", "modelSpec": {"data": ["Niño 3.4 region: $5^\\circ$N–$5^\\circ$S, $120^\\circ$–$170^\\circ$W", "El Niño threshold: $+0.5$ °C", "Oceanic Niño Index: 2.6 °C (Nov–Jan 2015/16), 2.4 °C (1997/98), 2.0 °C (2023/24)"], "assume": ["The index is the plain area average of the anomaly over the box (latitude weighting changes it by less than 0.4%)", "The three anomaly maps $T_1,T_2,T_3$ are models, not observed fields"], "model": ["Scaled coordinates: $x=(\\text{degrees east of }145^\\circ\\text{W})/25$, $y=\\text{latitude}/5^\\circ$; box $B=[-1,1]\\times[-1,1]$", "Index: $I=\\dfrac{1}{4}\\iint_B T\\,dA$ (°C)", "$T_1=1.5(x+0.3)(1-y^2)$, $T_2=0.9+1.6x^3-0.8y+0.6(1-x^2)$, $T_3=3e^{-(x^2+y^2)/2}$"]}, "photo": {"alt": "NOAA world map of sea-surface temperature differences from average in November 2015, with a long band of warm water along the equator in the eastern Pacific", "credit": "NOAA", "license": "Public domain", "licenseUrl": "", "page": "https://commons.wikimedia.org/wiki/File:El_Ni%C3%B1o_in_November_2015.png", "file": "w02-p2.jpg"}, "figure": {"alt": "The Niño 3.4 box in the equatorial Pacific with scaled coordinates, and the warm and cold parts of the snapshot T1 shaded", "caption": "The Niño 3.4 box (left) and, in scaled coordinates, where the snapshot $T_1$ is warm or cold (right).", "file": "w02-p2"}}, {"title": "The Pyramid of the Sun, smooth and stepped", "context": "The Pyramid of the Sun at Teotihuacan, near Mexico City, was raised in the first or second century CE and is one of the largest buildings of the ancient world. It was built from earth and stone in four great stepped levels. How much material is in it? A smooth pyramid, a staircase that fits inside it, and a staircase that wraps around it give three answers, and they explain how integrals of jumpy functions are defined.", "model": "Height, base, number of levels, and the solid volume are published by INAH archaeologists. The square base, flat faces, and equal-height vertical-walled steps are models.", "sources": ["inah_sun"], "work": "Explain why the base square must be split along its diagonals to integrate the smooth height $h$: on each piece, $\\max(|x|,|y|)$ is given by a single formula. Which formula holds on which piece? Integrate over one piece, and check with a tetrahedron: the part above the triangle $|y|\\le x\\le112$ has vertices $(0,0,0)$, $(0,0,66)$, $(112,\\pm112,0)$, so its volume is $\\frac13\\cdot$(base area)$\\cdot$(height). Next, write the inscribed staircase as $h_{\\text{low}}=16.5\\,\\lfloor4(1-\\max(|x|,|y|)/112)\\rfloor$, sketch its top view, and list every point where it is discontinuous (do not miss the summit). Explain why $h_{\\text{low}}$ is integrable. Finally, with $n$ equal steps, write (upper $-$ lower) as a function of $n$ and explain why it tends to 0.", "questions": [{"prompt": "Find the volume of the smooth pyramid model.", "expected": "4/3*66*112^2", "units": "m³", "kind": "number", "tolerance": 1e-05, "hints": ["By symmetry, the base splits into 8 congruent triangles; on 0 ≤ y ≤ x ≤ 112, h = 66(1 − x/112).", "On that triangle, the inner y-integral just multiplies by the slice length x."], "id": "w02-p3-a", "label": "a"}, {"prompt": "Find the volume of the inscribed staircase, the four-level model that fits inside the smooth pyramid.", "expected": "16.5*(168^2+112^2+56^2)", "units": "m³", "kind": "number", "tolerance": 1e-05, "hints": ["Level k (k = 1, 2, 3, 4) is a square slab 16.5 m thick whose outer edge is where the smooth face reaches height 16.5k.", "Side lengths of the levels are 168, 112, 56, and 0 m; the top level is only a point."], "id": "w02-p3-b", "label": "b"}, {"prompt": "Find the volume of the circumscribed staircase, whose four levels wrap around the smooth pyramid.", "expected": "16.5*(224^2+168^2+112^2+56^2)", "units": "m³", "kind": "number", "tolerance": 1e-05, "hints": ["Level k is a square slab 16.5 m thick whose edge is where the smooth face starts that level, at height 16.5(k − 1).", "Side lengths of the levels are 224, 168, 112, and 56 m."], "id": "w02-p3-c", "label": "c"}], "solution": ["With the origin under the summit, $h(x,y)=66\\big(1-\\max(|x|,|y|)/112\\big)$ on $[-112,112]^2$. The diagonals $y=\\pm x$ split the square into 8 triangles; on $0\\le y\\le x\\le112$, $\\max(|x|,|y|)=x$.", "$\\int_0^{112}\\!\\int_0^{x}66(1-x/112)\\,dy\\,dx=66\\int_0^{112}(x-x^2/112)\\,dx=66\\cdot\\frac{112^2}{6}=137{,}984$ m$^3$, so $V=8\\times137{,}984=1{,}103{,}872$ m$^3$. Tetrahedron check: the piece over $|y|\\le x\\le112$ is two of these triangles, $\\frac13(112^2)(66)=275{,}968=2\\times137{,}984$.", "$h_{\\text{low}}$ is piecewise constant: $49.5$ m on the square $\\max(|x|,|y|)<28$ (except the summit), $33$ m out to $56$, $16.5$ m out to $84$, $0$ beyond. It jumps across the outlines $\\max(|x|,|y|)=28,56,84$, and at the single point $(0,0)$, where $\\lfloor4\\rfloor=4$ gives $66$ m while all nearby values are $49.5$ m. It is bounded and its discontinuities have zero area, so it is integrable; its integral is a sum of slabs: $16.5(168^2+112^2+56^2)=724{,}416$ m$^3$.", "The circumscribed staircase has slabs of sides $224,168,112,56$: $16.5(224^2+168^2+112^2+56^2)=1{,}552{,}320$ m$^3$. These are lower and upper sums for $h$. With $n$ steps, upper $-$ lower $=\\frac{66}{n}\\cdot224^2\\to0$, so both staircases converge to the smooth volume.", "The published “a little over 1,175,000 m$^3$” lies between the staircases and a little above the smooth pyramid, consistent with a truncated top and steep walls. Volume is proportional to the height: 63 m to 75 m changes the smooth estimate from about $1.05$ to $1.25$ million m$^3$."], "reflection": "Published heights for the pyramid range from about 63 m to 75 m. How much does that uncertainty change the volume, and is it bigger or smaller than the difference between the smooth and stepped models?", "extension": false, "id": "w02-p3", "discussionSolution": "Volume is proportional to height, so 63–75 m changes every model by about 9% either way around 69 m, roughly 0.1 million m³ either way for the smooth pyramid. That is much smaller than the gap between the two staircases (0.83 million m³) but comparable to the gap between the smooth model and the published 1.175 million m³. With four levels, the step model matters more; with many levels, the height uncertainty would dominate.", "modelSpec": {"data": ["Height today: 66.00 m", "Base: 224.00 m", "Built in 4 architectural levels", "Solid volume: a little over 1,175,000 m³"], "assume": ["A square base $224$ m on a side, centred at the origin", "Smooth model: four flat faces meeting at the summit", "Staircase models: 4 levels of equal height 16.5 m with vertical walls, one fitting inside the smooth pyramid and one wrapping around it"], "model": ["Smooth height: $h(x,y)=66\\big(1-\\max(|x|,|y|)/112\\big)$ m on $[-112,112]^2$", "Level $k$ of a staircase is a square slab from height $16.5(k-1)$ to $16.5k$", "$V=\\iint h\\,dA$"]}, "photo": {"alt": "The Pyramid of the Sun at Teotihuacan seen from the plaza, showing its stacked levels with visitors on the summit", "credit": "Daniel Case", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "page": "https://commons.wikimedia.org/wiki/File:Pyramid_of_the_Sun,_Teotihuacan,_from_path_to_parking_lot.jpg", "file": "w02-p3.jpg"}, "figure": {"alt": "Side profile of the smooth pyramid with inscribed and circumscribed four-level staircases, and a top view of the base split by its diagonals", "caption": "The models: a smooth pyramid between two four-level staircases (side view), and the base split along its diagonals (top view). Metres, to scale.", "file": "w02-p3"}}, {"title": "Filling the Grand Ethiopian Renaissance Dam", "context": "The Grand Ethiopian Renaissance Dam on the Blue Nile, a 145 m wall of concrete, feeds a 5,150 MW hydropower plant. When full, its lake covers about 1,874 km² of flooded valleys. Engineers estimate a reservoir’s volume from its shoreline and depths; here you build a model from a few published numbers and see how close it gets to the official 74 billion m³.", "model": "Area, volume, dam height, and full supply level come from ASCE; the depth at the dam and the length are secondary values. The valley shape and the sediment profile are assumptions.", "sources": ["asce_gerd", "wiki_gerd"], "work": "Sketch $D$: find where each shoreline curve meets the dam and where the two curves meet each other, and use a test point to say which curve is on top. Describe $D$ as a Type I region ($x$ outside) and as a Type II region ($y$ outside). Compute $\\iint_D 1\\,dA$ and $\\iint_D(1-x^2-|y|)\\,dA$ in both orders, confirm that the answers agree, and say which order was easier and why. For the cross-section at the dam, $\\{(y,z):|y|\\le z\\le1\\}$, explain why integrating $e^{-4z^2}$ sounding by sounding (z inside) fails, and reverse the order.", "questions": [{"prompt": "In the Type II description of $D$ ($y$ outside, $x$ inside), the right-hand limit of $x$ depends on $y$. Evaluate it at $y=0.36$: how far upstream does the lake reach along that line?", "expected": "sqrt(1-0.36)", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["Solve the shoreline equation y = 1 − x² for x.", "Keep the root with x ≥ 0: the reservoir lies upstream of the dam."], "id": "w02-p4-a", "label": "a"}, {"prompt": "Use the model to estimate the reservoir’s volume, in km³.", "expected": "8/15*(3/4*1874)*0.14", "units": "km³", "kind": "number", "tolerance": 1e-05, "hints": ["First find LW from the area: ∬_D 1 dA = 4/3 in scaled units, so the real area is (4/3)LW.", "The volume is LWH times ∬_D (1 − x² − |y|) dA, with H = 0.14 km."], "id": "w02-p4-b", "label": "b"}, {"prompt": "In the dam cross-section, find the average of $e^{-4z^2}$ over the water, that is, the mean sediment concentration as a fraction of $c_0$.", "expected": "(1-exp(-4))/4", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["Reverse the order: at height z, the water spans −z ≤ y ≤ z.", "Then substitute u = 4z². The cross-section has area 1 in scaled units."], "id": "w02-p4-c", "label": "c"}], "solution": ["The shorelines $y=\\pm(1-x^2)$ meet the dam $x=0$ at $y=\\pm1$ and each other at $x=1$, the upstream tip. At the test point $x=\\tfrac12$, the curves give $y=0.75$ and $y=-0.75$, so $1-x^2$ is the top. Type I: $0\\le x\\le1$, $-(1-x^2)\\le y\\le1-x^2$. Type II: $-1\\le y\\le1$, $0\\le x\\le\\sqrt{1-|y|}$ (from $|y|\\le1-x^2\\iff x\\le\\sqrt{1-|y|}$).", "Area: $\\int_0^1 2(1-x^2)\\,dx=\\frac43=2\\int_0^1\\sqrt{1-y}\\,dy$. Volume factor, Type I: with $c=1-x^2$, $\\int_{-c}^{c}(c-|y|)\\,dy=c^2$, and $\\int_0^1(1-x^2)^2\\,dx=1-\\frac23+\\frac15=\\frac8{15}$. Type II: $\\int_0^{\\sqrt{1-y}}(1-y-x^2)\\,dx=\\frac23(1-y)^{3/2}$, and $2\\int_0^1\\frac23(1-y)^{3/2}\\,dy=\\frac8{15}$. Type I is easier: polynomials, no square roots, and no split.", "Real area $\\frac43LW=1874$ km$^2$ gives $LW=1405.5$ km$^2$, so $V=\\frac8{15}LWH=\\frac8{15}(1405.5)(0.14)\\approx104.9$ km$^3$. Note $V=\\frac25AH$: the model’s mean depth is $0.4H=56$ m.", "The published 74 km$^3$ means a real mean depth of $74/1874\\approx39.5$ m, only $0.28H$: real reservoirs flood many shallow side valleys that the smooth model ignores, so the model overestimates by about 40%.", "Sediment: $\\int_{-1}^1\\int_{|y|}^1e^{-4z^2}\\,dz\\,dy$ has no elementary inner antiderivative. Reversed, $\\int_0^1\\int_{-z}^{z}e^{-4z^2}\\,dy\\,dz=\\int_0^1 2ze^{-4z^2}\\,dz=\\frac{1-e^{-4}}4\\approx0.245$; the cross-section area is $\\int_{-1}^1(1-|y|)\\,dy=1$, so the mean concentration is about $0.245\\,c_0$."], "reflection": "The model gives about 105 km³ against the published 74 km³. Which assumption is most responsible, and how would you change the bed shape to fix it while keeping the same area and depth at the dam?", "extension": false, "id": "w02-p4", "discussionSolution": "The smooth bed rises steadily in both directions, so most of D is fairly deep. Real reservoirs fill branching valleys whose side arms are shallow, so the mean depth is a smaller fraction of the maximum. Taking depth $=H(1-x^2-|y|)^p$ with $p>1$ keeps the same shoreline D, the same area, and the same 140 m at the dam, but makes most of the lake shallower: p = 2 gives mean depth 0.23H ≈ 32 m, so p ≈ 1.5 roughly matches the published 74 km³.", "modelSpec": {"data": ["Reservoir area when full: about 1,874 km²", "Storage at full capacity: 74 billion m³ = 74 km³", "Dam height: 145 m; depth at the dam about 140 m (secondary)", "Reservoir length up to 246 km (secondary)"], "assume": ["Scaled plan coordinates: $x$ = distance upstream $/L$, $y$ = distance across $/W$, with the dam on $x=0$", "The river bed rises like $x^2$ upstream (steeper upstream) and like $|y|$ toward the banks; $H=140$ m $=0.14$ km", "Sediment concentration at the dam falls with height above the bed as $c=c_0e^{-(z/70\\text{ m})^2}$"], "model": ["Water depth: $H(1-x^2-|y|)$ where positive; the lake is $D=\\{x\\ge0,\\ |y|\\le1-x^2\\}$", "Volume: $V=LWH\\iint_D(1-x^2-|y|)\\,dA$; area: $A=LW\\iint_D1\\,dA$", "Dam cross-section (scaled height $z$ above the lowest bed point): water fills $|y|\\le z\\le1$; concentration $c_0e^{-4z^2}$"]}, "photo": {"alt": "False-colour ASTER satellite image of the GERD reservoir filling: cyan water in a branching valley, vegetation in red, the dam at upper left", "credit": "NASA/METI/AIST/Japan Space Systems, and U.S./Japan ASTER Science Team", "license": "Public domain", "licenseUrl": "", "page": "https://commons.wikimedia.org/wiki/File:Grand_Ethiopian_Renaissance_Dam_(ASTER).jpg", "file": "w02-p4.jpg"}, "figure": {"alt": "Plan view of the scaled reservoir bounded by two parabolic shorelines and the dam, and a V-shaped cross-section at the dam shaded by sediment concentration", "caption": "The model in scaled coordinates: the lake $D$ upstream of the dam (left) and the V-shaped water cross-section at the dam, shaded by sediment concentration (right).", "file": "w02-p4"}}, {"title": "Measuring the Antarctic ozone hole on a grid", "context": "Every southern spring, a hole opens in the ozone layer over Antarctica. NASA defines it as the region where total ozone is 220 Dobson units or less and reports its area each day from satellite maps. On 21 September 2023 it reached 26.0 million km². A computer finds that area by adding up grid cells, so the answer depends on which cells count.", "model": "The 220 DU definition, the 2023 maximum area, and the 2023 minimum ozone are published. The circular hole and the 1000 km square grid are models.", "sources": ["nasa_ozone"], "work": "Find the hole’s radius $r$ from the area. Draw the circle on a grid of 1000 km cells with the South Pole at a grid corner, and shade the cells entirely inside the hole and those that touch it. Explain why the area of the hole, $\\iint\\chi\\,dA$ with $\\chi=1$ inside and $0$ outside, lies between the two counts, where $\\chi$ is discontinuous, and why the gap must shrink to 0 as the cells shrink.", "questions": [{"prompt": "With 1000 km cells, find the lower sum: the total area of the cells lying entirely inside the hole.", "expected": "16", "units": "million km²", "kind": "number", "tolerance": 1e-05, "hints": ["A cell lies inside when its corner farthest from the pole is within r ≈ 2.88 thousand km.", "By symmetry, count one quarter and multiply by 4."], "id": "w02-p5-a", "label": "a"}, {"prompt": "With 1000 km cells, find the upper sum: the total area of the cells that meet the hole.", "expected": "36", "units": "million km²", "kind": "number", "tolerance": 1e-05, "hints": ["A cell meets the hole when its corner nearest the pole is closer than r.", "In one quarter, the cell from (2, 2) to (3, 3) counts, because 2² + 2² = 8 < r² ≈ 8.28."], "id": "w02-p5-b", "label": "b"}, {"prompt": "Repeat with 500 km cells. Find (upper sum) − (lower sum).", "expected": "11", "units": "million km²", "kind": "number", "tolerance": 1e-05, "hints": ["Each cell now has area 0.25 million km²; count the cells that meet the hole but are not entirely inside.", "In one quarter there are 20 cells inside and 31 cells meeting the hole."], "id": "w02-p5-c", "label": "c"}], "solution": ["$\\pi r^2=26.0$ gives $r=\\sqrt{26/\\pi}\\approx2.877$ thousand km, so $r^2\\approx8.28$. In the model, $O=99+121(x^2+y^2)/r^2$ DU, so the 220 DU contour is the circle of radius $r$.", "1000 km cells, one quarter: cells $[i,i+1]\\times[j,j+1]$ lie inside when $(i+1)^2+(j+1)^2\\le8.28$: $(0,0),(0,1),(1,0),(1,1)$. Lower sum $=4\\times4=16$ million km$^2$. They meet the hole when $i^2+j^2<8.28$: all 9 cells with $i,j\\le2$. Upper sum $=4\\times9=36$.", "500 km cells: 20 inside and 31 meeting per quarter (80 and 124 in all), giving $20$ and $31$ million km$^2$, so the gap falls from $20$ to $11$. The gap is the area of the cells crossed by the 220 DU contour, roughly (perimeter)$\\times$(cell size), which tends to 0.", "$\\chi$ is bounded and discontinuous only on the contour, a curve of zero area, so it is integrable and every Riemann sum converges to $\\pi r^2=26.0$ million km$^2$."], "reflection": "NASA’s maps count a cell as “in the hole” when the ozone value reported for that cell is at most 220 DU. Is that more like the lower sum, the upper sum, or a midpoint sum, and why does the choice matter less on a fine grid?", "extension": true, "id": "w02-p5", "discussionSolution": "Counting a cell when its reported value is below 220 DU is like a midpoint sum of the indicator function: cells crossed by the contour count when their sample point happens to be inside. It lies between the lower and upper sums, and all three differ only on cells crossed by the contour, whose total area shrinks with the cell size. On NASA’s fine grids the difference is a small fraction of the 26 million km².", "modelSpec": {"data": ["Ozone hole: the region with total ozone ≤ 220 DU", "2023 maximum hole area: 26.0 million km² (21 September)", "2023 minimum ozone: 99 DU (3 October)"], "assume": ["The hole is a circle centred on the South Pole, on a flat map", "Ozone rises with distance from the pole as below; the grid is square, with the pole at a grid corner"], "model": ["Ozone: $O(x,y)=99+121(x^2+y^2)/r^2$ DU, with $x,y$ in thousands of km", "Hole: $O\\le220\\iff x^2+y^2\\le r^2$, with $\\pi r^2=26.0$", "Area $=\\iint\\chi\\,dA$, $\\chi=1$ in the hole and $0$ outside"]}, "figure": {"alt": "A circle representing the ozone hole drawn on a square grid of 1000 km cells centred on the South Pole", "caption": "The model hole: the 220 DU contour, a circle of area 26.0 million km², on a grid of 1000 km cells with the pole at a grid corner.", "file": "w02-p5"}}]}, {"week": 3, "title": "Dunes, tides, glaciers, and wind", "subtitle": "Life Is Like a Box of Integrals", "skills": ["Read a region from given limits and reverse the order, with curved (parabolic, cubic, sine) boundaries", "Split a region where a boundary formula changes, and combine a sum of integrals into one", "Set up triple integrals over boxes and non-box solids, inferring hidden bounds", "Project a solid onto different coordinate planes and compare the integrals", "Turn iterated limits into an inequality chain and reorder triple integrals that cannot be done as written"], "formulas": ["$\\displaystyle\\iint_D f\\,dA=\\int_a^b\\!\\!\\int_{g_1(x)}^{g_2(x)}f\\,dy\\,dx=\\int_c^d\\!\\!\\int_{h_1(y)}^{h_2(y)}f\\,dx\\,dy$", "$\\displaystyle\\iiint_E f\\,dV=\\iint_D\\Big(\\int_{\\text{floor}}^{\\text{ceiling}}f\\,dz\\Big)dA$, $D$ = shadow of $E$", "$\\bar z=\\dfrac{1}{V}\\iiint_E z\\,dV$"], "sources": ["pilat", "noaa", "aquarium", "khumbu", "turkana", "threegorges"], "problems": [{"title": "The sand mountain of Pilat", "context": "On France’s Atlantic coast near Bordeaux, the Dune du Pilat is the tallest sand dune in Europe: a 110 m wall of sand, 2.9 km long, creeping into the pine forest by a few metres every year. The sea wind pushes sand up its gentle seaward slope; the sand then avalanches down a steep slip face on the forest side. Its cross-section is a region bounded by two curves.", "model": "Width, length, height, and sand volume are published. The parabola-and-line cross-section, its flat base at sea level, and the slip-face angle are model choices.", "sources": ["pilat"], "work": "Find where the windward curve meets the slip face by solving a quadratic, and explain which root to reject. Check that the slip face slopes at about $34^\\circ$, the angle at which dry sand avalanches. Sketch the cross-section and draw one horizontal slice (order $dx\\,dy$) and one vertical slice (order $dy\\,dx$). Explain why the $dy\\,dx$ order needs two integrals: say where to split and why. A geologist computes the first moment as \\[\\int_0^4\\!\\!\\int_0^{\\sqrt x/2}y\\,dy\\,dx+\\int_4^{5.5}\\!\\!\\int_0^{(5.5-x)/1.5}y\\,dy\\,dx.\\] Sketch both pieces on one picture and combine them into a single integral in the order $dx\\,dy$.", "questions": [{"prompt": "Enter the crest (x, y) in model units.", "expected": ["4", "1"], "units": "", "kind": "vector", "tolerance": 1e-05, "hints": ["Set 4y² = 5.5 − 1.5y and solve the quadratic.", "One root is negative, below the ground; keep the other."], "id": "w03-p1-a", "label": "a"}, {"prompt": "Find the area of the cross-section, in square metres (that is, cubic metres of sand per metre of dune length).", "expected": "41/12*110^2", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["In the order dx dy, a horizontal slice at height y runs from x = 4y² to x = 5.5 − 1.5y.", "Integrate for 0 ≤ y ≤ 1, then multiply by 110² to convert model units to square metres."], "id": "w03-p1-b", "label": "b"}, {"prompt": "Find the height of the cross-section’s centroid above the base, in metres.", "expected": "15/41*110", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["Combine the geologist’s two integrals into ∫₀¹ y(5.5 − 1.5y − 4y²) dy.", "Divide by the area in model units, then convert with 1 unit = 110 m."], "id": "w03-p1-c", "label": "c"}], "solution": ["Crest: $4y^2=5.5-1.5y$ gives $8y^2+3y-11=0=(y-1)(8y+11)$, so $y=1$ or $y=-11/8$. The negative root is below the ground (the extended curves cross there), so the crest is $(4,1)$: 440 m inland, 110 m high. The slip face drops 1 unit over 1.5 units: $\\tan^{-1}(2/3)\\approx33.7^\\circ$.", "Horizontal slices run from the windward curve $x=4y^2$ to the slip face $x=5.5-1.5y$ (test $y=\\tfrac12$: $1<4.75$), so \\[A=\\int_0^1(5.5-1.5y-4y^2)\\,dy=5.5-0.75-\\tfrac43=\\tfrac{41}{12}\\] square units $\\approx41{,}342$ m$^2$ per metre of dune.", "Vertical slices have top $\\min\\!\\big(\\tfrac{\\sqrt x}2,\\tfrac{5.5-x}{1.5}\\big)$: the formula changes at the crest, $x=4$. So $A=\\int_0^4\\tfrac{\\sqrt x}2\\,dx+\\int_4^{5.5}\\tfrac{5.5-x}{1.5}\\,dx=\\tfrac83+\\tfrac34=\\tfrac{41}{12}$, the same area.", "The geologist’s two pieces are the windward and lee parts of the same region, so their sum is $\\int_0^1\\int_{4y^2}^{5.5-1.5y}y\\,dx\\,dy=\\int_0^1(5.5y-1.5y^2-4y^3)\\,dy=2.75-0.5-1=\\tfrac54$.", "Centroid height: $\\bar y=\\dfrac{5/4}{41/12}=\\dfrac{15}{41}\\approx0.366$ units $\\approx40.2$ m, a little above the $1/3$ of a triangle because the convex windward face holds extra sand high up."], "reflection": "The model cross-section times the 2.9 km length gives about 120 million m³, more than twice the published 55 million m³. Which modelling choice is most to blame? And how much sand must cross each metre of the crest per year for the dune to advance 1 m?", "extension": false, "id": "w03-p1", "discussionSolution": "The flat base at sea level: “about 110 m” is the crest’s altitude, but the dune rests on older dunes and forest ground well above sea level, so the sand is much thinner than 110 m (the dune also tapers at its ends). Advancing 1 m means moving the whole cross-section 1 m, so about 41,000 m³ of sand per metre of dune per year in the model, or roughly 19,000 m³ if we scale to the published volume (55 million m³ ÷ 2,900 m).", "modelSpec": {"data": ["Width: 600 m; length: 2,900 m", "Height: about 110 m", "Sand: 55 million m³", "The dune advances 1 to 5 m per year toward the forest"], "assume": ["A uniform cross-section along the whole length, on a flat base at sea level", "1 model unit = 110 m, both across and up", "Windward face: a parabola; slip face: a straight line"], "model": ["Cross-section: the region bounded by $x=4y^2$ (windward), $x=5.5-1.5y$ (slip face), and $y=0$ (base)", "$x$ = distance inland from the seaward toe, $y$ = height (model units)"]}, "photo": {"alt": "Aerial view of the Dune du Pilat: a long bank of pale sand between the Atlantic Ocean and a pine forest", "credit": "Mtu33260", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "page": "https://commons.wikimedia.org/wiki/File:DunePyla2.jpg", "file": "w03-p1.jpg"}, "figure": {"alt": "Cross-section of the dune: a parabolic windward face rising to the crest and a straight slip face down to the base, with one horizontal and two vertical slices", "caption": "The model cross-section (1 unit = 110 m, to scale), with a horizontal slice and vertical slices on each side of the crest.", "file": "w03-p1"}}, {"title": "Monterey Bay: a tank, a tide pool, and a hot mussel", "context": "The Monterey Bay Aquarium runs on the bay itself: its pumps draw seawater from Monterey Bay into exhibits like the Open Sea, and just outside its walls the rocks of the intertidal zone are covered and uncovered twice a day by the tide. John Steinbeck’s friend Ed Ricketts studied these shores on nearby Cannery Row. How long is a mussel on the rocks underwater, and how hot does it get when the tide is out?", "model": "Tank dimensions and capacity and the tidal datums are published. The tank’s temperature profile, the sine-shaped tide, and the mussel’s heating rate are assumptions.", "sources": ["aquarium", "noaa"], "work": "Tank: explain why $\\iiint_B1\\,dV$ is the tank’s volume, compare it with the published 1.2 million gallons ($1$ ft$^3\\approx7.48$ gal), and, before computing part (b), predict its sign from where the water is warmer or cooler than the target. Explain why all six orders give the same value. Tide: a mussel at scaled height $y$ is underwater while $\\sin\\theta>y$. Sketch the region of the integral in part (c), write it in the other order, and explain why the reversed integral is easier. Mussel: when the tide leaves it at $t=0$, its temperature rises at rate $r(s)$ (°C/h), so $T(t)-T(0)=\\int_0^t r(s)\\,ds$. Its heat dose after $\\tau$ hours is $D=\\int_0^\\tau\\!\\int_0^t r(s)\\,ds\\,dt$. By changing the order, prove $D=\\int_0^\\tau(\\tau-s)\\,r(s)\\,ds$, explain the factor $\\tau-s$ in words, and check the case $r(s)=$ constant.", "questions": [{"prompt": "Find the volume of the Open Sea tank model, in cubic feet.", "expected": "90*52*35", "units": "ft³", "kind": "number", "tolerance": 1e-05, "hints": ["The tank is a box: integrate 1 over 0 ≤ x ≤ 90, 0 ≤ y ≤ 52, 0 ≤ z ≤ 35.", "On a box, the triple integral of 1 is length × width × height."], "id": "w03-p2-a", "label": "a"}, {"prompt": "Find $\\iiint_B (T-T_0)\\,dV$ for the tank, in °C·ft³.", "expected": "90*52*0.1*(35^2/2-20*35)", "units": "°C·ft³", "kind": "number", "tolerance": 1e-05, "hints": ["The integrand depends only on z, so the x and y integrals give the factor 90 × 52.", "∫₀³⁵ (z − 20) dz is negative: the cool layer is thicker than the warm one."], "id": "w03-p2-b", "label": "b"}, {"prompt": "Find the average time underwater during one high tide, for mussels spread evenly in height between mean tide level and mean high water, in hours.", "expected": "2*12.42/(2*pi)", "units": "h", "kind": "number", "tolerance": 1e-05, "hints": ["Reverse the order: for 0 ≤ θ ≤ π/2 the height runs from 0 to sin θ.", "The band has scaled height 1, and 1 radian of tidal phase is 12.42/(2π) hours."], "id": "w03-p2-c", "label": "c"}], "solution": ["Tank: $\\iiint_B1\\,dV=90\\cdot52\\cdot35=163{,}800$ ft$^3\\approx1.225$ million gal, within about 2% of the published 1.2 million gallons (the real tank is not a perfect box).", "$T-T_0=0.1(z-20)$ is warm above $z=20$ and cool below, and the cool layer is 20 ft thick against 15 ft, so predict a negative total. On a box with a continuous integrand all orders agree (Fubini), and the integrand separates: $90\\cdot52\\cdot0.1\\int_0^{35}(z-20)\\,dz=468(612.5-700)=-40{,}950$ °C·ft$^3$, an average of $-0.25$ °C.", "Tide: scaled height above mean tide level is $\\sin\\theta$, $A=(1.412-0.333)/2\\approx0.54$ m, so $y=1$ is MHW. By symmetry about $\\theta=\\pi/2$, the time underwater at height $y$ is $2\\int_{\\arcsin y}^{\\pi/2}d\\theta$, and the band average is \\[2\\int_0^1\\!\\int_{\\arcsin y}^{\\pi/2}d\\theta\\,dy=2\\int_0^{\\pi/2}\\!\\int_0^{\\sin\\theta}dy\\,d\\theta=2\\int_0^{\\pi/2}\\sin\\theta\\,d\\theta=2\\text{ rad}.\\] As written, the inner integral leaves $\\int\\arcsin y\\,dy$, which needs integration by parts.", "2 radians of phase is $2\\cdot12.42/(2\\pi)\\approx3.95$ h out of each 12.42 h cycle.", "Heat dose: the region is $0\\le s\\le t\\le\\tau$. Reversing, for fixed $s$ the variable $t$ runs from $s$ to $\\tau$, so $D=\\int_0^\\tau\\!\\int_s^\\tau r(s)\\,dt\\,ds=\\int_0^\\tau(\\tau-s)r(s)\\,ds$: heating at time $s$ keeps the mussel warmer for the remaining $\\tau-s$ hours. For constant $r$, both sides give $r\\tau^2/2$."], "reflection": "Mussels high on the shore spend less time underwater and get longer, hotter low tides. Using the arcsin formula for time underwater, explain why a small step up the rock near mean high water costs much more underwater time than the same step near mean tide level.", "extension": false, "id": "w03-p2", "discussionSolution": "Time underwater per tide is (π − 2 arcsin y) radians, and the derivative of arcsin y is $1/\\sqrt{1-y^2}$, which blows up as y approaches 1 (mean high water). Near mean tide level (y = 0) the derivative is 1. So near the top of the band each centimetre higher removes far more underwater time, which is why zones of different species are packed tightly high on the shore.", "modelSpec": {"data": ["Open Sea exhibit: 90 ft across, 52 ft front to back, 35 ft tall; 1,200,000 US gallons", "Monterey tidal datums above MLLW: MHW 1.412 m, MTL 0.873 m, MLW 0.333 m"], "assume": ["The tank is a box $B=[0,90]\\times[0,52]\\times[0,35]$ ft, $z$ measured up from the floor", "Temperature: $T-T_0=0.1(z-20)$ °C, warm near the top and cool near the floor", "Tide: a sine wave of amplitude $A=(\\text{MHW}-\\text{MLW})/2\\approx0.54$ m about MTL, period 12.42 h", "A mussel at height $y$ is underwater whenever the water is above it"], "model": ["Tide height above MTL: $A\\sin\\theta$, phase $\\theta$ in radians (1 rad = $12.42/2\\pi$ h)", "Scaled height $y=(\\text{height}-\\text{MTL})/A$; $0\\le y\\le1$ is the band from MTL to MHW", "Average time underwater in that band: $2\\displaystyle\\int_0^1\\!\\!\\int_{\\arcsin y}^{\\pi/2}d\\theta\\,dy$"]}, "photo": {"alt": "Visitors silhouetted against the tall window of the Open Sea exhibit at the Monterey Bay Aquarium, with schools of fish in blue water", "credit": "Bill Abbott", "license": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "page": "https://commons.wikimedia.org/wiki/File:Open_Sea_exhibit_at_Monterey_Bay_Aquarium_2011.jpg", "file": "w03-p2.jpg"}, "figure": {"alt": "Left: the Open Sea tank as a box with a warm upper layer and cool lower layer. Right: one tidal cycle as a sine curve with a horizontal line at mussel height y", "caption": "Left: the tank model. Right: one high tide in scaled units; a mussel at height $y$ is underwater where the curve is above the line.", "file": "w03-p2"}}, {"title": "The ice tongue below Everest", "context": "Climbers bound for Everest pitch their tents at Base Camp on the Khumbu Glacier, a river of ice about 17 km long that flows down from the mountain and melts away at 4,900 m. Below the Khumbu Icefall, the glacier is a long tongue of ice resting in a U-shaped valley and thinning to nothing at its end. How much ice is in the tongue, and how high does it sit?", "model": "The length and elevations are secondary published values. The tongue’s length, width, thickness, parabolic valley, and flat sloping surface are assumptions in a stated model.", "sources": ["khumbu"], "work": "The ice is the solid between the valley floor $z=y^2$ and the surface $z=1-x$, with $x\\ge0$; no other bounds are given. Find the hidden bounds on $x$ and $y$. Project the solid onto the $xy$-plane: sketch the shadow $D$ and name the floor and the ceiling over it. Then project onto the $yz$-plane and onto the $xz$-plane: sketch each shadow, state the inner limits, and write the volume integral in each of the three ways. Which projection gives the easiest integral? Evaluate the volume factor two ways and confirm that the answers agree.", "questions": [{"prompt": "Find the volume of ice in the model tongue, in km³.", "expected": "10*0.5*0.3*8/15", "units": "km³", "kind": "number", "tolerance": 1e-05, "hints": ["In scaled units, the volume is ∭ 1 dV over Y² ≤ Z ≤ 1 − X with X ≥ 0; it equals 8/15.", "Multiply by L·W·H = 10 km × 0.5 km × 0.3 km."], "id": "w03-p3-a", "label": "a"}, {"prompt": "Find the area of the tongue’s footprint on the map (its shadow in the xy-plane), in km².", "expected": "10*0.5*4/3", "units": "km²", "kind": "number", "tolerance": 1e-05, "hints": ["The shadow is where the floor is below the ceiling: y² ≤ 1 − x.", "In scaled units its area is ∫₀¹ 2√(1 − x) dx; then multiply by L·W."], "id": "w03-p3-b", "label": "b"}, {"prompt": "Find the mean height of the ice above the lowest line of the valley floor, in metres.", "expected": "3/7*300", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["Compute ∭ z dV in scaled units: projecting onto the xy-plane, the inner integral is ((1 − x)² − y⁴)/2.", "Divide by the scaled volume 8/15, then multiply by H = 300 m."], "id": "w03-p3-c", "label": "c"}], "solution": ["Hidden bounds: $y^2\\le z\\le1-x$ forces $x\\le1$ and $y^2\\le1-x$, so $|y|\\le1$. Shadow on the $xy$-plane: $D=\\{0\\le x\\le1,\\ -\\sqrt{1-x}\\le y\\le\\sqrt{1-x}\\}$, floor $z=y^2$, ceiling $z=1-x$. \\[V=\\int_0^1\\!\\!\\int_{-\\sqrt{1-x}}^{\\sqrt{1-x}}(1-x-y^2)\\,dy\\,dx=\\int_0^1\\tfrac43(1-x)^{3/2}\\,dx=\\tfrac8{15}.\\]", "On the $yz$-plane the shadow is $\\{y^2\\le z\\le1\\}$ and $0\\le x\\le1-z$: $V=\\int_{-1}^1\\int_{y^2}^1(1-z)\\,dz\\,dy=\\int_{-1}^1\\tfrac{(1-y^2)^2}2\\,dy=\\tfrac8{15}$. On the $xz$-plane it is the triangle $0\\le z\\le1-x$ with $|y|\\le\\sqrt z$: $V=\\int_0^1\\int_0^{1-x}2\\sqrt z\\,dz\\,dx$. The $yz$ projection is easiest: polynomials only.", "Real size: $V=LWH\\cdot\\tfrac8{15}=10(0.5)(0.3)\\tfrac8{15}=0.8$ km$^3$. Footprint: $LW\\int_0^12\\sqrt{1-x}\\,dx=5\\cdot\\tfrac43\\approx6.67$ km$^2$.", "$\\iiint z\\,dV=\\int_0^1\\!\\int_{-c}^{c}\\tfrac{(1-x)^2-y^4}{2}\\,dy\\,dx$ with $c=\\sqrt{1-x}$; the inner integral is $\\tfrac45c^5$, so the total is $\\tfrac45\\cdot\\tfrac27=\\tfrac8{35}$. Then $\\bar z=\\tfrac{8/35}{8/15}=\\tfrac37$ of $H$, about $129$ m above the valley’s lowest line."], "reflection": "Glaciologists measure thickness at a few points with radar and the surface everywhere from satellites. Which of your three projections matches that kind of data best, and why?", "extension": false, "id": "w03-p3", "discussionSolution": "Satellites give the surface height everywhere and radar gives the bed along a few lines, so the natural data are “floor and ceiling over each map point”: the xy-projection, with thickness = ceiling − floor as the inner integral. The yz-projection was easiest for this model, but it needs the down-glacier length at each height, which is rarely measured.", "modelSpec": {"data": ["Main Khumbu Glacier: about 17 km long", "Terminus at 4,900 m; source at 7,600 m"], "assume": ["The model covers only the lower tongue below the Icefall: length $L=10$ km, half-width $W=0.5$ km at its top, centre thickness $H=300$ m there", "Coordinates follow the valley: the valley floor is level along the glacier in these coordinates"], "model": ["Scaled coordinates $x=$ distance down-glacier$/L$, $y=$ distance across$/W$, $z=$ height above the floor’s lowest line$/H$", "Ice: the solid between the parabolic valley floor $z=y^2$ and the flat ice surface $z=1-x$, with $x\\ge0$", "Real volume $=LWH\\times$(scaled volume)"]}, "photo": {"alt": "The debris-covered Khumbu Glacier filling a valley below snowy Himalayan peaks, seen between Lobuche and Gorak Shep with hikers in the foreground", "credit": "Faj2323", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "page": "https://commons.wikimedia.org/wiki/File:120410_Khumbu_Glacier_Pano.jpg", "file": "w03-p3.jpg"}, "figure": {"alt": "Three-dimensional sketch of the glacier tongue between a parabolic valley floor and a sloping flat ice surface", "caption": "The model ice tongue in scaled coordinates: floor $z=y^2$, surface $z=1-x$.", "file": "w03-p3"}}, {"title": "How much power does Lake Turkana’s wind give?", "context": "In the desert east of Lake Turkana in northern Kenya, a low-level jet of wind is funnelled between two mountains. The Lake Turkana Wind Power project, 365 turbines and the largest wind farm in sub-Saharan Africa when it was built, sits in its path. Wind power grows like the cube of the wind speed, so a farm’s average output depends on the whole spread of wind speeds, not just the average. Engineers write that average as integrals that cannot all be done in the order they are written.", "model": "Turbine count, rating, average wind speed, and estimated production are published. The Weibull wind model with shape 3, the rated speed, and the cube-law power curve are assumptions.", "sources": ["turkana"], "work": "Integral 1: sketch its region in the $(x,p)$-plane, reverse the order (watch the cube-root boundary, and do not use rectangle limits), and substitute. Integral 2: write its region as a single chain of inequalities $0\\le\\square\\le\\square\\le\\square\\le1$, and explain why it cannot be evaluated in the order written. Project the region onto the $xy$-plane and name its floor and ceiling. Reorder it with $x$ outermost, explaining the cross-section at fixed $x$, and write one more valid order, $dy\\,dz\\,dx$. Which of the two given integrals could you have done as written?", "questions": [{"prompt": "Evaluate integral 1, the share of the rated output that comes from winds below the rated speed.", "expected": "(1-exp(-1.47)*(1+1.47))/1.47", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["For fixed x, p runs from 0 to x³, so the reversed integral is ∫₀¹ x³ f(x) dx.", "Substitute u = 1.47x³; then ∫ u e^(−u) du needs integration by parts."], "id": "w03-p4-a", "label": "a"}, {"prompt": "After reordering integral 2 with x outermost, enter the integrand of the outer x-integral (without the factor 6) as a function of x.", "expected": "x^2/2*exp(-1.47*x^3)", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["At fixed x, the chain leaves 0 ≤ z ≤ y ≤ x: a triangle in the yz-plane.", "The integrand does not depend on y or z, so the inner double integral is (triangle area) × exp(−1.47x³)."], "id": "w03-p4-b", "label": "b"}, {"prompt": "Use the capacity factor from integral 2 to estimate the farm’s annual energy, in GWh.", "expected": "310*8.76*(1-exp(-1.47))/1.47", "units": "GWh", "kind": "number", "tolerance": 1e-05, "hints": ["Substitute u = 1.47x³ in 6 ∫₀¹ (x²/2) exp(−1.47x³) dx.", "Annual energy = capacity factor × 310 MW × 8760 h; 1 GWh = 1000 MWh."], "id": "w03-p4-c", "label": "c"}], "solution": ["Integral 1: $0\\le p\\le1$, $\\sqrt[3]p\\le x\\le1$ is the region below $p=x^3$. Reversed: $\\int_0^1\\int_0^{x^3}f(x)\\,dp\\,dx=\\int_0^1x^3f(x)\\,dx=\\int_0^13ax^5e^{-ax^3}\\,dx$. With $u=ax^3$: $\\frac1a\\int_0^a ue^{-u}\\,du=\\frac{1-e^{-a}(1+a)}a\\approx0.294$. (As written it also works: the inner integral is $e^{-ap}-e^{-a}$.)", "Integral 2: $0\\le z\\le1$, $z\\le y\\le1$, $y\\le x\\le1$, so $0\\le z\\le y\\le x\\le1$. The innermost $\\int_y^1e^{-ax^3}\\,dx$ has no elementary antiderivative. Shadow on the $xy$-plane: $0\\le y\\le x\\le1$, floor $z=0$, ceiling $z=y$.", "With $x$ outermost: $\\int_0^1\\int_0^x\\int_0^y e^{-ax^3}\\,dz\\,dy\\,dx$; the cross-section at fixed $x$ is the triangle $0\\le z\\le y\\le x$ of area $x^2/2$. Another valid order: $\\int_0^1\\int_0^x\\int_z^x e^{-ax^3}\\,dy\\,dz\\,dx$.", "$CF=6\\int_0^1\\frac{x^2}2e^{-ax^3}\\,dx=\\frac{1-e^{-a}}a\\approx0.524$, so the farm makes about $0.524\\times310\\times8760\\approx1{,}423$ GWh a year, close to the published estimate of 1,440 GWh."], "reflection": "The average wind speed is 11 m/s, but using it alone, a turbine rated at 14 m/s would make (11/14)³ ≈ 49% of its rating. Why is the true capacity factor larger, and which feature of the wind distribution would make it larger still?", "extension": false, "id": "w03-p4", "discussionSolution": "Power grows like the cube of speed, and the cube is convex, so by averaging over the spread of speeds, windy hours contribute much more than calm hours take away (Jensen’s inequality). In the model the cube is capped at the rating, so the capacity factor is 52%, not 49%. A distribution with more time near or above 14 m/s (a larger Weibull scale, or a narrower spread centred above rated speed) would raise it further.", "modelSpec": {"data": ["365 turbines of 0.850 MW: 310 MW", "Average wind speed: 11 m/s", "Estimated production: 1,440 GWh per year"], "assume": ["Wind speeds follow a Weibull distribution of shape 3: $P(\\text{speed}>v)=e^{-(v/c)^3}$, with $c=12.3$ m/s so that the mean is 11 m/s", "Each turbine makes $0.850\\,(v/14)^3$ MW below 14 m/s and 0.850 MW above (no cut-in or cut-out)"], "model": ["Scaled speed $x=v/14$: $P(x\\text{-speed}>x)=e^{-ax^3}$ with $a=(14/12.3)^3\\approx1.47$; density $f(x)=3ax^2e^{-ax^3}$", "Integral 1 (below-rated share): $\\displaystyle\\int_0^1\\!\\!\\int_{\\sqrt[3]p}^{1}f(x)\\,dx\\,dp$", "Integral 2 (capacity factor): $CF=6\\displaystyle\\int_0^1\\!\\!\\int_z^1\\!\\!\\int_y^1e^{-ax^3}\\,dx\\,dy\\,dz$"]}, "photo": {"alt": "A row of wind turbines on a flat gravel plain at the Lake Turkana Wind Power site in Sarima, Kenya, with a worker in a safety vest in the foreground", "credit": "Andrew Owuor", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "page": "https://commons.wikimedia.org/wiki/File:Wind_Turbines_in_Sarima_Kenya.jpg", "file": "w03-p4.jpg"}, "figure": {"alt": "Left: the model probability of exceeding each scaled wind speed. Right: the model power curve rising as the cube of speed up to the rated speed", "caption": "The wind model: chance that the scaled speed exceeds $x$ (left) and the turbine’s power curve (right).", "file": "w03-p4"}}, {"title": "Lifting ships at the Three Gorges", "context": "At China’s Three Gorges Dam on the Yangtze, the world’s largest ship lift raises boats of up to 3,000 tons straight up 113 m in a tank of water, like an elevator for ships. A smooth start matters: passengers and cargo feel changes in acceleration (jerk) more than the acceleration itself.", "model": "Basin size, lift height, and ship size are secondary published values. The counterweight-free energy estimate and the smooth-start jerk profile are assumptions.", "sources": ["threegorges"], "work": "Write the water in the basin as a box, and compute its volume as $\\iiint1\\,dV$. For the smooth start, position is a triple integral of jerk: $x(T)=\\int_0^T\\!\\int_0^t\\!\\int_0^s j(u)\\,du\\,ds\\,dt$. Write the region as an inequality chain, reorder with $u$ outermost, and show $x(T)=\\int_0^T\\frac{(T-u)^2}{2}\\,j(u)\\,du$. Check it with constant jerk.", "questions": [{"prompt": "Find the mass of water in the basin, in tonnes (1 m³ of water is 1 tonne).", "expected": "120*18*3.5", "units": "t", "kind": "number", "tolerance": 1e-05, "hints": ["The basin is a box 120 m × 18 m × 3.5 m.", "Volume in m³ equals mass in tonnes."], "id": "w03-p5-a", "label": "a"}, {"prompt": "Without counterweights, how much energy would it take to lift the full basin of water plus a 3,000 t ship by 113 m? Give megawatt-hours.", "expected": "(120*18*3.5+3000)*1000*9.81*113/(3.6*10^9)", "units": "MWh", "kind": "number", "tolerance": 1e-05, "hints": ["Work = (total mass) × g × height, with g = 9.81 m/s².", "1 MWh = 3.6 × 10⁹ J."], "id": "w03-p5-b", "label": "b"}, {"prompt": "With the smooth-start jerk profile, how far (in metres) has the basin moved when it reaches full speed?", "expected": "0.2*pi/100*1000*(pi^2-4)/(2*pi^3)", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["Reorder so u is outermost: the cross-section at fixed u is a triangle of area (T − u)²/2.", "With w = u/T, you need ∫₀¹ w² sin(πw) dw = (π² − 4)/π³."], "id": "w03-p5-c", "label": "c"}], "solution": ["Basin: $\\iiint1\\,dV=120\\cdot18\\cdot3.5=7560$ m$^3$, so 7560 t of water.", "Energy: $(7560+3000)\\times10^3\\times9.81\\times113\\approx1.17\\times10^{10}$ J $\\approx3.25$ MWh. Counterweights make the real lift nearly balanced, so the motors supply only a small part of this.", "Chain: $0\\le u\\le s\\le t\\le T$. For fixed $u$, $(s,t)$ ranges over the triangle $u\\le s\\le t\\le T$ of area $(T-u)^2/2$, so $x(T)=\\int_0^T\\frac{(T-u)^2}2j(u)\\,du$. Constant jerk $j_0$ gives $j_0T^3/6$ both ways.", "With $j(u)=j_0\\sin(\\pi u/T)$, the speed at $T$ is $j_0T^2/\\pi=0.2$, so $j_0=0.2\\pi/100$ for $T=10$ s. Then $x(T)=j_0T^3\\cdot\\frac{\\pi^2-4}{2\\pi^3}\\approx0.59$ m (after $w\\to1-w$, $\\int_0^1(1-w)^2\\sin\\pi w\\,dw=\\int_0^1w^2\\sin\\pi w\\,dw$)."], "reflection": "If the basin instead reached 0.2 m/s with constant acceleration over the same 10 s, how far would it travel, and why does the smooth start cover less distance?", "extension": true, "id": "w03-p5", "discussionSolution": "With constant acceleration a = 0.02 m/s², the distance is aT²/2 = 1 m. The smooth start accelerates gently at first, so it spends more of the 10 s moving slowly and covers only about 0.59 m.", "modelSpec": {"data": ["Ship lift basin: 120 m × 18 m × 3.5 m of water", "Vertical distance: 113 m", "Ships up to 3,000 tons"], "assume": ["No counterweights (the real lift is counterbalanced)", "Smooth start: jerk $j(u)=j_0\\sin(\\pi u/T)$ for $0\\le u\\le T=10$ s, reaching full speed 0.2 m/s at $T$"], "model": ["Position: $x(T)=\\displaystyle\\int_0^T\\!\\!\\int_0^t\\!\\!\\int_0^s j(u)\\,du\\,ds\\,dt$ (jerk, then acceleration, speed, and position)", "$g=9.81$ m/s²; water: 1 tonne per m³"]}, "figure": {"alt": "Graphs of jerk, acceleration, speed, and position against time for the smooth start of the ship lift", "caption": "The smooth start: jerk, acceleration, speed, and position over the first 10 s (each scaled to its maximum).", "file": "w03-p5"}}]}, {"week": 4, "title": "Maps that reshape the plane", "subtitle": "Stretch Marks: How Maps Distort Area", "skills": ["Find images of rectangles and squares under linear, polar, and nonlinear maps, edge by edge", "Decide whether a map is one-to-one (inverse or counterexample) and onto", "Compute Jacobians, including the polar factor r, and use |J| as a local area-scaling factor", "Change variables in a double integral: region, integrand, and area element together", "Choose between forward and inverse Jacobians; state the hypotheses of the theorem"], "formulas": ["$\\iint_D f\\,dx\\,dy=\\iint_{D^*}f(T(u,v))\\,\\left|\\dfrac{\\partial(x,y)}{\\partial(u,v)}\\right|du\\,dv$", "$\\dfrac{\\partial(x,y)}{\\partial(u,v)}=x_uy_v-x_vy_u,\\quad \\dfrac{\\partial(u,v)}{\\partial(x,y)}=1\\Big/\\dfrac{\\partial(x,y)}{\\partial(u,v)}$", "Linear map $T(\\mathbf u)=A\\mathbf u$: area is multiplied by $|\\det A|$"], "sources": ["kspivot", "graphene", "neowise", "boxmuller", "snyder", "unareas"], "problems": [{"title": "Crop circles on the Kansas plains", "context": "Fly over western Kansas and the farmland is covered with green circles. About 90% of the state’s irrigated acreage is watered by center pivots: a long sprinkler pipe on wheels that rotates around a well at its centre. The outer nozzles sweep far more ground than the inner ones, so they cannot all be the same size.", "model": "The 128-acre area and 650 gpm flow are a published worked example. A full irrigated circle, uniform depth, and the 10 ft nozzle spacing are assumptions.", "sources": ["kspivot"], "work": "Each point of the field is $T(r,\\theta)=(r\\cos\\theta,r\\sin\\theta)$ with $(r,\\theta)$ in $D^*=[0,L]\\times[0,2\\pi]$. If the pivot turns once every 24 hours, sketch the ground watered in one hour by the outer span $1100\\le r\\le L$, that is, the image of $[1100,L]\\times[0,\\pi/12]$, and say what each of the four edges of the rectangle becomes. Compute $\\partial(x,y)/\\partial(r,\\theta)$ from the $2\\times2$ determinant. Explain why the points where $T$ fails to be one-to-one do not spoil $\\iint_D dA=\\int_0^{2\\pi}\\!\\int_0^L r\\,dr\\,d\\theta$. Before part (c), predict: does the outer half of the pipe water more or less than half the field?", "questions": [{"prompt": "On $D^*=[0,L]\\times[0,2\\pi]$, which inputs share their image with a different input?", "expected": "1", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["Two inputs collide when they give the same point. What point does r = 0 give, whatever θ is?", "θ = 0 and θ = 2π point in the same direction."], "options": ["Only the inputs with $r=0$.", "All inputs with $r=0$ (they all give the pivot), and each pair $(r,0)$, $(r,2\\pi)$ (the same spoke).", "The inputs with $\\theta=\\pi$, which land on the negative $x$-axis.", "None: polar coordinates are one-to-one on this rectangle."], "id": "w04-p1-a", "label": "a"}, {"prompt": "A nozzle at distance $r$ waters the ring $r-5\\le\\rho\\le r+5$ ft. For uniform depth its flow must be the system flow times (ring area)/(field area). Enter its flow as a function of r.", "expected": "650*20*pi*r/(128*43560)", "units": "gpm", "kind": "expression", "tolerance": 1e-05, "hints": ["The ring is the image of [r − 5, r + 5] × [0, 2π]; its area is ∫∫ ρ dρ dθ = 20πr ft².", "The field is 128 × 43,560 ft², and the whole field shares 650 gpm."], "id": "w04-p1-b", "label": "b"}, {"prompt": "What fraction of the total flow goes to nozzles on the outer half of the pipe, L/2 ≤ r ≤ L?", "expected": "3/4", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["Flow is proportional to the area watered.", "Compare ∫ r dr from L/2 to L with ∫ r dr from 0 to L."], "id": "w04-p1-c", "label": "c"}], "solution": ["$L=\\sqrt{128\\cdot43{,}560/\\pi}\\approx1332$ ft. The edge $r=1100$ becomes an arc of radius 1100 ft and $r=L$ an arc of radius $L$, both through $15^\\circ$; $\\theta=0$ becomes the radial segment from 1100 to $L$ on the positive $x$-axis and $\\theta=\\pi/12$ the segment at $15^\\circ$. The image is a curved wedge of an annulus with area $\\tfrac{\\pi}{24}(L^2-1100^2)\\approx73{,}900$ ft$^2$.", "$\\dfrac{\\partial(x,y)}{\\partial(r,\\theta)}=\\det\\begin{pmatrix}\\cos\\theta&-r\\sin\\theta\\\\\\sin\\theta&r\\cos\\theta\\end{pmatrix}=r\\cos^2\\theta+r\\sin^2\\theta=r$.", "The whole edge $r=0$ collapses to the pivot, and the edges $\\theta=0$ and $\\theta=2\\pi$ land on the same spoke. Everywhere else $T$ is one-to-one. The repeated points form a single point and a segment, which have zero area, so the theorem still applies; equivalently, delete them and nothing changes.", "A nozzle serving $r-5\\le\\rho\\le r+5$ waters $\\int_0^{2\\pi}\\!\\int_{r-5}^{r+5}\\rho\\,d\\rho\\,d\\theta=20\\pi r$ ft$^2$ of the $128\\cdot43{,}560$ ft$^2$ field, so it needs $650\\cdot20\\pi r/(128\\cdot43{,}560)\\approx0.00732\\,r$ gpm, linear in $r$: about 9.5 gpm at 1300 ft but only 0.7 gpm at 100 ft.", "The outer half gets $\\int_{L/2}^L r\\,dr\\Big/\\int_0^L r\\,dr=\\dfrac{L^2-L^2/4}{L^2}=\\dfrac34$ of the water, because the factor $r$ weights the outer rings more."], "reflection": "The published guide says runoff problems usually appear at the outer edge of a pivot. Use the Jacobian to explain why the outer nozzles must pour water onto the ground faster.", "extension": false, "id": "w04-p1", "discussionSolution": "In one revolution a nozzle at radius r waters a ring of area 2πr times its width, because the area element is r dr dθ. All nozzles finish their rings in the same time, so the outer nozzles must deliver water at a rate proportional to r. If the soil cannot absorb water that fast, the extra runs off, which is why runoff shows up at the outer edge first.", "modelSpec": {"data": ["Irrigated area in the worked example: $128$ acres; $1$ acre $=43{,}560$ ft$^2$", "System flow: $650$ gpm", "Center pivots water about 90% of irrigated acreage in Kansas"], "assume": ["The irrigated area is one full circle of radius $L$, so $\\pi L^2=128\\times43{,}560$ ft$^2$ and $L\\approx1332$ ft", "Every part of the field receives the same depth of water", "Nozzles are spaced $10$ ft apart; each waters a ring $10$ ft wide centred on it", "The pipe turns once every $24$ hours"], "model": ["Polar map $T(r,\\theta)=(r\\cos\\theta,\\ r\\sin\\theta)$ on $D^*=[0,L]\\times[0,2\\pi]$", "Water per unit time is proportional to the area watered"]}, "photo": {"alt": "Satellite view of Kansas farmland packed with green center-pivot circles, some with pie-slice wedges missing, set in a grid of square fields", "credit": "NASA / USGS (Landsat)", "license": "Public domain", "licenseUrl": "", "page": "https://commons.wikimedia.org/wiki/File:Landsat_sees_crops_in_Kansas.jpg", "file": "w04-p1.jpg"}, "figure": {"alt": "Left: the parameter rectangle in the r-theta plane with a shaded strip. Right: the circular field with the corresponding shaded curved wedge and the pivot at the centre", "caption": "The polar map sends the $(r,\\theta)$ rectangle (left) onto the circular field (right). The shaded strip is the outer span $1100\\le r\\le L$ over one hour; edges are matched by colour.", "file": "w04-p1"}}, {"title": "Graphene: a hammock one atom thick", "context": "In 2004, Andre Geim and Konstantin Novoselov in Manchester peeled single layers of carbon atoms off graphite, the stuff of pencil lead, and won the 2010 Nobel Prize in Physics. The Nobel committee pictured a 1 m² graphene hammock that could hold a cat yet weigh less than one of its whiskers. That weight comes from counting atoms, one honeycomb cell at a time.", "model": "The carbon–carbon distance, the cell area, and the density are published values. A perfect, flat, defect-free lattice is the model.", "sources": ["graphene"], "work": "Find the images of the four corners of the unit square under $T$ and sketch the cell $T([0,1]^2)$. Write $T$ as a matrix. The cell is bounded by the four lines $y=0$, $y=\\tfrac{\\sqrt3}{2}a$, $y=\\sqrt3\\,x$, and $y=\\sqrt3\\,(x-a)$: show that in $(u,v)$ these become the sides of the square $0\\le u\\le1$, $0\\le v\\le1$. Explain why $T$ is one-to-one and onto $\\mathbb R^2$, compute $\\partial(u,v)/\\partial(x,y)$ for the inverse map, and check that it is the reciprocal of $\\det T$. Finally, count the carbon atoms in a 1 m² hammock.", "questions": [{"prompt": "Find the area of one unit cell of graphene (the image of the unit square), in nm².", "expected": "3*sqrt(3)/2*0.142^2", "units": "nm²", "kind": "number", "tolerance": 1e-05, "hints": ["The cell area is |det A| times the area of the unit square.", "With a = √3 × 0.142 nm, det A = (√3/2)a²."], "id": "w04-p2-a", "label": "a"}, {"prompt": "Crystallographers use the inverse map. Measuring $x$ and $y$ in units of $a$ (so $a=1$), enter $T^{-1}(x,y)=(u,v)$.", "expected": ["x-y/sqrt(3)", "2*y/sqrt(3)"], "units": "", "kind": "vector", "tolerance": 1e-05, "hints": ["Solve y = (√3/2)v for v first.", "Then x = u + v/2 gives u."], "id": "w04-p2-b", "label": "b"}, {"prompt": "Which of these maps is not one-to-one on all of the plane?", "expected": "2", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["For each map, try to solve for (u, v) from (x, y). Where can you not decide?", "For F, compare the outputs of (1, 0) and (−1, 0)."], "options": ["$T(u,v)=(u+\\tfrac12v,\\ \\tfrac{\\sqrt3}{2}v)$, the lattice map", "$S(u,v)=(u+v,\\ u-v)$", "$F(u,v)=(u^2,\\ v)$", "$G(u,v)=(u,\\ v+u^3)$"], "id": "w04-p2-c", "label": "c"}], "solution": ["$a=\\sqrt3\\times0.142=0.2460$ nm. $T(u,v)=u\\,\\mathbf a_1+v\\,\\mathbf a_2$ has matrix $A=\\begin{pmatrix}a&a/2\\\\0&\\tfrac{\\sqrt3}{2}a\\end{pmatrix}$. Corners: $(0,0)\\mapsto(0,0)$, $(1,0)\\mapsto(a,0)$, $(1,1)\\mapsto(\\tfrac32a,\\tfrac{\\sqrt3}{2}a)$, $(0,1)\\mapsto(\\tfrac a2,\\tfrac{\\sqrt3}{2}a)$: a rhombus with $60^\\circ$ and $120^\\circ$ angles.", "$\\det A=\\tfrac{\\sqrt3}{2}a^2=\\tfrac{3\\sqrt3}{2}(0.142)^2\\approx0.0524$ nm$^2$, matching the published 0.052 nm$^2$.", "With $a=1$: $v=2y/\\sqrt3$ and $u=x-v/2=x-y/\\sqrt3$. This formula works for every $(x,y)$, so $T$ is onto, and it gives only one $(u,v)$, so $T$ is one-to-one. The lines $y=0,\\ y=\\tfrac{\\sqrt3}{2}$ become $v=0,\\ v=1$, and $y=\\sqrt3x,\\ y=\\sqrt3(x-1)$ become $u=0,\\ u=1$. The inverse has $\\partial(u,v)/\\partial(x,y)=1\\cdot\\tfrac{2}{\\sqrt3}-(-\\tfrac1{\\sqrt3})\\cdot0=\\tfrac{2}{\\sqrt3}=1/\\det A$.", "$S$ has inverse $u=\\tfrac{x+y}2,\\ v=\\tfrac{x-y}2$; $G$ has inverse $u=x,\\ v=y-x^3$. Only $F$ fails: $F(1,0)=F(-1,0)=(1,0)$.", "Two atoms per cell give $2/(5.24\\times10^{-20}\\text{ m}^2)\\approx3.8\\times10^{19}$ atoms in 1 m$^2$, and at 0.77 mg per m$^2$ the hammock weighs less than a milligram."], "reflection": "A sheet of graphene and a sheet of paper both cover 1 m². Why is the cell area, the determinant of one small linear map, all you need to know to weigh the graphene sheet?", "extension": false, "id": "w04-p2", "discussionSolution": "A linear map stretches every region by the same factor |det A|, so every cell of the lattice has the same area, 0.052 nm², and holds two atoms. The number of atoms in any large sheet is its area divided by the cell area, times two, and the mass follows. The sheet of paper has no such repeating cell, so no single determinant describes it.", "modelSpec": {"data": ["Carbon–carbon distance: $0.142$ nm", "Two carbon atoms per unit cell", "Published cell area $0.052$ nm$^2$; density $0.77$ mg/m$^2$"], "assume": ["A perfect, flat, defect-free lattice"], "model": ["Lattice spacing $a=\\sqrt3\\times0.142$ nm $\\approx0.246$ nm", "Lattice vectors $\\mathbf a_1=(a,0)$ and $\\mathbf a_2=(\\tfrac a2,\\tfrac{\\sqrt3}{2}a)$", "$T(u,v)=u\\,\\mathbf a_1+v\\,\\mathbf a_2$; the unit cell is $T([0,1]^2)$"]}, "photo": {"alt": "Grey-scale atomic force microscope image of graphene showing a regular hexagonal pattern of dark holes ringed by bright carbon atoms, with a 0.5 nm scale bar", "credit": "AFM real", "license": "CC0", "licenseUrl": "http://creativecommons.org/publicdomain/zero/1.0/deed.en/", "page": "https://commons.wikimedia.org/wiki/File:Carbon_atoms_in_graphene.jpg", "file": "w04-p2.jpg"}, "figure": {"alt": "Honeycomb lattice of carbon atoms with the two lattice vectors and one rhombus-shaped unit cell shaded", "caption": "The graphene model: carbon atoms (dots) 0.142 nm apart, lattice vectors $\\mathbf a_1,\\mathbf a_2$, and one unit cell (shaded) containing two atoms.", "file": "w04-p2"}}, {"title": "Straightening the orbit of comet NEOWISE", "context": "In July 2020, comet NEOWISE was a naked-eye sight in the evening and morning skies of the Northern Hemisphere. It had passed the Sun at only 0.29 AU on July 3 and was heading back out on an orbit so stretched that it is almost a parabola. Celestial mechanicians use a remarkable map, due to Levi-Civita, that turns such orbits into straight lines.", "model": "The perihelion distance and dates are published values. Treating the orbit as an exact parabola and ignoring the planets are simplifications.", "sources": ["neowise"], "work": "Show that $T(-u,-v)=T(u,v)$; what does this say about whether $T$ is one-to-one on the plane? Writing $(u,v)=(\\varrho\\cos\\psi,\\varrho\\sin\\psi)$, show that $T$ squares the distance from the origin and doubles the angle; use this to explain why $T$ is one-to-one on the first quadrant and sends rays to rays. Find the image of each edge of the unit square $[0,1]^2$ (two are parabolas: eliminate the parameter) and sketch it. Check that the line $u=\\sqrt q$ becomes the comet’s parabola. The Sun–comet line sweeps a region $D$ from perihelion until the comet is 1 AU from the Sun; find the vertices and side equations of the region $D^*$ that $T$ maps onto $D$, choose an order of integration, and state the hypotheses of the Change of Variables Theorem and check each one.", "questions": [{"prompt": "Enter $\\dfrac{\\partial(x,y)}{\\partial(u,v)}$.", "expected": "4*(u^2+v^2)", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["x_u = 2u, x_v = −2v, y_u = 2v, y_v = 2u.", "Compute x_u y_v − x_v y_u."], "id": "w04-p3-a", "label": "a"}, {"prompt": "Find the area of the image of the unit square $[0,1]^2$.", "expected": "8/3", "units": "AU²", "kind": "number", "tolerance": 1e-05, "hints": ["Integrate 4(u² + v²) over the square.", "Each of the two terms contributes 4/3."], "id": "w04-p3-b", "label": "b"}, {"prompt": "Using Kepler’s second law, how many days after perihelion does the model comet reach 1 AU from the Sun?", "expected": "0.2947*sqrt(0.7053/0.2947)*(2*0.2947+1)/3/(pi*sqrt(2*0.2947))*365.25", "units": "days", "kind": "number", "tolerance": 1e-05, "hints": ["The swept region is the image of the triangle with vertices (0, 0), (√q, 0), (√q, √(1 − q)).", "Integrate 4(u² + v²) over it (v first), then divide by the sweep rate π√(2q) AU² per year."], "decimals": 1, "id": "w04-p3-c", "label": "c"}], "solution": ["$T(-u,-v)=((-u)^2-(-v)^2,2(-u)(-v))=T(u,v)$, so every point except the origin has two preimages: $T$ is not one-to-one on $\\mathbb R^2$. In polar form, $u^2-v^2=\\varrho^2\\cos2\\psi$ and $2uv=\\varrho^2\\sin2\\psi$: radius squared, angle doubled. On the first quadrant $0\\le\\psi\\le\\pi/2$ the doubled angle covers $[0,\\pi]$ only once, so $T$ is one-to-one there, and the ray at angle $\\psi$ goes to the ray at angle $2\\psi$.", "Edges of the unit square: $v=0\\mapsto(u^2,0)$, the segment $[0,1]$; $u=0\\mapsto(-v^2,0)$, the segment $[-1,0]$; $u=1\\mapsto x=1-y^2/4$; $v=1\\mapsto x=y^2/4-1$, for $0\\le y\\le2$. Both parabolas have their focus at the origin, where the Sun sits. In general $u=c$ gives $x=c^2-y^2/(4c^2)$, a parabola with focus at the origin and vertex $(c^2,0)$, so $u=\\sqrt q$ is the comet’s orbit with perihelion $(q,0)$.", "$J=(2u)(2u)-(-2v)(2v)=4(u^2+v^2)\\ge0$, zero only at the origin. Area of the image of the square: $\\int_0^1\\!\\int_0^1 4(u^2+v^2)\\,du\\,dv=\\tfrac43+\\tfrac43=\\tfrac83$ AU$^2$.", "Distance from the Sun is $x^2+y^2=(u^2+v^2)^2$, so $r=u^2+v^2$. On the orbit $u=\\sqrt q$, $r=1$ gives $v=\\sqrt{1-q}$. The Sun–perihelion segment comes from $v=0$, the orbit arc from $u=\\sqrt q$, and the Sun–comet segment from the ray $v=ku$ with $k=\\sqrt{(1-q)/q}$. So $D^*$ is the triangle $0\\le u\\le\\sqrt q,\\ 0\\le v\\le ku$. Hypotheses: $T$ is $C^1$, one-to-one on the first quadrant, $T(D^*)=D$, and $J\\ne0$ except at one point.", "Area $=\\int_0^{\\sqrt q}\\!\\int_0^{ku}4(u^2+v^2)\\,dv\\,du=\\int_0^{\\sqrt q}4u^3(k+k^3/3)\\,du=q^2(k+k^3/3)=\\tfrac{qk(2q+1)}{3}\\approx0.2416$ AU$^2$ for $q=0.2947$. Dividing by $\\pi\\sqrt{2q}\\approx2.412$ AU$^2$/yr gives $0.1001$ yr $\\approx36.6$ days, so the model reaches 1 AU around August 9; JPL’s ephemeris gives 36.60 days."], "reflection": "JPL’s ephemeris puts the real NEOWISE 1 AU from the Sun about 36.60 days after perihelion, within an hour of the model. The real orbit is an ellipse that takes about 6800 years to go around. Why does a parabola work so well here, and where would it fail badly?", "extension": false, "id": "w04-p3", "discussionSolution": "Near the Sun the speed is set by v² = GM(2/r − 1/a). With a ≈ 358 AU, the term 1/a ≈ 0.003 per AU is tiny next to 2/r ≥ 2 per AU, so inside 1 AU the ellipse and the parabola differ by about 0.1% in speed, and the sweep rates agree almost exactly. Far from the Sun the two curves part ways: the parabola escapes to infinity, while the real comet turns around about 717 AU out and returns in some 6800 years.", "modelSpec": {"data": ["Perihelion distance of NEOWISE: $q=0.2947$ AU", "Eccentricity $0.99918$; perihelion 2020 July 3.68"], "assume": ["The orbit is an exact parabola with the Sun at its focus; the planets’ pulls are ignored", "Kepler’s second law: the Sun–comet line sweeps area at the constant rate $\\pi\\sqrt{2q}$ AU$^2$ per year (this uses $GM_\\odot=4\\pi^2$ AU$^3$/yr$^2$)", "1 year $=365.25$ days"], "model": ["Sun at the origin, perihelion at $(q,0)$, distances in AU", "Levi-Civita map $T(u,v)=(u^2-v^2,\\ 2uv)$", "Swept region $D$: bounded by the Sun–perihelion segment, the orbit, and the Sun–comet segment when the comet is $1$ AU from the Sun"]}, "photo": {"alt": "Comet NEOWISE against a starry sky, with a bright greenish head, a broad cream-coloured dust tail, and a faint, narrow blue ion tail", "credit": "Davrou (David Rousseau)", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "page": "https://commons.wikimedia.org/wiki/File:2020-07-21_-_Neowise_-_D_Rousseau.jpg", "file": "w04-p3.jpg"}, "figure": {"alt": "Left: the uv-plane with the vertical line u equals root q. Right: the xy-plane with the Sun at the origin, the parabolic orbit through perihelion, the 1 AU circle, and the shaded region swept by the Sun–comet line", "caption": "The model: in the $uv$-plane the line $u=\\sqrt q$ (left); in the $xy$-plane the comet’s parabola with the Sun at its focus and the region $D$ swept from perihelion until the comet is 1 AU from the Sun (right).", "file": "w04-p3"}}, {"title": "How a computer makes bell curves", "context": "Weather ensembles, bank stress tests, and simulated particle collisions all need random numbers that follow the bell-shaped normal distribution, but a computer’s basic generator only produces numbers spread evenly between 0 and 1. In 1958 George Box and Mervin Muller found a short recipe that bends a uniform square into a perfect two-dimensional bell curve. It is a change of variables.", "model": "The transformation is the published Box–Muller method. Treating the computer’s uniform numbers as truly random is an idealization.", "sources": ["boxmuller"], "work": "Write the inverse map $(x,y)\\mapsto(u,v)$ (use polar coordinates of $(x,y)$). Say where the map fails to be one-to-one on $(0,1]\\times[0,1]$ and why that is harmless, and note what happens to $T(u,v)$ as $u\\to0$. Explain the probability rule: the chance that $T(u,v)$ lands in a region $D$ equals the area of the preimage $D^*$, and write that area as $\\iint_D\\left|\\partial(u,v)/\\partial(x,y)\\right|dx\\,dy$, transforming region, integrand, and area element together. Then scale: $X=\\sigma_1x$, $Y=\\sigma_2y$ multiplies areas by $\\sigma_1\\sigma_2$. Use this diagonal scaling and then polar coordinates to show that the chance of landing in the error ellipse $X^2/\\sigma_1^2+Y^2/\\sigma_2^2\\le4$ is the same as in part (c).", "questions": [{"prompt": "Enter the forward Jacobian $\\dfrac{\\partial(x,y)}{\\partial(u,v)}$ (it may be negative).", "expected": "-2*pi/u", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["x_u = −cos(2πv)/(u√(−2 ln u)) and x_v = −2π√(−2 ln u) sin(2πv).", "The sine and cosine terms combine into one term with no square root left."], "id": "w04-p4-a", "label": "a"}, {"prompt": "The points $(x,y)$ have density $\\left|\\dfrac{\\partial(u,v)}{\\partial(x,y)}\\right|$. Enter it as a function of x and y.", "expected": "exp(-(x^2+y^2)/2)/(2*pi)", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["The inverse Jacobian is the reciprocal of the forward one, with an absolute value.", "Write u in terms of x and y: x² + y² = −2 ln u."], "id": "w04-p4-b", "label": "b"}, {"prompt": "What is the probability that a generated point lies within distance 2 of the origin?", "expected": "1-exp(-2)", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["The disk x² + y² ≤ 4 comes from the strip u ≥ e^(−2) of the unit square.", "Or integrate the density in polar coordinates out to r = 2."], "id": "w04-p4-c", "label": "c"}], "solution": ["With $R=\\sqrt{-2\\ln u}$: $x_u=-\\dfrac{\\cos2\\pi v}{uR}$, $x_v=-2\\pi R\\sin2\\pi v$, $y_u=-\\dfrac{\\sin2\\pi v}{uR}$, $y_v=2\\pi R\\cos2\\pi v$, so $\\dfrac{\\partial(x,y)}{\\partial(u,v)}=-\\dfrac{2\\pi}{u}(\\cos^2+\\sin^2)=-\\dfrac{2\\pi}{u}$. The minus sign means orientation is reversed; area scaling uses $2\\pi/u$.", "Inverse: $u=e^{-(x^2+y^2)/2}$, $v=\\theta/(2\\pi)$ where $\\theta$ is the polar angle of $(x,y)$. The map is one-to-one except that $u=1$ sends every $v$ to the origin and $v=0$, $v=1$ give the same ray: zero area. As $u\\to0$ the radius $\\sqrt{-2\\ln u}\\to\\infty$, so the image is the whole plane (an improper region).", "By the reciprocal rule, $\\left|\\dfrac{\\partial(u,v)}{\\partial(x,y)}\\right|=\\dfrac{u}{2\\pi}=\\dfrac{1}{2\\pi}e^{-(x^2+y^2)/2}=\\dfrac{e^{-x^2/2}}{\\sqrt{2\\pi}}\\cdot\\dfrac{e^{-y^2/2}}{\\sqrt{2\\pi}}$: two independent standard normal numbers.", "$P=\\iint_{x^2+y^2\\le4}\\dfrac{e^{-(x^2+y^2)/2}}{2\\pi}dA=\\int_0^{2\\pi}\\!\\int_0^2\\dfrac{e^{-r^2/2}}{2\\pi}r\\,dr\\,d\\theta=1-e^{-2}\\approx0.865$. Equivalently, the preimage is $e^{-2}\\le u\\le1$, of area $1-e^{-2}$.", "For the ellipse, $X=\\sigma_1x$, $Y=\\sigma_2y$ has $J=\\sigma_1\\sigma_2$, and the density $\\dfrac{1}{2\\pi\\sigma_1\\sigma_2}e^{-(X^2/\\sigma_1^2+Y^2/\\sigma_2^2)/2}$ times $\\sigma_1\\sigma_2$ returns the disk integral above: again $1-e^{-2}$. A two-dimensional “2-sigma” ellipse holds only 86.5%, not the familiar one-dimensional 95%."], "reflection": "The forward Jacobian was negative. Why does the probability density use its absolute value, and what would go wrong without it?", "extension": false, "id": "w04-p4", "discussionSolution": "Probability, like area, cannot be negative. The sign of the Jacobian only records that the map reverses orientation (it flips the square over as it bends it). Without the absolute value the density would be negative and the total probability would come out as −1.", "modelSpec": {"data": ["Box–Muller: from uniform $u,v$ in $(0,1)$, $x=\\sqrt{-2\\ln u}\\cos2\\pi v$, $y=\\sqrt{-2\\ln u}\\sin2\\pi v$"], "assume": ["$(u,v)$ is spread uniformly over the unit square, so the probability of a set of inputs is its area"], "model": ["$T(u,v)=(x,y)$ on $(0,1]\\times[0,1]$", "Probability that $T(u,v)\\in D$ equals the area of the set of $(u,v)$ that land in $D$"]}, "figure": {"alt": "Left: a unit square with vertical strips of equal width. Right: the plane with circles that the strips map to, crowded near the origin", "caption": "Equal-area strips of the $(u,v)$ square (left) become the rings and wedges of the plane (right); rings near the centre are thin, so points crowd there.", "file": "w04-p4"}}, {"title": "Why Greenland looks as big as Africa", "context": "On the familiar Mercator world map, Greenland looks about as large as Africa, yet the Democratic Republic of the Congo alone, on the equator, is slightly bigger than Greenland. Gerardus Mercator designed his map so that sailors could steer by straight lines, and that choice stretches areas near the poles.", "model": "Projection formulas and areas are published values. A spherical Earth and one representative latitude for Greenland are simplifications.", "sources": ["snyder", "unareas"], "work": "With $R=1$, the sphere’s area element at longitude $\\lambda$ and latitude $\\phi$ is $\\cos\\phi\\,d\\lambda\\,d\\phi$. Explain why the ratio (map Jacobian)/$\\cos\\phi$ is the map’s area scale factor. Is the Mercator map one-to-one on $(-\\pi,\\pi)\\times(-\\pi/2,\\pi/2)$, and what happens to the poles? Repeat the Jacobian calculation for the cylindrical equal-area map $x=\\lambda$, $y=\\sin\\phi$ and explain its name.", "questions": [{"prompt": "Enter the Mercator Jacobian $\\dfrac{\\partial(x,y)}{\\partial(\\lambda,\\phi)}$ as a function of phi.", "expected": "1/cos(phi)", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["x = λ does not depend on φ, so only y_φ matters.", "d/dφ of ln tan(π/4 + φ/2) simplifies to sec φ."], "id": "w04-p5-a", "label": "a"}, {"prompt": "By what factor does the Mercator map enlarge areas at latitude $72^\\circ$?", "expected": "1/cos(72*pi/180)^2", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["Divide the Jacobian by the sphere’s factor cos φ.", "sec² 72° is about 10."], "id": "w04-p5-b", "label": "b"}, {"prompt": "Placing Greenland at latitude 72° and DR Congo at the equator, how many times larger than DR Congo does Greenland appear on the Mercator map?", "expected": "2166086/cos(72*pi/180)^2/2344858", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["Multiply each true area by its areal scale factor.", "At the equator the factor is 1."], "id": "w04-p5-c", "label": "c"}], "solution": ["$x_\\lambda=1$, $x_\\phi=0$, $y_\\lambda=0$, and $y_\\phi=\\dfrac{\\tfrac12\\sec^2(\\pi/4+\\phi/2)}{\\tan(\\pi/4+\\phi/2)}=\\dfrac{1}{\\sin(\\pi/2+\\phi)}=\\sec\\phi$, so $J=\\sec\\phi$.", "A small patch of Earth has area $\\cos\\phi\\,\\Delta\\lambda\\,\\Delta\\phi$ and its image has area about $|J|\\,\\Delta\\lambda\\,\\Delta\\phi$, so areas are scaled by $\\sec\\phi/\\cos\\phi=\\sec^2\\phi$, as Snyder states. At $72^\\circ$ this is $\\approx10.47$. The map is one-to-one on the open rectangle, but $y\\to\\pm\\infty$ at the poles, which never appear.", "Apparent ratio: $\\dfrac{2{,}166{,}086\\times10.47}{2{,}344{,}858\\times1}\\approx9.7$. Greenland looks almost ten times larger than DR Congo, although it is about 8% smaller.", "For $y=\\sin\\phi$, $J=\\cos\\phi$, exactly the sphere’s factor: the areal scale is 1 everywhere, so the map is equal-area (at the price of squashed shapes near the poles)."], "reflection": "Mercator’s map preserves angles, which made it ideal for navigation. Can a map from the sphere to the plane preserve both angles and areas? What does the Jacobian say?", "extension": true, "id": "w04-p5", "discussionSolution": "No. A map that preserves angles stretches lengths equally in all directions at each point, by some factor k, so it multiplies area by k². Preserving area too would force k = 1, so the map would preserve all lengths, and a sphere cannot be flattened without changing lengths (its curvature is not zero). Every world map must trade shape against area.", "modelSpec": {"data": ["Greenland: $2{,}166{,}086$ km$^2$; Democratic Republic of the Congo: $2{,}344{,}858$ km$^2$", "Mercator (sphere): $x=R\\lambda$, $y=R\\ln\\tan(\\pi/4+\\phi/2)$", "Cylindrical equal-area: $x=R\\lambda$, $y=R\\sin\\phi$"], "assume": ["Earth is a sphere; take $R=1$", "Greenland is represented by latitude $72^\\circ$ N and DR Congo by the equator"], "model": ["Map $(\\lambda,\\phi)\\mapsto(x,y)$ on $-\\pi<\\lambda<\\pi$, $-\\pi/2<\\phi<\\pi/2$", "Sphere area element: $\\cos\\phi\\,d\\lambda\\,d\\phi$"]}, "figure": {"alt": "Mercator grid of meridians and parallels every 15 degrees; the parallels spread apart toward the poles. Bands for the latitudes of Greenland and DR Congo are shaded", "caption": "Mercator’s map with parallels every $15^\\circ$: they spread apart toward the poles. Shaded: the latitude bands of Greenland and of DR Congo.", "file": "w04-p5"}}]}, {"week": 5, "title": "Balance points and blind spots", "subtitle": "The Balancing Act", "skills": ["Find centers of mass of planar regions using symmetry, vertex averages, and moments", "Predict how a non-uniform density moves the balance point, then compute", "Set up cones and spheres in cylindrical and spherical coordinates, in more than one order", "Derive the volume factors r and ρ² sin φ and use them for volumes, masses, and moments", "Evaluate improper integrals by exhaustion, and decide convergence of power laws in 1, 2, and 3 dimensions"], "formulas": ["$\\bar x=\\dfrac{1}{M}\\iint x\\,\\delta\\,dA,\\quad \\bar y=\\dfrac{1}{M}\\iint y\\,\\delta\\,dA,\\quad M=\\iint\\delta\\,dA$", "Cylindrical: $dV=r\\,dr\\,d\\theta\\,dz$. Spherical: $x=\\rho\\sin\\phi\\cos\\theta,\\ y=\\rho\\sin\\phi\\sin\\theta,\\ z=\\rho\\cos\\phi$", "$\\iint_{\\mathbb R^2}f\\,dA=\\lim\\iint_{D_n}f\\,dA$ for regions $D_n$ that exhaust the plane"], "sources": ["gatewayarch", "earthfacts", "fmiradar", "walker1977", "taipeidamper"], "problems": [{"title": "The Gateway Arch balances on thin air", "context": "The Gateway Arch in St. Louis is a stainless-steel curve 630 feet tall and 630 feet wide, the tallest arch in the world. Its legs are triangular in cross-section, tapering from 54 feet per side at the ground to 17 feet at the top. Where is its center of mass? Not inside the steel.", "model": "The width, height, and taper are published values. The parabolic outlines and the thickness-weighted density are models.", "sources": ["gatewayarch"], "work": "Without integrating, explain why $\\bar x=0$ for both densities. The NPS says each leg’s cross-section is an equilateral triangle with 54 ft sides at the base: place it with vertices $(0,0)$, $(54,0)$, $(27,27\\sqrt3)$ and locate its centroid by averaging the vertices, with no integrals. Describe the arch region $A$ as (region under the outer curve) minus (region under the inner curve), and explain how that turns its moments into differences. Before computing part (c), predict: will the tapering legs move $\\bar y$ up or down compared with part (b)? Finally, sketch the arch with your $\\bar y$ marked and explain how a body can balance at a point where it has no material.", "questions": [{"prompt": "For the uniform region under $y=h(1-x^2/w^2)$, above $y=0$, enter $\\bar y$ as a function of h and w.", "expected": "2*h/5", "units": "ft", "kind": "expression", "tolerance": 1e-05, "hints": ["Mass: ∫ h(1 − x²/w²) dx over [−w, w] = 4hw/3.", "Moment: ∫ (1/2)h²(1 − x²/w²)² dx = 8h²w/15."], "id": "w05-p1-a", "label": "a"}, {"prompt": "Find $\\bar y$ for the uniform arch region $A$.", "expected": "2/5*(630^2*315-613^2*261)/(630*315-613*261)", "units": "ft", "kind": "number", "tolerance": 1e-05, "hints": ["Subtract the inner region’s mass and moment from the outer region’s.", "Mass of each region: 4hw/3. Moment of each: 8h²w/15."], "id": "w05-p1-b", "label": "b"}, {"prompt": "Now weight the arch by its leg thickness, $\\delta=54-\\tfrac{37}{630}y$. Find $\\bar y$.", "expected": "406441825784/1768433009", "units": "ft", "kind": "number", "tolerance": 1e-05, "hints": ["You need ∬ y^k dA over each parabolic region for k = 0, 1, 2; for the region under y = h(1 − x²/w²) these are 4wh/3, 8wh²/15, and 32wh³/105.", "Then M = 54·(k=0 term) − (37/630)·(k=1 term), with the inner region subtracted, and similarly for the moment."], "decimals": 1, "id": "w05-p1-c", "label": "c"}], "solution": ["Reflection $x\\mapsto-x$ maps the arch to itself and leaves $\\delta$ (which depends only on $y$) unchanged, so $x\\delta$ is odd and $\\bar x=0$. Triangle centroid: $\\big(\\tfrac{0+54+27}{3},\\tfrac{0+0+27\\sqrt3}{3}\\big)=(27,9\\sqrt3)\\approx(27,15.6)$ ft, one third of the way up from the base.", "Region under $y=h(1-x^2/w^2)$: $M=\\int_{-w}^{w}h(1-\\tfrac{x^2}{w^2})dx=\\tfrac43hw$ and $M_x=\\int_{-w}^{w}\\tfrac12h^2(1-\\tfrac{x^2}{w^2})^2dx=\\tfrac{8}{15}h^2w$, so $\\bar y=\\tfrac25h$ whatever the width $w$.", "Since $A$ is the outer region with the inner region removed, $M_A=\\tfrac43(630\\cdot315-613\\cdot261)=51{,}276$ and $M_{x,A}=\\tfrac8{15}(630^2\\cdot315-613^2\\cdot261)\\approx1.4373\\times10^7$, giving $\\bar y\\approx280.3$ ft. At $x=0$ the steel lies between 613 and 630 ft, so the balance point is in the empty space under the arch.", "The legs are thickest at the ground, so the weighting favours low points and $\\bar y$ should drop. With $\\iint y^k\\,dA$ equal to $\\tfrac43wh,\\ \\tfrac8{15}wh^2,\\ \\tfrac{32}{105}wh^3$ for $k=0,1,2$ on each region, $M=\\iint(54-\\tfrac{37}{630}y)\\,dA$ and $M_x=\\iint y(54-\\tfrac{37}{630}y)\\,dA$ give $\\bar y\\approx229.8$ ft: about 50 ft lower."], "reflection": "Real arches have a centroid curve that passes through the center of each cross-section, and the NPS also says the legs are filled with concrete up to 300 ft. Would that concrete move the balance point further down, and why does an arch builder care where the weight is?", "extension": false, "id": "w05-p1", "discussionSolution": "Concrete low in the legs adds weight near the ground, so it lowers the balance point further. A low center of mass makes the structure more stable against wind loads, and builders need the weight distribution to size the foundations and to plan the order in which segments are added so the half-finished legs do not tip.", "modelSpec": {"data": ["Outer width $630$ ft; maximum height $630$ ft", "Leg cross-section: equilateral triangle, $54$ ft per side at the base and $17$ ft at the top"], "assume": ["Outer edge: the parabola $y=630(1-x^2/315^2)$", "Inner edge: the parabola $y=613(1-x^2/261^2)$ (legs 54 ft wide at the ground, 17 ft thick at the top)", "Part (c): areal density proportional to leg thickness, falling linearly from 54 at $y=0$ to 17 at $y=630$"], "model": ["The arch is the lamina $A$ between the two parabolas, above $y=0$ (feet)", "Uniform density for part (b); $\\delta=54-\\tfrac{37}{630}y$ for part (c)"]}, "photo": {"alt": "The stainless-steel Gateway Arch against a blue sky, its legs tapering toward the top, with visitors walking on a path beneath it", "credit": "Lewis Hulbert", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "page": "https://commons.wikimedia.org/wiki/File:Gateway_Arch,_St._Louis.jpg", "file": "w05-p1.jpg"}, "figure": {"alt": "Elevation view of the arch modelled as the band between two parabolas, with the leg cross-section triangle shown as an inset", "caption": "The model arch: the band between the outer parabola (630 ft tall and wide) and the inner one. Inset: a leg’s equilateral cross-section, 54 ft per side at the base.", "file": "w05-p1"}}, {"title": "Weighing Earth’s core without digging", "context": "No borehole has come anywhere near the centre of a planet whose radius is 6371 km. Yet we know Earth’s centre is far denser than any rock at the surface. Two numbers measured from outside, Earth’s mass and how hard it is to change the direction of its spin (its moment of inertia), are enough to show it.", "model": "The mass, radius, mean density, and moment-of-inertia factor are published values. The quadratic density profile is a model; the real Earth has distinct layers.", "sources": ["earthfacts"], "work": "Derive the spherical volume factor: a small box with sides $\\Delta\\rho$, $\\Delta\\phi$, $\\Delta\\theta$ has edges of length $\\Delta\\rho$, $\\rho\\Delta\\phi$, and $\\rho\\sin\\phi\\,\\Delta\\theta$ (why?). Then explain why, for a density that depends only on $\\rho$, every mass or moment integral over the ball reduces to a single $\\rho$-integral times an angular factor. Check the model on a uniform ball: what is $I/(MR^2)$? Is the measured 0.3308 bigger or smaller, and what does that say about where Earth’s mass is? Finally, as a cross-check on the published data, compute the work needed to lift 1 kg from the surface to infinity, $\\int_R^\\infty GM/r^2\\,dr$; explain why this improper integral converges and recover the escape speed.", "questions": [{"prompt": "Measure distances in Earth radii ($R=1$). Enter the mass of the ball $\\rho\\le1$ with density $a-b\\rho^2$ as a function of a and b.", "expected": "4*pi*(a/3-b/5)", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["dV = ρ² sin φ dρ dφ dθ, and the angles contribute 4π.", "∫₀¹ (a − bρ²)ρ² dρ = a/3 − b/5."], "id": "w05-p2-a", "label": "a"}, {"prompt": "Enter the model’s moment-of-inertia factor $I/(MR^2)$ about the spin axis as a function of a and b.", "expected": "2/3*(a/5-b/7)/(a/3-b/5)", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["The distance to the axis is ρ sin φ, so I = ∭ (a − bρ²) ρ² sin²φ · ρ² sin φ dρ dφ dθ.", "∫₀^π sin³φ dφ = 4/3."], "id": "w05-p2-b", "label": "b"}, {"prompt": "Choose a and b to match the published mean density 5513 kg/m³ and moment-of-inertia factor 0.3308. What central density a does the model give, in g/cm³?", "expected": "5.513/(1-3*0.79326608/5)", "units": "g/cm³", "kind": "number", "tolerance": 1e-05, "hints": ["The factor depends only on k = b/a; solve (2/3)(1/5 − k/7)/(1/3 − k/5) = 0.3308 for k.", "Mean density = M/V = 3(a/3 − b/5) = a(1 − 3k/5)."], "decimals": 1, "id": "w05-p2-c", "label": "c"}], "solution": ["The box’s edges are a radial step $\\Delta\\rho$, an arc $\\rho\\Delta\\phi$ of a circle of radius $\\rho$, and an arc $\\rho\\sin\\phi\\,\\Delta\\theta$ of a circle of radius $\\rho\\sin\\phi$ (the distance to the $z$-axis), so $dV=\\rho^2\\sin\\phi\\,d\\rho\\,d\\phi\\,d\\theta$. For a density depending only on $\\rho$, the angles separate and contribute $\\int_0^{2\\pi}\\!\\int_0^\\pi\\sin\\phi\\,d\\phi\\,d\\theta=4\\pi$.", "$M=4\\pi\\int_0^1(a-b\\rho^2)\\rho^2\\,d\\rho=4\\pi(\\tfrac a3-\\tfrac b5)$. $I=\\int_0^{2\\pi}\\!\\int_0^\\pi\\!\\int_0^1(a-b\\rho^2)\\rho^4\\sin^3\\phi\\,d\\rho\\,d\\phi\\,d\\theta=\\tfrac{8\\pi}{3}(\\tfrac a5-\\tfrac b7)$, so $\\dfrac{I}{MR^2}=\\dfrac23\\cdot\\dfrac{a/5-b/7}{a/3-b/5}$. A uniform ball ($b=0$) gives $0.4$; Earth’s $0.3308$ is smaller, so its mass is concentrated toward the centre.", "With $k=b/a$, $\\tfrac23(\\tfrac15-\\tfrac k7)=0.3308(\\tfrac13-\\tfrac k5)$ gives $k\\approx0.7933$. Then $a=5.513/(1-0.6k)\\approx10.5$ g/cm$^3$ at the centre and $a(1-k)\\approx2.2$ g/cm$^3$ at the surface, close to surface rock. A centre denser than any surface rock points to a heavy (iron) core.", "Escape: $\\int_R^\\infty\\dfrac{GM}{r^2}dr=\\lim_{T\\to\\infty}\\Big[-\\dfrac{GM}{r}\\Big]_R^T=\\dfrac{GM}{R}$, finite because the exponent 2 exceeds 1. Then $\\tfrac12v^2=GM/R$ gives $v=\\sqrt{2\\times398{,}600/6371}\\approx11.19$ km/s, matching NASA’s 11.186 km/s."], "reflection": "Suppose gravity weakened like 1/r instead of 1/r². Could anything escape Earth? Which 1D convergence fact decides?", "extension": false, "id": "w05-p2", "discussionSolution": "With a 1/r force, the work to reach distance T is GM ln(T/R), which grows without bound: no finite launch speed would escape. The 1D fact is that $\\int_1^\\infty r^{-p}\\,dr$ converges exactly when $p>1$; gravity’s p = 2 makes escape possible.", "modelSpec": {"data": ["Radius $R=6371$ km; mass $5.9722\\times10^{24}$ kg; mean density $5513$ kg/m$^3$", "Moment of inertia factor $I/(MR^2)=0.3308$", "$GM=398{,}600$ km$^3$/s$^2$; escape velocity $11.186$ km/s"], "assume": ["Earth is a ball whose density depends only on the distance $\\rho$ from the centre", "The density profile is quadratic"], "model": ["Density $\\delta(\\rho)=a-b\\rho^2$, with $\\rho$ in Earth radii ($0\\le\\rho\\le1$)", "$I$ is the moment of inertia about the spin axis"]}, "figure": {"alt": "Cross-section of Earth shaded by the model density, darkest at the centre, with a small spherical box drawn with edges d rho, rho d phi, rho sin phi d theta", "caption": "Earth as a ball whose density depends only on $\\rho$; a small spherical box has edges $\\Delta\\rho$, $\\rho\\,\\Delta\\phi$, and $\\rho\\sin\\phi\\,\\Delta\\theta$.", "file": "w05-p2"}}, {"title": "The radar’s blind cone", "context": "Finland’s weather radars scan the sky by spinning their antennas around and around, tilting up a little after each turn. The steepest tilt in the Finnish schedule is 45°, so the air directly above each radar, inside an upside-down cone, is never sampled: forecasters call it the cone of silence. How much sky is that, and what if the top tilt were lower?", "model": "The 45° top elevation and the 100 km range are published values. A flat Earth and straight radar beams are simplifications.", "sources": ["fmiradar"], "work": "Describe the blind region below height $h$ in cylindrical coordinates in both orders: $z$ first, and $r$ first. Check your volume against $\\tfrac13\\pi R^2h$. Then let the top tilt be any angle $\\alpha$ (so the cone is $z=r\\tan\\alpha$ with base radius $R=h\\cot\\alpha$) and show that $\\bar z$ does not depend on $R$. In spherical coordinates, convert the cone $z=\\sqrt{x^2+y^2}$ to an equation in $\\phi$, and describe the blind region within range 100 km. Also explain why the volume of one radar sample, $\\Delta\\rho$ long and $\\Delta\\phi$ by $\\Delta\\theta$ wide, grows like $\\rho^2$.", "questions": [{"prompt": "Find the volume of the blind region below height $h$ (in km). Enter it as a function of h.", "expected": "pi*h^3/3", "units": "km³", "kind": "expression", "tolerance": 1e-05, "hints": ["With a 45° top tilt, the blind cone is z ≥ r, so at height z its radius is z.", "Integrate r dr dθ dz with 0 ≤ r ≤ z, 0 ≤ z ≤ h."], "id": "w05-p3-a", "label": "a"}, {"prompt": "Enter $\\bar z$ for the blind region below height $h$.", "expected": "3*h/4", "units": "km", "kind": "expression", "tolerance": 1e-05, "hints": ["The moment is ∫₀ʰ z · (πz²) dz.", "Divide by the volume πh³/3."], "id": "w05-p3-b", "label": "b"}, {"prompt": "Within range 100 km, what fraction of the hemisphere of sky above the radar lies in the blind cone?", "expected": "1-sqrt(2)/2", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["The blind region is 0 ≤ ρ ≤ 100, 0 ≤ φ ≤ π/4, 0 ≤ θ ≤ 2π.", "The ρ and θ integrals are the same as for the hemisphere (0 ≤ φ ≤ π/2), so compare the φ integrals."], "id": "w05-p3-c", "label": "c"}], "solution": ["At a $45^\\circ$ top tilt the blind region is $z\\ge\\sqrt{x^2+y^2}$, that is, $r\\le z$. Order 1: $0\\le\\theta\\le2\\pi$, $0\\le z\\le h$, $0\\le r\\le z$. Order 2: $0\\le\\theta\\le2\\pi$, $0\\le r\\le h$, $r\\le z\\le h$. Then $V=\\int_0^{2\\pi}\\!\\int_0^h\\!\\int_0^z r\\,dr\\,dz\\,d\\theta=\\tfrac{\\pi h^3}{3}$, matching $\\tfrac13\\pi R^2h$ with $R=h$.", "$\\bar z=\\dfrac{\\int_0^h z\\cdot\\pi z^2\\,dz}{\\pi h^3/3}=\\dfrac{3h}{4}$. For a top tilt $\\alpha$ the cross-section at height $z$ is $\\pi z^2\\cot^2\\alpha$; the factor $\\cot^2\\alpha$ (equivalently $R^2/h^2$) cancels, so $\\bar z=3h/4$ for every $\\alpha$ and every $R$.", "$z=\\sqrt{x^2+y^2}$ becomes $\\rho\\cos\\phi=\\rho\\sin\\phi$, so $\\phi=\\pi/4$. The blind region within 100 km is $0\\le\\rho\\le100$, $0\\le\\phi\\le\\pi/4$, all $\\theta$: $V=\\tfrac{2\\pi}{3}100^3(1-\\tfrac{\\sqrt2}{2})\\approx6.1\\times10^5$ km$^3$, a fraction $1-\\tfrac{\\sqrt2}{2}\\approx0.293$ of the hemisphere.", "A sample has edges $\\Delta\\rho$, $\\rho\\Delta\\phi$, $\\rho\\sin\\phi\\,\\Delta\\theta$, so its volume is $\\rho^2\\sin\\phi\\,\\Delta\\rho\\,\\Delta\\phi\\,\\Delta\\theta$: at 100 km it is 100 times larger than at 10 km."], "reflection": "Weather happens mostly below about 10 km. Why does a high top tilt (45° in Finland) matter more for a radar next to a city than one far away, and how does a network of overlapping radars fill the blind cone?", "extension": false, "id": "w05-p3", "discussionSolution": "Near a city, storms overhead fall inside the blind cone exactly where people live, and a cone of silence 10 km tall over the city is unobserved by its own radar. Neighbouring radars look at the same air from the side at low tilts, so a network spaced so that each radar’s blind cone lies inside the others’ coverage leaves no gap.", "modelSpec": {"data": ["Highest elevation angle in the Finnish scan schedule: $45^\\circ$ (scan group C)", "Range of those scans: $100$ km"], "assume": ["The ground is flat and radar beams are straight lines", "The radar sits at the origin; $z$ is height in km"], "model": ["Blind region (cone of silence): points above the steepest beam, $z\\ge\\sqrt{x^2+y^2}$", "Part (c): blind points within range $100$ km of the radar"]}, "photo": {"alt": "A water tower in Vantaa, Finland, rising above pine trees, with the white dome of a Finnish Meteorological Institute weather radar on its top; a playground in the foreground", "credit": "Paju", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "page": "https://commons.wikimedia.org/wiki/File:Kaivokselan_tutka1.jpg", "file": "w05-p3.jpg"}, "figure": {"alt": "Side view of the radar with its scan beams at elevation angles from 2 to 45 degrees and the unscanned cone above it shaded, out to 100 km range", "caption": "Side view of the Finnish scan group C (tilts 2°–45°, range 100 km). The shaded cone above the steepest beam is never sampled.", "file": "w05-p3"}}, {"title": "Starlight and city light at Lick Observatory", "context": "Lick Observatory, the University of California’s mountain-top observatory near San Jose, depends on dark skies. In 1976 Lick astronomer Merle Walker measured how bright the lights of Salinas made the night sky at sites up to 99 km away, and found that the glow fades with distance $D$ like $D^{-2.5}$. Astronomers meanwhile add up the light of each star from its blurry image on the camera.", "model": "The Salinas measurements and the $D^{-2.5}$ law are published. The Gaussian star image and the evenly spread city lights are models.", "sources": ["walker1977"], "work": "Check Walker’s law on two rows of his table (10.5 km and 16.9 km). For the star: camera pixels are squares, so astronomers often add up light over squares $[-s,s]^2$ instead of disks. Show that the square sums converge to the same total as the disks (sandwich each square between two disks) and explain why switching exhaustions is legal here; then factor the square integral to find $\\int_{-\\infty}^\\infty e^{-x^2}dx$. For the city: do the near-zero version of part (b), over the punctured disk $0<x^2+y^2\\le1$: for which $b$ does it converge, and to what? Show that $b=1$ diverges at both ends. Compare with $\\int_0^1x^{-p}dx$ and $\\int_1^\\infty x^{-p}dx$, and complete: $1/|\\mathbf x|^s$ is integrable near the origin of $\\mathbb R^n$ exactly when $s<\\underline{\\quad}$. Finally, classify $f=(x^2+y^2)^{-3/4}$: does it converge on the punctured disk, on the outside, both, or neither?", "questions": [{"prompt": "A star’s image has brightness $e^{-(x^2+y^2)}$ (arbitrary units). Enter the light collected inside a circular aperture of radius $r$.", "expected": "pi*(1-exp(-r^2))", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["Use polar coordinates: ∫₀^{2π} ∫₀^r e^(−ρ²) ρ dρ dθ.", "Substitute w = ρ²."], "id": "w05-p4-a", "label": "a"}, {"prompt": "Suppose city lights are spread evenly over the region outside a dark circle of radius 1, and the glow from distance $D$ is proportional to $D^{-2b}$. For $b>1$, enter $\\iint_{x^2+y^2\\ge1}(x^2+y^2)^{-b}\\,dA$ as a function of b.", "expected": "pi/(b-1)", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["In polar coordinates the integrand becomes r^(1−2b).", "Integrate from 1 to T, then let T → ∞."], "id": "w05-p4-b", "label": "b"}, {"prompt": "With Walker’s law (2b = 2.5), by what factor does the glow from evenly spread lights fall if the dark zone around the observatory grows from radius 10 km to 40 km?", "expected": "1/2", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["Redo part (b) with inner radius a: the integral is proportional to a^(2−2b).", "Here 2 − 2b = −1/2."], "id": "w05-p4-c", "label": "c"}], "solution": ["Walker’s law predicts the ratio $(16.9/10.5)^{2.5}\\approx3.29$ between the two rows; the table gives $1.91/0.59\\approx3.24$. Star: $\\iint_{D_r}e^{-(x^2+y^2)}dA=2\\pi\\int_0^re^{-\\rho^2}\\rho\\,d\\rho=\\pi(1-e^{-r^2})\\to\\pi$ as $r\\to\\infty$.", "The square $[-s,s]^2$ contains the disk of radius $s$ and sits inside the disk of radius $\\sqrt2s$. The integrand is positive, so the square integrals are sandwiched between $\\pi(1-e^{-s^2})$ and $\\pi(1-e^{-2s^2})$, both tending to $\\pi$. (For a positive integrand every exhaustion gives the same limit; this fails for integrands that change sign.) On a square, $\\iint e^{-x^2}e^{-y^2}dA=\\big(\\int_{-s}^se^{-x^2}dx\\big)^2$, so $\\int_{-\\infty}^\\infty e^{-x^2}dx=\\sqrt\\pi$.", "Outside: $2\\pi\\int_1^Tr^{1-2b}dr=\\dfrac{2\\pi}{2-2b}(T^{2-2b}-1)\\to\\dfrac{\\pi}{b-1}$ for $b>1$, and $\\to\\infty$ for $b<1$. Inside: $2\\pi\\int_\\varepsilon^1r^{1-2b}dr\\to\\dfrac{\\pi}{1-b}$ for $b<1$ and diverges for $b>1$. At $b=1$ both become $2\\pi\\ln T$ or $2\\pi\\ln(1/\\varepsilon)$: divergent at both ends.", "In 1D the thresholds are $p<1$ near 0 and $p>1$ at infinity. In $\\mathbb R^n$ the volume factor $r^{n-1}$ turns $1/r^s$ into $r^{n-1-s}$, so the threshold is $s<n$ near the origin and $s>n$ at infinity. For $(x^2+y^2)^{-3/4}=r^{-3/2}$: $s=1.5<2$, so it converges on the punctured disk (to $4\\pi$) but not outside.", "With inner radius $a$ the glow is $\\dfrac{\\pi}{b-1}a^{2-2b}=4\\pi a^{-1/2}$ for $b=1.25$. From $a=10$ to $a=40$ it falls by $(40/10)^{-1/2}=\\tfrac12$. Walker’s $2.5>2$ means the total from all the lights is finite once the observatory has a dark zone; without one ($a\\to0$) the nearest lights would dominate without bound."], "reflection": "If city glow fell only like D⁻², as it would for light spreading in empty space without being absorbed, what would happen to the total glow from lights spread over an endless plain, even with a dark zone around the observatory?", "extension": false, "id": "w05-p4", "discussionSolution": "With exponent 2b = 2 (b = 1), the outer integral becomes 2π ln(T/a), which grows without bound as the plain extends: the total glow would be infinite, and no dark zone could help. Real glow falls faster than D⁻² because the atmosphere scatters and absorbs light along the way, which is why Walker found 2.5 and why distance protects observatories.", "modelSpec": {"data": ["Walker (1977): sky glow at $45^\\circ$ altitude toward a city varies as $D^{-2.5}$", "Salinas measurements: glow $1.91$ at $10.5$ km and $0.59$ at $16.9$ km (natural sky $=1$)"], "assume": ["A star’s image has brightness $e^{-(x^2+y^2)}$ on the camera (units chosen so the width is 1)", "City lights are spread evenly over the plane outside a dark circle around the observatory, and glows add"], "model": ["Star: total light $=\\iint_{\\mathbb R^2}e^{-(x^2+y^2)}dA$", "Glow at the observatory $\\propto\\iint_{x^2+y^2\\ge a^2}(x^2+y^2)^{-b}dA$, Walker: $2b=2.5$"]}, "photo": {"alt": "Aerial view looking east from above San Jose over dry, folded hills of the Diablo Range; the white domes of Lick Observatory are tiny specks on the summit of Mount Hamilton near the centre", "credit": "Dicklyon", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "page": "https://commons.wikimedia.org/wiki/File:Lick_Observatory_aerial.jpg", "file": "w05-p4.jpg"}, "figure": {"alt": "Log-log plot of Walker’s Salinas sky glow measurements against distance with a line of slope minus 2.5", "caption": "Walker’s 1977 measurements of sky glow toward Salinas (visual dots, blue circles) with a line $\\propto D^{-2.5}$ (log–log axes).", "file": "w05-p4"}}, {"title": "The 660-tonne ball inside Taipei 101", "context": "Near the top of Taipei 101, a 508 m skyscraper, a giant steel ball hangs between the 87th and 92nd floors. When strong winds or earthquakes rock the tower, the 660-tonne pendulum swings the other way and calms the motion. How big must a steel ball be to weigh 660 tonnes, and how hard is it to spin?", "model": "The mass and floors are published. Treating the stacked steel plates as a solid uniform ball of steel is an assumption.", "sources": ["taipeidamper"], "work": "Set up the ball’s volume and its moment of inertia about a vertical axis through its centre in spherical coordinates, and explain the extra factor $\\sin^2\\phi$ in the moment. Then find the center of mass of the lower half of the ball (the hemisphere below the centre) and say why it must lie less than $R/2$ below the centre.", "questions": [{"prompt": "Find the radius of a solid steel ball with mass 660 t.", "expected": "(3*660000/(4*pi*7850))^(1/3)", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["V = ∫₀^{2π}∫₀^π∫₀^R ρ² sin φ dρ dφ dθ = 4πR³/3.", "Set 7850 × V = 660,000 kg and solve for R."], "id": "w05-p5-a", "label": "a"}, {"prompt": "Find the moment of inertia of the ball about a vertical axis through its centre.", "expected": "2/5*660*(3*660000/(4*pi*7850))^(2/3)", "units": "t·m²", "kind": "number", "tolerance": 1e-05, "hints": ["The squared distance to the axis is x² + y² = ρ² sin²φ.", "You should find I = (2/5)MR²."], "id": "w05-p5-b", "label": "b"}, {"prompt": "How far below the centre is the center of mass of the lower half of the ball?", "expected": "3/8*(3*660000/(4*pi*7850))^(1/3)", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["Use π/2 ≤ φ ≤ π; the depth below the centre is −z = −ρ cos φ.", "The moment is (π/4)R⁴ in units of density; the half-ball volume is (2/3)πR³."], "id": "w05-p5-c", "label": "c"}], "solution": ["$V=\\tfrac43\\pi R^3$ and $7850V=660{,}000$ kg give $R=\\big(\\tfrac{3\\cdot660{,}000}{4\\pi\\cdot7850}\\big)^{1/3}\\approx2.72$ m, a ball about 5.4 m across, more than a storey tall.", "$I=\\delta\\int_0^{2\\pi}\\!\\int_0^\\pi\\!\\int_0^R(\\rho\\sin\\phi)^2\\rho^2\\sin\\phi\\,d\\rho\\,d\\phi\\,d\\theta=\\delta\\cdot2\\pi\\cdot\\tfrac43\\cdot\\tfrac{R^5}{5}=\\tfrac25MR^2\\approx1950$ t·m$^2$. The $\\sin^2\\phi$ is the squared distance $\\rho^2\\sin^2\\phi$ to the axis.", "Lower half: $\\int_0^{2\\pi}\\!\\int_{\\pi/2}^{\\pi}\\!\\int_0^R(-\\rho\\cos\\phi)\\rho^2\\sin\\phi\\,d\\rho\\,d\\phi\\,d\\theta=2\\pi\\cdot\\tfrac12\\cdot\\tfrac{R^4}4=\\tfrac{\\pi R^4}{4}$; dividing by $\\tfrac23\\pi R^3$ gives $\\tfrac38R\\approx1.02$ m below the centre. It is less than $R/2$ because the half-ball is widest near the centre."], "reflection": "The real damper is a stack of 41 steel plates of different diameters rather than a smooth solid ball. How would you set up its volume as a sum of cylinders, and why would the answer differ slightly from the ball?", "extension": true, "id": "w05-p5", "discussionSolution": "Summing cylinders of height 0.125 m and the published plate radii gives a stepped solid that only approximates a sphere: the corners of the steps add or remove a little steel compared with the smooth ball. The real plates also have holes and fittings, so the true radius differs slightly from the solid-ball estimate.", "modelSpec": {"data": ["Mass of the pendulum weight: $660$ t", "Hangs between the 87th and 92nd floors of the 508 m tower"], "assume": ["The weight is a solid ball of uniform steel, density $7850$ kg/m$^3$"], "model": ["Ball $\\rho\\le R$ in spherical coordinates, centre at the origin"]}, "photo": {"alt": "The gold-coloured tuned mass damper of Taipei 101 seen from above: a ball built from stacked circular steel plates, flat on top, hanging from thick cables with hydraulic dampers below", "credit": "Armand du Plessis", "license": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/", "page": "https://commons.wikimedia.org/wiki/File:Taipei_101_Tuned_Mass_Damper_2010.jpg", "file": "w05-p5.jpg"}, "figure": {"alt": "Side view of a ball hanging from cables between two floor levels, with its centre and the lower hemisphere marked", "caption": "The damper modelled as a solid steel ball of radius $R$ hanging between floors; the lower hemisphere is shaded.", "file": "w05-p5"}}]}, {"week": 6, "title": "Paths, work, and what depends on the route", "subtitle": "The Road Not Taken (Doesn’t Matter)", "skills": ["Parametrize curves, including curved wires, and compute speed", "Compute length, mass, and centroids with ds; check invariance under reparametrization and reversal", "Compute work and circulation with dr, P dx + Q dy, and explain signs", "Test path independence, find 2D and 3D potentials, and use the fundamental theorem", "Recognize when equal cross-partials still fail to give a potential"], "formulas": ["$\\int_C f\\,ds=\\int_a^b f(\\mathbf c(t))\\,\\|\\mathbf c^{\\prime}(t)\\|\\,dt$ (no orientation)", "$\\int_C\\mathbf F\\cdot d\\mathbf r=\\int_C P\\,dx+Q\\,dy=\\int_a^b\\mathbf F(\\mathbf c(t))\\cdot\\mathbf c^{\\prime}(t)\\,dt$ (orientation matters)", "$\\int_C\\nabla f\\cdot d\\mathbf r=f(\\mathbf c(b))-f(\\mathbf c(a))$"], "sources": ["ggbridge", "ggbstatics", "acc", "everest", "stelvio", "earthgm", "lightning"], "problems": [{"title": "Weighing the Golden Gate’s main cable", "context": "Each of the Golden Gate Bridge’s two main cables is a 0.92 m bundle of 27,572 steel wires. Between the towers it hangs in a smooth curve 1,280 m across and 144 m deep. How long is that curve, how heavy is it, and where is its balance point?", "model": "Span, sag, and the weight figure are published; the exact parabola and a constant weight per metre of cable are modeling assumptions.", "sources": ["ggbridge", "ggbstatics"], "work": "Parametrize the main-span cable as $\\mathbf c(t)=(t,y(t))$ with its $t$-interval, and find its speed. Then reverse it (Marin tower to San Francisco tower), and check that the engineer’s parametrization $\\Psi(u)=\\big(k\\sinh u,\\ \\tfrac k2\\sinh^2u\\big)$, $k=12800/9$ m, traces the same curve; give its $u$-interval and show $\\|\\Psi^{\\prime}(u)\\|=k\\cosh^2u$. Explain why all three give the same length and the same $\\int_C y\\,ds$. Estimate the weight of the main-span cable from $\\lambda=48.7$ kN per metre of cable, and explain why $\\int\\lambda\\,dx$ would underestimate it. Finally, the flat parabolic region between the cable and the line joining its two tops has centroid height $3h/5=86.4$ m. Why is the wire’s centroid so much lower?", "questions": [{"prompt": "Enter the speed $\\|\\mathbf c^{\\prime}(t)\\|$ of $\\mathbf c(t)=(t,\\,9t^2/25600)$ as a function of t.", "expected": "sqrt(1+(9*t/12800)^2)", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["Differentiate: c′(t) = (1, 9t/12800).", "The speed is the length of that vector."], "id": "w06-p1-a", "label": "a"}, {"prompt": "Find the length of the main-span cable (to two decimal places).", "expected": "1321.97431941635", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["L is the integral of the speed from t = −640 to t = 640.", "With t = k sinh u the integrand becomes k cosh²u du; a calculator’s numerical integral also works."], "id": "w06-p1-b", "label": "b"}, {"prompt": "Find $\\bar y$, the height of the cable’s centroid above its lowest point.", "expected": "49.2045532645424", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["Along Ψ, y ds = (k²/2) sinh²u cosh²u du = (k²/8) sinh²(2u) du.", "Divide ∫ y ds by the length from part (b). Expect a little more than h/3 = 48 m."], "id": "w06-p1-c", "label": "c"}], "solution": ["With the origin at the cable’s lowest point, $y=144(x/640)^2=9x^2/25600$, so $\\mathbf c(t)=(t,9t^2/25600)$, $-640\\le t\\le640$, with $\\mathbf c^{\\prime}(t)=(1,9t/12800)$ and speed $\\sqrt{1+(9t/12800)^2}$. The speed grows from 1 at midspan to $\\sqrt{1.2025}\\approx1.097$ at the towers.", "Reversed, $\\mathbf c_3(t)=(-t,9t^2/25600)$ has the same speed at each point, so every scalar integral is unchanged. For $\\Psi$: $y=\\tfrac k2\\sinh^2u=(k\\sinh u)^2/(2k)$ and $2k=25600/9$, so $\\Psi$ traces the same parabola for $|\\sinh u|\\le9/20$, i.e. $|u|\\le U=\\operatorname{arcsinh}(9/20)$. $\\Psi^{\\prime}=(k\\cosh u,k\\sinh u\\cosh u)$ has length $k\\cosh u\\sqrt{1+\\sinh^2u}=k\\cosh^2u$. Each parametrization traces the curve once, so $ds$ is the same geometric arc length.", "\\[L=k\\int_{-U}^{U}\\cosh^2u\\,du=k\\,(U+\\sinh U\\cosh U)\\approx1321.97\\text{ m},\\] about 42 m more than the 1,280 m span.", "\\[\\int_C y\\,ds=\\frac{k^2}{8}\\int_{-U}^{U}\\sinh^2(2u)\\,du=\\frac{k^2}{8}\\Big(\\frac{\\sinh4U}{4}-U\\Big)\\approx65047\\text{ m}^2,\\] so $\\bar y\\approx65047/1321.97\\approx49.20$ m. By symmetry $\\bar x=0$.", "Weight: $\\int_C\\lambda\\,ds=48.7\\times1321.97\\approx64{,}380$ kN, about 6,560 t; $\\int\\lambda\\,dx=48.7\\times1280\\approx62{,}340$ kN misses the extra length of the sloping parts. The flat region is widest at the top, so its area sits high (centroid $3h/5$); the wire’s mass is spread almost evenly in $x$, and most of the span is low, so its centroid is near $h/3$."], "reflection": "The source lists the cable’s weight per horizontal metre. If the weight per metre of cable is constant, is the weight per horizontal metre also constant? Where along the span is it largest?", "extension": false, "id": "w06-p1", "discussionSolution": "No. Weight per horizontal metre is $\\lambda\\,ds/dx=\\lambda\\sqrt{1+(y^{\\prime})^2}$, which equals $\\lambda$ only at midspan and grows to about $1.097\\lambda$ at the towers, where the cable is steepest. (For a real suspension bridge it is the deck’s load per horizontal metre that is nearly constant, which is why the cable hangs as a parabola.)", "modelSpec": {"data": ["Main span (tower to tower): $1280$ m", "Maximum sag of the main cable: $h=144$ m", "Cable weight: $48.7$ kN per horizontal metre; diameter $0.92$ m"], "assume": ["The main-span cable hangs as a parabola with its lowest point at midspan", "The weight per metre of cable is constant, $\\lambda=48.7$ kN/m (exact at midspan, where the cable is horizontal)", "The cable is a curve (a wire): its 0.92 m thickness is ignored"], "model": ["Coordinates in metres, origin at the cable’s lowest point: $y=144\\,(x/640)^2$, $-640\\le x\\le640$", "Mass, centroid: $W=\\int_C\\lambda\\,ds$, $\\ \\bar y=\\dfrac{\\int_C y\\,ds}{\\int_C ds}$"]}, "photo": {"alt": "Close-up of one orange-painted Golden Gate Bridge main cable against a blue sky, with a cable band and suspender ropes hanging from it", "credit": "Guillaume Paumier", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "page": "https://commons.wikimedia.org/wiki/File:Cables_of_the_Golden_Gate_bridge_in_San_Francisco_66.jpg", "file": "w06-p1.jpg"}, "figure": {"alt": "Side view of the Golden Gate main span: two towers, a parabolic main cable sagging 144 m, and the deck", "caption": "The model: a parabolic cable between towers 1,280 m apart, lowest point at the origin (vertical scale exaggerated 2:1).", "file": "w06-p1"}}, {"title": "Sailing around Antarctica: with or against the current?", "context": "The Antarctic Circumpolar Current, driven by strong westerly winds, is the only ocean current that circles the whole globe. A ship circling Antarctica can ride it or fight it. How much does the current help, and why does the direction of the voyage matter for some totals but not others?", "model": "The average speed is published; the voyage along latitude 60° S, the uniform eastward speed, and the small northward drift are assumptions.", "sources": ["acc", "earthgm"], "work": "Sketch the map: Antarctica, the voyage circle, and $\\mathbf u$ at eight points of the circle. Show that the eastward part of $\\mathbf u$ turns clockwise on this map and that the drift points away from the pole. Parametrize the westward voyage (counterclockwise on the map) with its interval. Without integrating, use your sketch to explain why the drift contributes nothing to $\\oint_C\\mathbf u\\cdot d\\mathbf r$. Explain why reversing the voyage flips the sign of $\\oint_C\\mathbf u\\cdot d\\mathbf r$ but not of $\\oint_C ds$ or $\\oint_C\\|\\mathbf u\\|\\,ds$. Finally, a ship moving at speed $V$ through the water needs time $\\oint_C ds/(V+\\mathbf u\\cdot\\mathbf T)$; show that, to first order, this is $L/V-(\\oint_C\\mathbf u\\cdot d\\mathbf r)/V^2$, and estimate the hours an eastward voyage at $V=20$ km/h saves over a westward one.", "questions": [{"prompt": "Find the length $\\oint_C 1\\,ds$ of the voyage.", "expected": "6371*pi", "units": "km", "kind": "number", "tolerance": 1e-05, "hints": ["The circle has radius 3185.5 km.", "A circle of radius ρ has length 2πρ; check it with ∫ ‖c′(t)‖ dt."], "id": "w06-p2-a", "label": "a"}, {"prompt": "Find $\\oint_C\\mathbf u\\cdot d\\mathbf r$ for the westward voyage (counterclockwise on the map).", "expected": "-1.8*6371*pi", "units": "km²/h", "kind": "number", "tolerance": 1e-05, "hints": ["With c(t) = (ρ cos t, ρ sin t), the eastward part gives (1.8/ρ)(ρ sin t, −ρ cos t)·(−ρ sin t, ρ cos t) = −1.8ρ.", "The drift part gives zero. The sign should be negative: the ship fights the current."], "id": "w06-p2-b", "label": "b"}, {"prompt": "Find $\\oint_C\\|\\mathbf u\\|\\,ds$ for the same westward voyage.", "expected": "1.8*sqrt(1.01)*6371*pi", "units": "km²/h", "kind": "number", "tolerance": 1e-05, "hints": ["On the circle the eastward and drift parts are perpendicular, with sizes 1.8 and 0.18 km/h.", "This scalar integral uses ‖c′(t)‖ and has no sign from the direction of travel."], "id": "w06-p2-c", "label": "c"}], "solution": ["On this view eastward is clockwise, because Earth turns clockwise seen from above the South Pole. The westward voyage is $\\mathbf c(t)=(\\rho\\cos t,\\rho\\sin t)$, $0\\le t\\le2\\pi$, with $\\rho=6371\\cos60^\\circ=3185.5$ km and speed $\\rho$, so $\\oint_C ds=2\\pi\\rho=6371\\pi\\approx20{,}015$ km.", "On the circle the drift $(0.18/\\rho)(x,y)$ is radial and $\\mathbf c^{\\prime}(t)$ is tangent, so their dot product is zero at every point. The eastward part gives $\\frac{1.8}{\\rho}(\\rho\\sin t,-\\rho\\cos t)\\cdot(-\\rho\\sin t,\\rho\\cos t)=-1.8\\rho$, so $\\oint_C\\mathbf u\\cdot d\\mathbf r=-1.8(2\\pi\\rho)=-11467.8\\pi\\approx-36{,}027$ km$^2$/h. Eastward (clockwise) gives $+36{,}027$ km$^2$/h: reversing $\\mathbf c^{\\prime}$ flips each dot product.", "$\\|\\mathbf u\\|=\\sqrt{1.8^2+0.18^2}=1.8\\sqrt{1.01}$ km/h everywhere on the circle, so $\\oint_C\\|\\mathbf u\\|\\,ds=1.8\\sqrt{1.01}\\,(6371\\pi)\\approx36{,}207$ km$^2$/h for either direction. The scalar integral counts the drift and ignores direction; the line integral ignores the drift and keeps direction.", "Since $1/(V+w)\\approx1/V-w/V^2$ for small $w$, the time is about $L/V-\\frac{1}{V^2}\\oint_C\\mathbf u\\cdot d\\mathbf r$. Going east saves about $2(36{,}027)/20^2\\approx180$ hours, roughly a week, compared with going west. The exact values $L/(V\\mp1.8)$ differ by about 182 hours."], "reflection": "Ocean circulation is measured in m²/s, the same units as this line integral. Why is $\\oint\\mathbf u\\cdot d\\mathbf r$ a natural measure of how strongly water swirls around a loop, while $\\oint\\|\\mathbf u\\|\\,ds$ is not?", "extension": false, "id": "w06-p2", "discussionSolution": "The line integral adds only the part of the flow along the loop, with a sign, so flow that goes around adds up and flow that crosses the loop or reverses cancels. $\\oint\\|\\mathbf u\\|\\,ds$ counts every bit of motion as positive, so water drifting straight across the loop or sloshing back and forth would also make it large.", "modelSpec": {"data": ["Average speed of the Antarctic Circumpolar Current: $50$ cm/s $=1.8$ km/h", "The current flows from west to east (the West Wind Drift)", "Earth’s mean radius: $R=6371$ km"], "assume": ["The voyage follows latitude $60^\\circ$ S", "Along the voyage the current flows due east at $1.8$ km/h, with a small northward drift of $0.18$ km/h (0.05 m/s)"], "model": ["Map: Earth viewed from directly above the South Pole; $x,y$ in km. The $60^\\circ$ S circle appears at its true radius $\\rho=R\\cos60^\\circ=3185.5$ km", "Surface current: $\\mathbf u(x,y)=\\dfrac{1.8}{\\rho}(y,\\,-x)+\\dfrac{0.18}{\\rho}(x,\\,y)$ km/h near the voyage circle", "$C$: the circle $x^2+y^2=\\rho^2$"]}, "photo": {"alt": "A wave breaks over the bow of the icebreaker Polar Star as it crosses the Southern Ocean toward Antarctica, January 2015", "credit": "U.S. Coast Guard photo by Petty Officer 1st Class George Degener", "license": "Public domain", "licenseUrl": "", "page": "https://commons.wikimedia.org/wiki/File:Waves_crashing_over_the_deck_of_the_coast_guard_cutter_Polar_Star.jpg", "file": "w06-p2.jpg"}, "figure": {"alt": "Map centred on the South Pole with Antarctica, the 60 degree south voyage circle, and current arrows turning clockwise with small outward drift", "caption": "View from above the South Pole: the voyage circle $\\rho=3185.5$ km and the model current (drift exaggerated).", "file": "w06-p2"}}, {"title": "A sealed snack bag climbs Everest", "context": "Climbers notice that sealed snack bags puff up on the way to high camps. On the summit of Mount Everest in 1981, Chris Pizzo of the American Medical Research Expedition measured an air pressure only one third of sea-level pressure. Physicists follow a gas on a pressure–volume diagram, where a “path” is the process that carries it from one state to another. Which totals depend on the path?", "model": "The summit pressure is a published measurement; the bag’s volume, the temperatures, and both processes are assumptions.", "sources": ["everest"], "work": "Parametrize both paths (path 2 has two pieces) with their intervals. Compute the energy integral $\\int_C\\tfrac52y\\,dx+\\tfrac52x\\,dy$ directly along both paths. The two answers agree: does that alone prove the integral is path independent? Explain why unequal answers on two paths disprove path independence while equal answers on two paths do not prove it. Check the cross-partials of the work field $(y,0)$ and of the heat field $(\\tfrac72y,\\tfrac52x)$, and find the heat $Q$ absorbed along each path.", "questions": [{"prompt": "Find the work $W=\\int_C y\\,dx$ done by the air along path 1, the straight segment.", "expected": "1", "units": "L·atm", "kind": "number", "tolerance": 1e-05, "hints": ["Parametrize x = 1 + 1.5t, y = 1 − 2t/3, 0 ≤ t ≤ 1; then dx = 1.5 dt.", "You can check with the area of a trapezoid under the segment."], "id": "w06-p3-a", "label": "a"}, {"prompt": "Find the work $W=\\int_C y\\,dx$ along path 2.", "expected": "log(3)-1/6", "units": "L·atm", "kind": "number", "tolerance": 1e-05, "hints": ["On the isotherm y = 1/x, so the first piece gives ∫ from 1 to 3 of dx/x.", "On the constant-pressure piece x decreases from 3 to 2.5, so that piece is negative."], "id": "w06-p3-b", "label": "b"}, {"prompt": "Enter a potential $f(x,y)$ for the energy field $\\big(\\tfrac52y,\\ \\tfrac52x\\big)$.", "expected": "5*x*y/2", "units": "L·atm", "kind": "potential", "tolerance": 1e-05, "hints": ["Integrate (5/2)y with respect to x and add an unknown g(y).", "Differentiate with respect to y to show g is constant."], "id": "w06-p3-c", "label": "c"}], "solution": ["Path 1: $\\mathbf c(t)=(1+1.5t,\\,1-\\tfrac23t)$, $0\\le t\\le1$. Path 2: $\\mathbf c(t)=(t,1/t)$, $1\\le t\\le3$, then $\\mathbf c(t)=(3-0.5t,\\,1/3)$, $0\\le t\\le1$. Both start at A $=(1,1)$ and end at B $=(2.5,1/3)$.", "Path 1: $W=\\int_0^1(1-\\tfrac23t)(1.5)\\,dt=1$ L·atm. Path 2: $W=\\int_1^3\\frac{dt}{t}+\\int_0^1\\tfrac13(-0.5)\\,dt=\\ln3-\\tfrac16\\approx0.932$ L·atm. Different works with the same endpoints prove that $\\int y\\,dx$ is path dependent; indeed $\\partial_y(y)=1\\ne0=\\partial_x(0)$.", "Energy: on path 1, $\\tfrac52\\int_0^1\\big[(1-\\tfrac23t)(1.5)+(1+1.5t)(-\\tfrac23)\\big]dt=\\tfrac52\\int_0^1(\\tfrac56-2t)\\,dt=-\\tfrac5{12}$; on path 2, $\\tfrac52\\big[\\int_1^3(\\tfrac1t-\\tfrac1t)\\,dt+\\int_0^1(-\\tfrac16)\\,dt\\big]=-\\tfrac5{12}$. Agreement on two paths proves nothing by itself. The potential $f=\\tfrac52xy$ ($f_x=\\tfrac52y$, $f_y=\\tfrac52x$) proves it for every path: $\\Delta U=f(B)-f(A)=\\tfrac52(\\tfrac56-1)=-\\tfrac5{12}$ L·atm.", "Heat $Q=\\Delta U+W$: $Q_1=-\\tfrac5{12}+1=\\tfrac7{12}\\approx0.583$ and $Q_2=-\\tfrac5{12}+\\ln3-\\tfrac16\\approx0.515$ L·atm ($1$ L·atm $=101.325$ J). The heat field fails the test: $\\partial_y(\\tfrac72y)=\\tfrac72\\ne\\tfrac52=\\partial_x(\\tfrac52x)$. Internal energy is a state function; heat and work are not."], "reflection": "On a pressure–volume diagram an engine runs around a closed loop. What is $\\Delta U$ around any loop, and why can the work around the loop still be nonzero?", "extension": false, "id": "w06-p3", "discussionSolution": "$\\Delta U=0$ around any loop, because $U$ has a potential $\\tfrac52PV$ and the loop ends where it starts. Work $\\oint P\\,dV$ is path dependent, so around a loop it need not be zero: it equals the signed area enclosed by the loop (Green’s theorem, Week 9), the net work the engine delivers each cycle, supplied by the heat absorbed.", "modelSpec": {"data": ["Summit pressure measured in October 1981: $253$ mm Hg", "One standard atmosphere: $760$ mm Hg, so the summit had $253/760=0.333$ atm"], "assume": ["The bag holds $1$ L of air at $1$ atm and $300$ K at sea level", "At the summit: $1/3$ atm and $250$ K; the slack bag keeps its inside pressure equal to the outside", "Air is an ideal diatomic gas: $PV/T$ is constant and $U=\\tfrac52PV$"], "model": ["Coordinates: $x=V$ (L), $y=P$ (atm). Start A $=(1,1)$, summit B $=(2.5,\\,1/3)$", "Work done by the air $W=\\int_C y\\,dx$; energy change $\\Delta U=\\int_C\\tfrac52y\\,dx+\\tfrac52x\\,dy$; heat $Q=\\Delta U+W$", "Path 1: the straight segment from A to B. Path 2: along the isotherm $xy=1$ from A to $(3,1/3)$, then at constant $y=1/3$ to B"]}, "photo": {"alt": "Aerial view of the snow-covered summit pyramid of Mount Everest above surrounding Himalayan ridges", "credit": "shrimpo1967; derivative work by Papa Lima Whiskey 2", "license": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "page": "https://commons.wikimedia.org/wiki/File:Mount_Everest_as_seen_from_Drukair2_PLW_edit_Cropped.jpg", "file": "w06-p3.jpg"}, "figure": {"alt": "Pressure-volume diagram with states A and B, a straight path 1, and a path 2 along a hyperbola then a horizontal segment", "caption": "The two processes from A $=(1,1)$ to B $=(2.5,1/3)$ on the $(V,P)$ diagram.", "file": "w06-p3"}}, {"title": "Forty-eight hairpins, one number", "context": "The road from Prato allo Stelvio up to the Stelvio Pass, 2,757 m high in the Italian Alps, climbs through 48 hairpin bends. Cyclists from around the world ride it. How much work does Earth’s gravity do on a rider, and does all that twisting matter?", "model": "Elevations and Earth’s GM and radius are published; the rider’s mass, the spherical Earth, and the hairpin formula are assumptions.", "sources": ["stelvio", "earthgm"], "work": "Find a potential $f$ for $\\mathbf F$ by integrating $F_1$ with respect to $x$ and carrying an unknown function $g(y,z)$; then use $F_2$ and $F_3$ to show $g$ is constant. Explain why you never need $\\phi(t)$ or $\\lambda(t)$, and why the extra term in $h(t)$ does not matter. What is the work done by gravity on the descent? Compare your answer with the flat-Earth estimate $-mg\\,\\Delta h$, $g=GM/R^2$. Finally, explain why gravity’s total work around any closed ride is zero even though the rider is exhausted.", "questions": [{"prompt": "Enter a potential $f(x,y,z)$ for $\\mathbf F$, writing the constant $GMm$ as c.", "expected": "c/sqrt(x^2+y^2+z^2)", "units": "J", "kind": "potential", "tolerance": 1e-05, "hints": ["Substitute w = x² + y² + z² to integrate −c x (x² + y² + z²)^(−3/2) with respect to x.", "Check that the derivative of your answer with respect to z is −c z/(x² + y² + z²)^(3/2)."], "id": "w06-p4-a", "label": "a"}, {"prompt": "Find the work done by gravity on the rider from Prato to the pass along the hairpin road.", "expected": "-1446.27683945079", "units": "kJ", "kind": "number", "tolerance": 1e-05, "hints": ["Use f(end) − f(start); only the distances r = R + elevation from Earth’s center matter.", "Expect about −m g Δh, but compute with the inverse-square potential; it differs in the fourth digit."], "id": "w06-p4-b", "label": "b"}, {"prompt": "A rider climbs from Prato to the pass, descends the far side to Bormio, and returns to Prato by another road. What is the total work done by gravity?", "expected": "0", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["The fundamental theorem gives f(end) − f(start).", "The rider’s effort goes into air drag, friction, and heat, which are not gravity."], "options": ["0 J: gravity has a potential everywhere the rider can be, and the ride ends where it starts.", "Negative: the rider worked hard, so gravity’s total work must be negative.", "It depends on which roads make up the loop.", "Positive: descents are faster than climbs."], "id": "w06-p4-c", "label": "c"}], "solution": ["$f_x=F_1=-c\\,x(x^2+y^2+z^2)^{-3/2}$ integrates to $f=c(x^2+y^2+z^2)^{-1/2}+g(y,z)$. Then $f_y=-c\\,y(x^2+y^2+z^2)^{-3/2}+g_y=F_2$ forces $g_y=0$, and $f_z=F_3$ forces $g_z=0$. So $f=c/\\sqrt{x^2+y^2+z^2}=GMm/r$, defined everywhere except Earth’s center.", "By the fundamental theorem, the work is $f(\\mathbf c(1))-f(\\mathbf c(0))$, and $f$ depends only on $r=\\|\\mathbf c\\|=R+h$. Since $h(0)=915$ and $h(1)=2757$ (the sine terms vanish at both ends), the angles never enter.", "With $c=GMm=3.9860\\times10^{14}\\times80$ J·m, \\[W=c\\Big(\\frac1{6{,}373{,}757}-\\frac1{6{,}371{,}915}\\Big)\\approx-1{,}446{,}277\\text{ J}\\approx-1446.28\\text{ kJ}.\\] Descending reverses the path and gives $+1446.28$ kJ.", "Flat Earth: $g=GM/R^2\\approx9.820$ m/s$^2$ and $-mg\\,\\Delta h=-80(9.820)(1842)\\approx-1447.11$ kJ, only 0.06% different, because $g$ is slightly weaker at altitude. Around a closed ride, $f$ ends where it starts, so gravity’s work is $0$; the rider’s work is lost to air drag, rolling friction, and body heat, which have no potential."], "reflection": "The punctured-plane field (−y, x)/(x² + y²) has equal cross-partials but no potential. Gravity here is also undefined at one point, yet it has a potential. What is different?", "extension": false, "id": "w06-p4", "discussionSolution": "Equal cross-partials give a potential on domains with no holes that a loop can wrap around. Space with one point removed has none: any loop can slide off the missing point, and f = GMm/r is defined everywhere except the center. The plane with a point removed has a hole that a loop can circle, and there (−y, x)/(x² + y²) has circulation 2π.", "modelSpec": {"data": ["Stelvio Pass: $2757$ m; Prato allo Stelvio: $915$ m", "48 hairpins on the 25 km road between them", "Earth: $GM=3.9860\\times10^{14}$ m$^3$/s$^2$, $R=6{,}371{,}000$ m"], "assume": ["Rider plus bicycle: $m=80$ kg", "Earth is a non-rotating sphere; elevation is measured along the radius, so a point at elevation $h$ has $r=R+h$"], "model": ["Gravity, Earth’s center at the origin: $\\mathbf F=-\\dfrac{GMm\\,(x,y,z)}{(x^2+y^2+z^2)^{3/2}}$ N", "Road, $0\\le t\\le1$: $\\mathbf c(t)=(R+h)(\\cos\\phi\\cos\\lambda,\\ \\cos\\phi\\sin\\lambda,\\ \\sin\\phi)$ with", "$h=915+1842t+15\\sin(2\\pi t)\\sin(48\\pi t)$ m, $\\phi=46.62^\\circ-0.09^\\circ t-0.003^\\circ\\sin(48\\pi t)$, $\\lambda=10.59^\\circ-0.14^\\circ t+0.004^\\circ\\sin(48\\pi t)$"]}, "photo": {"alt": "A motorcyclist rounds a stone-walled hairpin bend on the eastern ramp of the Stelvio Pass, with snowy mountains behind", "credit": "kallerna", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "page": "https://commons.wikimedia.org/wiki/File:Stelvio_Pass_Bolzano_side_3.jpg", "file": "w06-p4.jpg"}, "figure": {"alt": "Plan view of a winding road with many hairpin bends from Prato to the Stelvio Pass, and an inset showing distances from Earth’s center", "caption": "The hairpin model seen from above (left) and the only thing gravity’s work depends on: the distances $r_A$ and $r_B$ from Earth’s center (right, not to scale).", "file": "w06-p4"}}, {"title": "Lightning’s magnetic loop", "context": "A typical lightning flash carries about 30,000 amperes, and the Empire State Building is struck about 23 times a year. The current in the channel wraps the surrounding air in a circular magnetic field. Ampère’s law says the field’s circulation around a loop depends on the current inside it, not on the loop’s shape.", "model": "The current and strike rate are published; a straight, steady vertical channel is an assumption.", "sources": ["lightning"], "work": "Use symmetry to add the four oriented edges of the square $S_1$ and compare the total with part (a). Show that $\\partial B_1/\\partial y=\\partial B_2/\\partial x$ wherever the field is defined, and explain why $\\mathbf B$ is nevertheless not a gradient on the plane with the channel removed. Then compute the circulation around $S_2$ by adding its four oriented edges.", "questions": [{"prompt": "Find $\\oint\\mathbf B\\cdot d\\mathbf r$ around the circle of radius 10 m centred on the channel, counterclockwise.", "expected": "12*pi", "units": "mT·m", "kind": "number", "tolerance": 1e-05, "hints": ["On the circle B is tangent with size 6/10 mT.", "Multiply by the circle’s length; the answer does not depend on the radius."], "id": "w06-p5-a", "label": "a"}, {"prompt": "Find $\\int\\mathbf B\\cdot d\\mathbf r$ along the right edge of $S_1$, from $(10,-10)$ to $(10,10)$.", "expected": "3*pi", "units": "mT·m", "kind": "number", "tolerance": 1e-05, "hints": ["On this edge x = 10 and dx = 0, so only B₂ dy = 60 dy/(100 + y²) counts.", "Use ∫ dy/(100 + y²) = (1/10) arctan(y/10)."], "id": "w06-p5-b", "label": "b"}, {"prompt": "Enter $\\partial B_2/\\partial x$ as a function of x and y.", "expected": "6*(y^2-x^2)/(x^2+y^2)^2", "units": "mT/m", "kind": "expression", "tolerance": 1e-05, "hints": ["Use the quotient rule on 6x/(x² + y²).", "Compare with ∂B₁/∂y for B₁ = −6y/(x² + y²)."], "id": "w06-p5-c", "label": "c"}], "solution": ["On the circle $\\mathbf c(t)=(10\\cos t,10\\sin t)$, $\\mathbf B=0.6(-\\sin t,\\cos t)$ and $\\mathbf c^{\\prime}=10(-\\sin t,\\cos t)$, so the integrand is 6 and the circulation is $12\\pi\\approx37.70$ mT·m $=\\mu_0I$.", "Right edge: $\\int_{-10}^{10}\\frac{60}{100+y^2}\\,dy=6\\big[\\arctan(y/10)\\big]_{-10}^{10}=3\\pi$. By the four-fold symmetry each counterclockwise edge of $S_1$ gives $3\\pi$, and the total $12\\pi$ matches the circle.", "$\\partial_x\\frac{6x}{x^2+y^2}=\\frac{6(y^2-x^2)}{(x^2+y^2)^2}=\\partial_y\\frac{-6y}{x^2+y^2}$. If $\\mathbf B=\\nabla f$ on the punctured plane, every closed loop would give 0, but the circle gives $12\\pi$. Equal cross-partials guarantee a potential only on a domain without holes.", "$S_2$ does not enclose the channel. Its edges $x=40$ and $x=20$ give $6\\cdot2\\arctan(1/4)$ and $-6\\cdot2\\arctan(1/2)$; the edges $y=\\mp10$ give $6[\\arctan(4)-\\arctan(2)]$ each. Since $\\arctan4=\\pi/2-\\arctan\\tfrac14$ and $\\arctan2=\\pi/2-\\arctan\\tfrac12$, the total is $0$."], "reflection": "The cross-partial test missed that B is not a gradient. What feature of the domain is responsible, and why does a square that does not surround the channel give zero?", "extension": true, "id": "w06-p5", "discussionSolution": "The domain, the plane with the channel removed, has a hole, so a loop can circle the current; the cross-partial test is only reliable on a domain with no holes. A square away from the channel lies in a hole-free region, such as a half-plane, where B has a potential (a multiple of the polar angle), so its circulation is zero.", "modelSpec": {"data": ["Typical lightning current: about $30{,}000$ A", "The Empire State Building is struck about 23 times a year"], "assume": ["The channel is a long, straight vertical line carrying a steady $I=30{,}000$ A upward", "$\\mu_0=4\\pi\\times10^{-7}$ T·m/A, so $\\mu_0I/(2\\pi)=6$ mT·m"], "model": ["In a horizontal plane, $x,y$ in metres, channel at the origin: $\\mathbf B=\\dfrac{6\\,(-y,\\ x)}{x^2+y^2}$ mT", "$S_1$: the square $|x|\\le10$, $|y|\\le10$; $S_2$: the square $20\\le x\\le40$, $|y|\\le10$; both counterclockwise"]}, "figure": {"alt": "Top view of circular magnetic field lines around a lightning channel, a square loop around the channel, and a second square beside it", "caption": "Top view: field lines of $\\mathbf B$ around the channel, the circle of radius 10 m, and the squares $S_1$ and $S_2$.", "file": "w06-p5"}}]}, {"week": 7, "title": "Surfaces people build and measure", "subtitle": "Pride and Parametrization", "skills": ["Build parametrizations of spheres, cylinders, graphs, and ruled surfaces, with domains", "Identify a surface from its parametrization and read its grid curves", "Find the parameters of a point, tangent vectors, normals, and tangent planes", "Compute area for graphs, polar domains, spheres, cones, and surfaces of revolution", "Tell coordinate singularities from geometric corners; area does not depend on the parametrization"], "formulas": ["$\\mathbf N=\\Phi_u\\times\\Phi_v,\\quad dS=\\|\\mathbf N\\|\\,du\\,dv$", "$z=g(x,y):\\quad dS=\\sqrt{1+g_x^2+g_y^2}\\,dx\\,dy$", "$A=2\\pi\\int_a^b f(x)\\sqrt{1+f'(x)^2}\\,dx$ for $y=f(x)$ rotated about the $x$-axis"], "sources": ["earth", "alma", "cooling", "zimbabwe", "iter"], "problems": [{"title": "How much of Earth is tropical?", "context": "The tropics, between latitudes $23.44^\\circ$ S and $23.44^\\circ$ N, are where the Sun can be directly overhead at some time of year. On a globe they look like a thin belt around the middle. How much of the planet do they really cover?", "model": "R and the tilt are published values. A perfect sphere ignores Earth’s slight polar flattening, and the enclosing cylinder is a geometric construction, not a physical object.", "sources": ["earth"], "work": "Write $\\Phi(\\phi,\\theta)$ for the sphere with its domain, and describe its grid curves (fixed $\\theta$; fixed $\\phi$) in geographic language. Explain why this chart fails to be regular at the poles even though Earth is not pointed there. Before computing, predict: if Earth is cut by parallel planes into ten slabs of equal thickness, which slab has the most surface area? Then parametrize the cylinder as $\\Psi(\\theta,z)=(R\\cos\\theta,R\\sin\\theta,z)$ and find its lateral area between heights $z_1<z_2$.", "questions": [{"prompt": "Enter $\\|\\Phi_\\phi\\times\\Phi_\\theta\\|$ as a function of phi.", "expected": "6371^2*sin(phi)", "units": "km²", "kind": "expression", "tolerance": 1e-05, "hints": ["The two tangent vectors are perpendicular, with lengths R and R sin φ.", "So the norm of the cross product is their product."], "id": "w07-p1-a", "label": "a"}, {"prompt": "Find the area of the part of the sphere between two horizontal planes a distance h apart (both planes cut the sphere). Enter it as a function of h.", "expected": "2*pi*6371*h", "units": "km²", "kind": "expression", "tolerance": 1e-05, "hints": ["With z = R cos φ, dz = −R sin φ dφ turns R² sin φ dφ dθ into R dz dθ.", "Your answer should not depend on where the band sits."], "id": "w07-p1-b", "label": "b"}, {"prompt": "What fraction of Earth’s surface lies in the tropics? Enter the exact value or a decimal rounded to two places.", "expected": "sin(23.44*pi/180)", "units": "", "kind": "number", "tolerance": 0.002, "hints": ["The tropics run from z = −R sin 23.44° to z = R sin 23.44°.", "Divide the band area by the whole sphere’s area 4πR²."], "id": "w07-p1-c", "label": "c"}], "solution": ["$\\Phi(\\phi,\\theta)=(R\\sin\\phi\\cos\\theta,R\\sin\\phi\\sin\\theta,R\\cos\\phi)$ on $0\\le\\phi\\le\\pi$, $0\\le\\theta\\le2\\pi$. Fixed $\\theta$ gives a meridian (a line of longitude); fixed $\\phi$ gives a parallel (a line of latitude $90^\\circ-\\phi$).", "$\\Phi_\\phi=(R\\cos\\phi\\cos\\theta,R\\cos\\phi\\sin\\theta,-R\\sin\\phi)$ and $\\Phi_\\theta=(-R\\sin\\phi\\sin\\theta,R\\sin\\phi\\cos\\theta,0)$ are perpendicular with lengths $R$ and $R\\sin\\phi$, so $\\|\\Phi_\\phi\\times\\Phi_\\theta\\|=R^2\\sin\\phi=6371^2\\sin\\phi$ km$^2$. It vanishes at $\\phi=0,\\pi$ because every meridian meets at a pole, just as longitude is undefined there. A different chart, such as the graph $z=\\sqrt{R^2-x^2-y^2}$ near the North Pole, is regular there, so the sphere itself is smooth.", "For a band $z_1\\le z\\le z_2$, substituting $z=R\\cos\\phi$ gives $\\int_0^{2\\pi}\\!\\int_{z_1}^{z_2}R\\,dz\\,d\\theta=2\\pi R(z_2-z_1)=2\\pi Rh$. The cylinder has $\\|\\Psi_\\theta\\times\\Psi_z\\|=R$, so its band also has area $2\\pi R(z_2-z_1)$: Archimedes’ hat-box theorem. All ten equal slabs have the same area, $4\\pi R^2/10$; the equator does not win.", "The tropics have $h=2R\\sin23.44^\\circ$, so the fraction is $\\dfrac{2\\pi R\\cdot2R\\sin23.44^\\circ}{4\\pi R^2}=\\sin23.44^\\circ\\approx0.398$. Almost 40% of Earth’s surface is tropical."], "reflection": "Lambert’s cylindrical equal-area map moves each point horizontally out to this cylinder and unrolls it. Why does that map show Greenland and Africa with correct relative areas, even though shapes near the poles look squashed?", "extension": false, "id": "w07-p1", "discussionSolution": "Every band and every longitude wedge keeps its area under horizontal projection onto the cylinder (the hat-box theorem applied to thin pieces), so every region keeps its area. Shapes still distort: at latitude L, east–west lengths are stretched by 1/cos L while north–south lengths shrink by cos L, and the product, area, is unchanged.", "modelSpec": {"data": ["Earth’s volumetric mean radius: $R=6371$ km", "Axial tilt: $23.44^\\circ$, which puts the tropics at latitudes $23.44^\\circ$ S to $23.44^\\circ$ N"], "assume": ["Earth is a perfect sphere (the real Earth is flattened at the poles by about 0.3%)", "The cylinder is an imaginary construction that touches the sphere all around the equator"], "model": ["Earth: the sphere $x^2+y^2+z^2=R^2$, $R=6371$ km", "Latitude $L$ sits at height $z=R\\sin L$, so the tropics are the band $|z|\\le R\\sin23.44^\\circ$", "Enclosing cylinder: $x^2+y^2=R^2$, $-R\\le z\\le R$"]}, "photo": {"alt": "Earth seen from Apollo 17, showing Africa and the tropical belt", "credit": "NASA / Apollo 17 crew", "license": "Public domain", "licenseUrl": "", "page": "https://commons.wikimedia.org/wiki/File:The_Earth_seen_from_Apollo_17.jpg", "file": "w07-p1.jpg"}, "figure": {"alt": "Side view of the sphere inside its enclosing cylinder, with the tropics band shaded and horizontal projection arrows", "caption": "The model: Earth as a sphere, the tropics as a band of height $h$, and the enclosing cylinder.", "file": "w07-p1"}}, {"title": "How much mirror does an ALMA antenna need?", "context": "ALMA, at 5000 m altitude in Chile’s Atacama Desert, links dozens of dish antennas into one radio telescope. Each 12 m dish is a precision mirror whose curved surface must be built from panels, so its builders need to know exactly how much surface it has.", "model": "Diameter and focal length are published design values. The model ignores the 0.75 m central hole and the gaps between panels; it is a geometric idealization, not a manufacturing drawing.", "sources": ["alma"], "work": "Parametrize the mirror two ways and give each domain: as a graph over the disk, $(x,y,(x^2+y^2)/19.2)$, and with polar coordinates in the domain. Say whether the area should include the flat aperture disk. Then turn the dish on its side: rotating the profile $y=\\sqrt{19.2x}$, $0\\le x\\le1.875$, about the $x$-axis traces the same mirror. Set up $A=2\\pi\\int y\\sqrt{1+y'^2}\\,dx$, explain why it converges even though $y'$ is unbounded at $x=0$, and confirm it gives the same area as part (b).", "questions": [{"prompt": "Enter the graph area factor $\\sqrt{1+g_x^2+g_y^2}$ as a function of r.", "expected": "sqrt(1+r^2/92.16)", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["g_x = 2x/19.2 and g_y = 2y/19.2.", "Then g_x² + g_y² = r²/9.6² = r²/92.16."], "id": "w07-p2-a", "label": "a"}, {"prompt": "Find the area of the mirror surface (exact, or rounded to two decimal places).", "expected": "2*pi*92.16/3*((1+36/92.16)^(3/2)-1)", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["In polar coordinates, A = ∫₀^{2π}∫₀⁶ sqrt(1 + r²/92.16) r dr dθ.", "Substitute w = 1 + r²/92.16."], "id": "w07-p2-b", "label": "b"}, {"prompt": "In the surface-of-revolution setup, simplify the integrand $y\\sqrt{1+y'^2}$ as a function of x.", "expected": "sqrt(19.2*x+92.16)", "units": "m", "kind": "expression", "tolerance": 1e-05, "hints": ["y' = 19.2/(2y), so y²(1 + y'²) = y² + 19.2²/4.", "Replace y² by 19.2x."], "id": "w07-p2-c", "label": "c"}], "solution": ["Graph form: $(x,y,(x^2+y^2)/19.2)$ on $x^2+y^2\\le36$. Polar form: $(r\\cos\\theta,r\\sin\\theta,r^2/19.2)$ on $0\\le r\\le6$, $0\\le\\theta\\le2\\pi$. Only the curved mirror counts; the flat aperture disk is open sky.", "$g_x=x/9.6$ and $g_y=y/9.6$, so the factor is $\\sqrt{1+r^2/92.16}$. In polar coordinates the shadow element is also multiplied by $r$.", "$A=2\\pi\\int_0^6 r\\sqrt{1+r^2/92.16}\\,dr=\\frac{2\\pi(92.16)}{3}\\Big[(1+\\tfrac{36}{92.16})^{3/2}-1\\Big]\\approx123.515$ m$^2$, about 9% more than the $36\\pi\\approx113.097$ m$^2$ aperture.", "With $y=\\sqrt{19.2x}$, $y'=19.2/(2y)$ blows up at $x=0$, but $y\\sqrt{1+y'^2}=\\sqrt{y^2+92.16}=\\sqrt{19.2x+92.16}$ stays bounded, so the improper integral converges, and \\[A=2\\pi\\int_0^{1.875}\\sqrt{19.2x+92.16}\\,dx\\] gives the same area: area belongs to the surface, not to the parametrization."], "reflection": "Two different parameter domains gave the same area. What would go wrong, for the people ordering mirror panels, if area depended on the parametrization?", "extension": false, "id": "w07-p2", "discussionSolution": "Area is a property of the surface. Any two regular, one-to-one parametrizations are related by a change of variables whose Jacobian converts one area element exactly into the other. If area depended on the chart, the amount of aluminum to order would depend on the engineer’s choice of coordinates, which is absurd.", "modelSpec": {"data": ["Primary mirror diameter: $12$ m", "Primary focal length: $f=4.8$ m (focal ratio $f/D=0.4$)", "Central hole: $0.75$ m across"], "assume": ["The mirror is a perfect paraboloid, vertex at the origin, axis along $z$", "Panel gaps and the central hole are ignored"], "model": ["Mirror: $z=\\dfrac{r^2}{4f}=\\dfrac{r^2}{19.2}$ m over the disk $r\\le6$ m", "Rim depth: $z=36/19.2=1.875$ m", "Rays parallel to the axis reflect through the focus $(0,0,4.8)$"]}, "photo": {"alt": "Two ALMA dish antennas on the Chajnantor plateau in Chile", "credit": "Iztok Bončina / ALMA (ESO/NAOJ/NRAO)", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/", "page": "https://commons.wikimedia.org/wiki/File:Two_ALMA_antennas_on_Chajnantor_(ib-alma22).jpg", "file": "w07-p2.jpg"}, "figure": {"alt": "Cross-section of the paraboloid mirror with incoming rays reflecting to the focus", "caption": "The model: a paraboloid of aperture 12 m, rim depth 1.875 m, and focus 4.8 m above the vertex.", "file": "w07-p2"}}, {"title": "Straight lines that build a curved cooling tower", "context": "Power-station cooling towers have a distinctive narrow waist. The natural-draft tower at Niederaussem, Germany, was described as the tallest cooling tower in the world when it was built, yet its curved concrete shell is only about 24 cm thick. Surprisingly, that curved shell is made entirely of straight lines.", "model": "Only the height and base diameter are published values. The narrowest radius, its height, and the exact hyperboloid shape are assumed; real towers are not exact hyperboloids.", "sources": ["cooling"], "work": "Eliminate $t$ and $s$ to identify the surface by an equation in $x,y,z$, and check the base radius and total height. Describe the grid curves: what is the curve with $s$ fixed, and with $t$ fixed? A survey marker sits at $P=(38,19,40)$. Find its parameters, then compute $\\Phi_t$, $\\Phi_s$, and the normal there. Finally, check your tangent plane using the upper half written as a graph, $z=c\\sqrt{(x^2+y^2)/a^2-1}$.", "questions": [{"prompt": "Enter the parameters (t, s) of the marker, with 0 ≤ s < 2π.", "expected": ["0.5", "0"], "units": "", "kind": "vector", "tolerance": 1e-05, "hints": ["The height z = ct gives t immediately.", "Do not use the polar angle of (38, 19). Test s = 0 in both the x and y equations."], "id": "w07-p3-a", "label": "a"}, {"prompt": "Enter $\\Phi_t\\times\\Phi_s$ at the marker.", "expected": ["-3040", "-1520", "722"], "units": "m²", "kind": "vector", "tolerance": 1e-05, "hints": ["At the marker, Φ_t = (0, 38, 80) and Φ_s = (−19, 38, 0).", "Expand the cross product one component at a time."], "id": "w07-p3-b", "label": "b"}, {"prompt": "Enter the tangent plane at the marker as z in terms of x and y.", "expected": "(80*x+40*y-3040)/19", "units": "m", "kind": "expression", "tolerance": 1e-05, "hints": ["Use N·(X − P) = 0 with P = (38, 19, 40).", "Divide N by 38 first, then solve for z."], "id": "w07-p3-c", "label": "c"}], "solution": ["$x^2+y^2=a^2[(\\cos s-t\\sin s)^2+(\\sin s+t\\cos s)^2]=a^2(1+t^2)$ and $t=z/c$, so $\\frac{x^2+y^2}{38^2}-\\frac{z^2}{80^2}=1$: a hyperboloid of one sheet. At $t=-\\sqrt3$ the radius is $38\\cdot2=76$ m, matching the base, and the height is $c(2.5-\\sqrt3+\\sqrt3)=200$ m.", "Fixing $s$ gives $a(\\cos s,\\sin s,0)+t(-a\\sin s,a\\cos s,c)$, a straight line. Fixing $t$ gives a horizontal circle of radius $a\\sqrt{1+t^2}$. The curved shell is woven from straight lines, so straight reinforcing bars can follow it.", "$z=40$ gives $t=0.5$. Then $\\cos s-0.5\\sin s=1$ and $\\sin s+0.5\\cos s=0.5$ force $s=0$, not the polar angle $\\arctan(1/2)$ of $(38,19)$.", "$\\Phi_t=(-a\\sin s,a\\cos s,c)=(0,38,80)$ and $\\Phi_s=(-a(\\sin s+t\\cos s),a(\\cos s-t\\sin s),0)=(-19,38,0)$, so $\\mathbf N=(-3040,-1520,722)=38(-80,-40,19)$.", "The plane is $-80(x-38)-40(y-19)+19(z-40)=0$, that is, $z=(80x+40y-3040)/19$. The graph formula gives $z_x=\\dfrac{c\\,x/a^2}{\\sqrt{(x^2+y^2)/a^2-1}}=\\dfrac{80}{19}$ and $z_y=\\dfrac{40}{19}$ at $P$: the same plane."], "reflection": "A second family, $\\big(a(\\cos s+t\\sin s),\\,a(\\sin s-t\\cos s),\\,ct\\big)$, traces the same surface. How many straight lines on the surface pass through each point, and why might builders care?", "extension": false, "id": "w07-p3", "discussionSolution": "Two: one from each family, so the hyperboloid is doubly ruled. Straight reinforcing bars or formwork can follow both families, giving a curved, buckling-resistant shell assembled from straight pieces.", "modelSpec": {"data": ["Height: $200$ m", "Base diameter: $152$ m, so base radius $76$ m", "Shell thickness: about $0.24$ m"], "assume": ["The shell is exactly the surface traced by $\\Phi$ below; real towers only approximate this shape", "Narrowest radius $a=38$ m and vertical scale $c=80$ m, chosen to match the base radius and height", "$z$ is measured from the narrowest level, so the ground is at $z=-80\\sqrt3\\approx-138.6$ m"], "model": ["Shell: $\\Phi(t,s)=\\big(a(\\cos s-t\\sin s),\\ a(\\sin s+t\\cos s),\\ ct\\big)$", "Domain: $0\\le s\\le2\\pi$, $-\\sqrt3\\le t\\le2.5-\\sqrt3$", "$a=38$ m, $c=80$ m"]}, "photo": {"alt": "The waisted concrete cooling tower of Niederaussem power station, Germany", "credit": "Stodtmeister", "license": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/", "page": "https://commons.wikimedia.org/wiki/File:Kraftwerk_Niederau%C3%9Fem_Block_K_BoA_K%C3%BChlturm.jpg", "file": "w07-p3.jpg"}, "figure": {"alt": "Hyperboloid tower drawn as two crossing families of straight lines, with the point P marked", "caption": "The model surface drawn only with straight lines from $\\Phi$ (teal and brown: the two families). Height 200 m, base radius 76 m, narrowest radius 38 m at $z=0$; the marker $P$ is orange.", "file": "w07-p3"}}, {"title": "The Conical Tower of Great Zimbabwe", "context": "Great Zimbabwe, a UNESCO World Heritage site, was the capital of a southern African kingdom that flourished between roughly the 11th and 15th centuries. Inside its Great Enclosure stands a solid Conical Tower, built of granite blocks without mortar. How much stone surface faces the outside world?", "model": "Height and base diameter are published approximate values; descriptions vary by about a metre. The top radius is assumed, the real tower is masonry rather than a perfect cone, and the full cone’s apex is imaginary.", "sources": ["zimbabwe"], "work": "Write the curved stone face as a graph $z=g(x,y)$ over its shadow, and show the graph area factor is constant. Explain why that makes the curved area a fixed multiple of the shadow’s area, just as for a tilted plane. Decide whether a lime-wash estimate for the curved face should include the flat top disk. Check your area with the cone formula $\\pi RL$, subtracting the missing tip.", "questions": [{"prompt": "Enter $\\Phi_u\\times\\Phi_v$ as a function of u and v.", "expected": ["6*u*cos(v)", "6*u*sin(v)", "u"], "units": "m", "kind": "vector", "tolerance": 1e-05, "hints": ["Φ_u = (cos v, sin v, −6) and Φ_v = (−u sin v, u cos v, 0).", "Check that the third component is positive."], "id": "w07-p4-a", "label": "a"}, {"prompt": "Where does Φ fail to be regular, and what does that mean for the tower?", "expected": "0", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["Regularity fails exactly where the cross product is the zero vector.", "Its norm is u√37. Where is the apex, compared with the tower’s 9 m top?"], "options": ["Only at u = 0, the apex 7.5 m above the tower; the tower itself is regular everywhere.", "Along the top rim u = 1.25, where the tower is cut off.", "Along the seam v = 0, where the parametrization starts and ends.", "Nowhere: a cone has no special point."], "id": "w07-p4-b", "label": "b"}, {"prompt": "Find the area of the curved stone face, excluding the top disk.", "expected": "6*pi*sqrt(37)", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["‖N‖ = u√37.", "Integrate over 1.25 ≤ u ≤ 2.75 and 0 ≤ v ≤ 2π."], "id": "w07-p4-c", "label": "c"}], "solution": ["$\\Phi_u=(\\cos v,\\sin v,-6)$ and $\\Phi_v=(-u\\sin v,u\\cos v,0)$ give $\\mathbf N=(6u\\cos v,6u\\sin v,u)$ with $\\|\\mathbf N\\|=u\\sqrt{37}$, which is zero only at $u=0$.", "The apex $u=0$ is a genuine geometric corner, since no parametrization gives it a tangent plane, but it lies at $z=16.5$ m, outside the $9$ m tower. The truncated tower is regular everywhere; its top and bottom circles are boundary edges.", "$A=\\int_0^{2\\pi}\\int_{1.25}^{2.75}u\\sqrt{37}\\,du\\,dv=\\pi\\sqrt{37}\\,(2.75^2-1.25^2)=6\\pi\\sqrt{37}\\approx114.65$ m$^2$.", "As a graph, $z=16.5-6\\sqrt{x^2+y^2}$ has $g_x^2+g_y^2=36$, so the factor is the constant $\\sqrt{37}$ and $A=\\sqrt{37}\\times$ (annulus area $6\\pi$). Check: $\\pi RL-\\pi r\\ell=\\pi(2.75)(2.75\\sqrt{37})-\\pi(1.25)(1.25\\sqrt{37})=6\\pi\\sqrt{37}$. Lime-washing the flat top too would add $1.5625\\pi\\approx4.91$ m$^2$."], "reflection": "The sphere chart in the Earth problem also had a zero cross product at its poles. Why is that harmless for the sphere but a real corner for the cone?", "extension": false, "id": "w07-p4", "discussionSolution": "At a pole only the spherical-coordinate chart degenerates; another chart, such as a graph over the tangent plane, has a nonzero normal there, so the sphere is smooth. At a cone’s apex no parametrization gives a tangent plane, because normals from different sides point in different directions, so the corner is geometric.", "modelSpec": {"data": ["Height: about $9$ m (30 ft)", "Base diameter: about $5.5$ m (18 ft), so base radius $2.75$ m", "Published descriptions differ by about a metre"], "assume": ["The tower is a truncated cone with top radius $1.25$ m", "Its sloping side is extended upward to an imaginary apex so one formula describes it"], "model": ["Full cone: $\\Phi(u,v)=(u\\cos v,\\ u\\sin v,\\ 16.5-6u)$, $0\\le u\\le2.75$, $0\\le v\\le2\\pi$", "Tower: the part with $1.25\\le u\\le2.75$, that is, $0\\le z\\le9$ m", "The radius shrinks $1.5$ m over the $9$ m height, so $z$ falls $6$ m per metre of radius"]}, "photo": {"alt": "The Conical Tower inside the Great Enclosure at Great Zimbabwe", "credit": "Fanny Schertzer", "license": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/", "page": "https://commons.wikimedia.org/wiki/File:Conical_tower_%E2%80%93_Great_Zimbabwe.jpg", "file": "w07-p4.jpg"}, "figure": {"alt": "Side view of the truncated cone tower with dashed extension to an imaginary apex", "caption": "The model: a truncated cone, extended (dashed) to an imaginary apex where $\\Phi$ fails to be regular.", "file": "w07-p4"}}, {"title": "The plasma ring inside ITER", "context": "ITER, the international fusion experiment under construction in southern France, will hold a plasma hotter than the Sun’s core inside a ring-shaped magnetic cage. The shape of that ring is a torus.", "model": "Major and minor radii are published design values. The real plasma cross-section is D-shaped and taller than it is wide; a circular torus is a simplified model.", "sources": ["iter"], "work": "Describe the grid curves and what $R$ and $r$ measure. Show the two tangent vectors are perpendicular before computing the cross-product norm. Interpret the total area as (tube circumference) × (distance travelled by the tube’s center).", "questions": [{"prompt": "Enter $\\|\\Phi_\\theta\\times\\Phi_\\phi\\|$ as a function of phi.", "expected": "2*(6.2+2*cos(phi))", "units": "m²", "kind": "expression", "tolerance": 1e-05, "hints": ["The tangent lengths are R + r cos φ and r.", "The tangent vectors are perpendicular."], "id": "w07-p5-a", "label": "a"}, {"prompt": "Find the area of the model plasma surface.", "expected": "4*pi^2*6.2*2", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["Integrate r(R + r cos φ) over both angles.", "The cos φ term integrates to zero."], "id": "w07-p5-b", "label": "b"}, {"prompt": "Enter (area of the outer half, cos φ > 0) minus (area of the inner half).", "expected": "32*pi", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["The outer half has −π/2 ≤ φ ≤ π/2.", "Each half has area 2πr(πR ± 2r)."], "id": "w07-p5-c", "label": "c"}], "solution": ["Fixed $\\theta$ gives a circle of radius $r$, a cross-section of the tube; fixed $\\phi$ gives a horizontal circle of radius $R+r\\cos\\phi$. $R$ is the distance from the central axis to the tube’s center and $r$ is the tube’s radius.", "$\\Phi_\\theta=(-(R+r\\cos\\phi)\\sin\\theta,(R+r\\cos\\phi)\\cos\\theta,0)$ and $\\Phi_\\phi=(-r\\sin\\phi\\cos\\theta,-r\\sin\\phi\\sin\\theta,r\\cos\\phi)$ have zero dot product and lengths $R+r\\cos\\phi$ and $r$, so the norm is $r(R+r\\cos\\phi)=2(6.2+2\\cos\\phi)$ m$^2$.", "$A=\\int_0^{2\\pi}\\!\\int_0^{2\\pi}r(R+r\\cos\\phi)\\,d\\phi\\,d\\theta=4\\pi^2Rr=(2\\pi r)(2\\pi R)=49.6\\pi^2\\approx489.5$ m$^2$ (Pappus’ theorem).", "The outer half has area $2\\pi r(\\pi R+2r)$ and the inner half $2\\pi r(\\pi R-2r)$, a difference of $8\\pi r^2=32\\pi\\approx100.5$ m$^2$."], "reflection": "The same newsletter lists a plasma volume of 837 m³, while a circular torus with these radii has volume 2π²Rr² ≈ 490 m³. What feature of the real plasma explains the difference?", "extension": true, "id": "w07-p5", "discussionSolution": "Elongation. ITER’s plasma cross-section is D-shaped and about 1.7 times taller than it is wide, so it encloses much more volume than a circle of radius 2.0 m: 490 × 1.7 ≈ 833 m³, close to the published 837 m³. (In this model the volume and the area happen to share the number 49.6π², because V = A·r/2 and r/2 = 1 m.)", "modelSpec": {"data": ["Plasma major radius: $R=6.2$ m", "Plasma minor radius: $r=2.0$ m", "Plasma volume: $837$ m$^3$"], "assume": ["The plasma’s cross-section is a circle of radius $r$ (the real one is D-shaped and taller than it is wide)"], "model": ["Torus: $\\Phi(\\theta,\\phi)=\\big((R+r\\cos\\phi)\\cos\\theta,\\ (R+r\\cos\\phi)\\sin\\theta,\\ r\\sin\\phi\\big)$", "Domain: $0\\le\\theta\\le2\\pi$, $0\\le\\phi\\le2\\pi$"]}, "figure": {"alt": "Top view of the torus and a cut through its axis showing two circular tube cross-sections", "caption": "The model: a circular tube of radius $r$ whose centre runs around a circle of radius $R$.", "file": "w07-p5"}}]}, {"week": 8, "title": "What crosses a surface", "subtitle": "May the Flux Be With You", "skills": ["Evaluate scalar surface integrals on spheres, cylinders, and graphs, including weighted ones", "Spot cancellations between an integrand and the area factor", "Choose an orientation and read it from the cross product", "Compute flux with n dS, with the graph element (−g_x, −g_y, 1) dA, and on spheres with n = r/a", "Interpret the sign of a flux and compare closed-surface flux with volume"], "formulas": ["$\\iint_S f\\,dS=\\iint_D f(\\Phi)\\,\\|\\Phi_u\\times\\Phi_v\\|\\,du\\,dv$", "$\\iint_S\\mathbf F\\cdot d\\mathbf S=\\iint_D\\mathbf F(\\Phi)\\cdot(\\Phi_u\\times\\Phi_v)\\,du\\,dv=\\iint_S\\mathbf F\\cdot\\mathbf n\\,dS$", "Graph $z=g(x,y)$, upward: $d\\mathbf S=(-g_x,-g_y,1)\\,dx\\,dy$; sphere of radius $a$: $dS=a^2\\sin\\phi\\,d\\phi\\,d\\theta$, $\\mathbf n=\\mathbf r/a$"], "sources": ["tsi2011", "sunfacts", "earth", "noor1", "sentrough", "usgsrain", "bocci2012", "planck2018", "shoes2022", "pdgastro", "saharadust"], "problems": [{"title": "Weighing sunlight: the Sun’s power and Earth’s share", "context": "Above the atmosphere, a surface facing the Sun receives about 1361 watts on every square metre: the total solar irradiance, measured by satellite radiometers. From that one number you can find the total power output of the Sun, and how much of it Earth intercepts, the first line of every climate energy budget.", "model": "The irradiance and distance are published; perfect inverse-square spreading, parallel rays at Earth, and a spherical Earth are modeling assumptions.", "sources": ["tsi2011", "sunfacts", "earth"], "work": "Write the outward unit normal on the sphere $|\\mathbf r|=a$ centred on the Sun and evaluate $\\mathbf F\\cdot\\mathbf n$ there without parametrizing. Explain why the flux is the same for every $a$, and what physical fact that expresses. Near Earth, put the Sun in the $+z$ direction, so sunlight is the constant field $(0,0,-S)$; on the day hemisphere $z\\ge0$ of $x^2+y^2+z^2=R^2$, the power absorbed per square metre is $Sz/R$. Set up the absorbed power as a scalar surface integral with $dS=R^2\\sin\\phi\\,d\\phi\\,d\\theta$ and the correct range of $\\phi$. Interpret $\\iint z\\,dS\\big/\\iint 1\\,dS$ over a hemisphere as the height of the centre of mass of a thin hemispherical shell; compare it with the solid half-ball’s $3a/8$, explain the difference, and say which one is the day-side average of $\\cos$(solar zenith angle).", "questions": [{"prompt": "Find the outward flux of $\\mathbf F$ through the sphere of radius $a$ centred on the Sun, in yottawatts ($1$ YW $=10^{24}$ W). Your answer should not depend on $a$.", "expected": "4*pi*149.6^2*1360.8/10^6", "units": "YW", "kind": "number", "tolerance": 1e-05, "hints": ["On that sphere F points along n = r/a and has the constant size S d²/a².", "Multiply that constant by the area 4πa², with d = 1.496e11 m."], "id": "w08-p1-a", "label": "a"}, {"prompt": "Enter $\\iint_H z\\,dS$ for the upper hemisphere $H$ of a sphere of radius $a$ (curved part only), as a function of a.", "expected": "pi*a^3", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["With z = a cos φ and dS = a² sin φ dφ dθ, the hemisphere is 0 ≤ φ ≤ π/2.", "The φ-integral of cos φ sin φ from 0 to π/2 is 1/2."], "id": "w08-p1-b", "label": "b"}, {"prompt": "Averaged over the whole globe, day and night, how much solar power arrives per square metre at the top of the atmosphere?", "expected": "1360.8/4", "units": "W/m²", "kind": "number", "tolerance": 1e-05, "hints": ["The absorbed power is (S/R) times part (b) with a = R, which is S times πR².", "Divide by Earth’s whole surface area, the integral of 1 dS = 4πR²."], "id": "w08-p1-c", "label": "c"}], "solution": ["On $|\\mathbf r|=a$ the outward unit normal is $\\mathbf n=\\mathbf r/a$, and $\\mathbf F=Sd^2\\,\\mathbf r/a^3$, so $\\mathbf F\\cdot\\mathbf n=Sd^2/a^2$ is constant. The flux is $(Sd^2/a^2)(4\\pi a^2)=4\\pi d^2S=4\\pi(1.496\\times10^{11})^2(1360.8)\\approx3.827\\times10^{26}$ W $=382.71$ YW, matching the published luminosity of $382.8$ YW. The $a^2$ cancels: every sphere around the Sun catches the same total power, because nothing absorbs the light in between (energy conservation).", "On the day hemisphere, $z=R\\cos\\phi$ with $0\\le\\phi\\le\\pi/2$, so \\[\\iint_H\\frac{Sz}{R}\\,dS=\\frac SR\\int_0^{2\\pi}\\!\\!\\int_0^{\\pi/2}R\\cos\\phi\\,R^2\\sin\\phi\\,d\\phi\\,d\\theta=\\frac SR\\,\\pi R^3=S\\pi R^2.\\] With $R=6.371\\times10^6$ m this is about $1.735\\times10^{17}$ W: exactly the sunlight crossing a flat disk of radius $R$, Earth’s shadow.", "$\\iint_Hz\\,dS=\\pi a^3$, while the shell’s area is $\\iint_H1\\,dS=2\\pi a^2$, so the shell’s centre of mass is at height $a/2$ (equal-height bands have equal area, so the shell’s mass is spread evenly in height). The solid half-ball’s centroid $3a/8$ is lower because most of its volume sits near the flat base. Since $\\cos\\zeta=z/R$, the day-side average of $\\cos\\zeta$ is the shell’s $\\tfrac12$, not $\\tfrac38$.", "Averaging over the whole sphere divides by its area $\\iint 1\\,dS=4\\pi R^2$ (an area, not the volume $\\tfrac43\\pi R^3$): $S\\pi R^2/(4\\pi R^2)=S/4=340.2$ W/m$^2$, the familiar “about 340 W/m$^2$” of climate budgets."], "reflection": "A planet orbits twice as far from the Sun as Earth. Without any new integral, what irradiance does it receive, and which part of your work justifies the answer?", "extension": false, "id": "w08-p1", "discussionSolution": "The flux through every sphere centred on the Sun is the same L, so at distance 2d the irradiance is L/(4π(2d)²) = S/4, about 340 W/m². The justification is part (a): the flux does not depend on the radius because nothing between the spheres absorbs light.", "modelSpec": {"data": ["Total solar irradiance at Earth’s distance: $S=1360.8$ W/m$^2$", "Mean Earth–Sun distance: $d=149.6\\times10^6$ km", "Earth’s mean radius: $R=6371$ km", "Published luminosity of the Sun (for checking): $382.8\\times10^{24}$ W"], "assume": ["Sunlight spreads out equally in all directions and nothing between the Sun and Earth absorbs it", "Near Earth the Sun is so far away that its rays are parallel", "Earth is a perfect sphere"], "model": ["Sunlight (W/m$^2$), Sun at the origin: $\\mathbf F(\\mathbf r)=Sd^2\\,\\dfrac{\\mathbf r}{|\\mathbf r|^3}$", "Near Earth, with the Sun in the $+z$ direction: $\\mathbf F=(0,0,-S)$; Earth is $x^2+y^2+z^2=R^2$", "Absorbed per square metre at a day-side point: $-\\mathbf F\\cdot\\mathbf n=Sz/R$"]}, "photo": {"alt": "The full disk of the Sun in ultraviolet light from NASA’s Solar Dynamics Observatory, with bright active regions and glowing magnetic loops", "credit": "NASA/SDO, ALMA (ESO/NAOJ/NRAO)", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/", "page": "https://commons.wikimedia.org/wiki/File:Full_disk_of_the_Sun_(eso1703e-comparisona).jpg", "file": "w08-p1.jpg"}, "figure": {"alt": "Left: the Sun with two concentric spheres crossed by the same radial rays. Right: Earth with parallel sunlight striking the day hemisphere", "caption": "The model: light spreading from the Sun through spheres of radius $a$ (left), and parallel sunlight on Earth’s day hemisphere $z\\ge0$ (right).", "file": "w08-p1"}}, {"title": "How much sunlight do Noor’s mirrors catch?", "context": "Noor Ouarzazate I, on the edge of the Sahara in Morocco, is a 160 MW solar power plant without a single solar panel. Long curved mirrors, parabolic troughs, track the Sun and focus its light onto a pipe of hot oil running along their focal line. The plant’s total mirror opening is published as an aperture area of 1,308,000 m$^2$. Engineers quote this aperture area, not the larger area of curved glass. Why?", "model": "Plant size, aperture area, and trough geometry are published; the strength of direct sunlight, perfect tracking, and the absence of losses are assumptions.", "sources": ["noor1", "sentrough"], "work": "Sketch the cross-section $z=x^2/6.8$, $|x|\\le2.88$, with the focus and three vertical sunbeams, and draw the upward unit normal at $x=0$ and at the rim. At a mirror point, the sunlight per square metre of glass is $f=900\\cos\\alpha$ W/m$^2$, where $\\alpha$ is the angle between the upward unit normal and the vertical. Write $\\cos\\alpha$ as a function of $x$. Then write $\\iint_S f\\,dS$ over one 12 m module as a double integral over its shadow, including the factor $\\sqrt{1+g_x^2+g_y^2}$, and spot the cancellation before integrating. Finally set up the glass area $\\iint_S1\\,dS$ of the same module and decide, without evaluating, whether it is larger or smaller than the $5.76\\times12$ m$^2$ aperture. Is $\\iint_S1\\,dS$ ever the volume of the trough?", "questions": [{"prompt": "Enter the upward vector area element $(-g_x,-g_y,1)$ for the mirror $z=g(x,y)=x^2/6.8$.", "expected": ["-x/3.4", "0", "1"], "units": "", "kind": "vector", "tolerance": 1e-05, "hints": ["g_x = 2x/6.8 and g_y = 0, because the trough is straight along y.", "The third component is +1 for the upward orientation."], "id": "w08-p2-a", "label": "a"}, {"prompt": "With direct sunlight of 900 W/m² arriving along every trough’s axis of symmetry, how much solar power reaches all the mirrors of Noor I? Give megawatts.", "expected": "900*1308000/10^6", "units": "MW", "kind": "number", "tolerance": 1e-05, "hints": ["On each trough the weighted integrand f times the square-root factor is the constant 900: the cosine and the area factor cancel.", "So the power is 900 W/m² times the shadow (aperture) area, summed over the whole field."], "id": "w08-p2-b", "label": "b"}, {"prompt": "Sunlight is the field $\\mathbf F=(0,0,-900)$ W/m$^2$ and $D$ is the shadow of one module. Which integral gives the solar power hitting that module’s mirror?", "expected": "2", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["The vector (−g_x, −g_y, 1) dA already equals n dS: it includes the area factor.", "The option with the length of F ignores the angle and would count light that only grazes the glass."], "options": ["$-\\iint_D\\mathbf F\\cdot(-g_x,-g_y,1)\\sqrt{1+g_x^2+g_y^2}\\,dA$", "$\\iint_D\\|\\mathbf F\\|\\sqrt{1+g_x^2+g_y^2}\\,dA$", "$-\\iint_D\\mathbf F\\cdot(-g_x,-g_y,1)\\,dA$", "$-\\iint_D\\mathbf F\\cdot\\dfrac{(-g_x,-g_y,1)}{\\sqrt{1+g_x^2+g_y^2}}\\,dA$"], "id": "w08-p2-c", "label": "c"}], "solution": ["$g_x=2x/6.8=x/3.4$ and $g_y=0$, so $(-g_x,-g_y,1)=(-x/3.4,0,1)$ and $\\cos\\alpha=\\mathbf n\\cdot\\mathbf k=1/\\sqrt{1+x^2/11.56}$: about $1$ at the bottom and $0.76$ at the rim.", "For one module, \\[\\iint_S f\\,dS=\\int_0^{12}\\!\\!\\int_{-2.88}^{2.88}\\frac{900}{\\sqrt{1+x^2/11.56}}\\sqrt{1+\\frac{x^2}{11.56}}\\,dx\\,dy=900(5.76)(12)\\approx62.2\\text{ kW}.\\] Tilted glass receives less light per square metre by exactly the factor by which there is more of it. For the whole field the power is $900\\times1{,}308{,}000$ W $=1177.2$ MW; the 160 MW turbine rating is about 14% of this.", "The glass area is $\\iint_S1\\,dS=12\\int_{-2.88}^{2.88}\\sqrt{1+x^2/11.56}\\,dx\\approx76.67$ m$^2$, about 11% more than the $69.12$ m$^2$ aperture, because the factor exceeds $1$ away from $x=0$. It is an area in m$^2$, never a volume. The collected power depends only on the aperture: that is why plants are rated by aperture area.", "Flux uses $\\mathbf F\\cdot d\\mathbf S=\\mathbf F\\cdot(-g_x,-g_y,1)\\,dA$ with no extra root; here that is $-900\\,dA$, and the minus sign turns the (negative) flux of downward light into absorbed power. The option with an extra root double-counts the area factor; the one with $\\|\\mathbf F\\|$ gives $900\\times$ glass area; the one dividing by the root uses a unit normal but forgets $dS$."], "reflection": "A parabolic trough turns about a single axis, so the sunlight usually arrives at some angle to the plane containing the trough’s axis of symmetry. Should the collected power then go up, down, or stay the same, and which factor in your integral changes?", "extension": false, "id": "w08-p2", "discussionSolution": "It goes down. Only the component of sunlight along the aperture’s normal is collected: if the beam makes an angle $\\beta$ with that normal, the flux through the aperture, and so through the mirror with the same boundary, is multiplied by $\\cos\\beta$. The constant 900 in the integrand becomes $900\\cos\\beta$. This “cosine loss” is why trough fields track the Sun.", "modelSpec": {"data": ["Turbine capacity: $160$ MW", "Solar-field aperture area: $1{,}308{,}000$ m$^2$", "SENER trough: aperture width $5.76$ m, focal length $1.70$ m, module length $12$ m"], "assume": ["Every trough is a perfect parabolic cylinder with the published SENER dimensions", "Direct sunlight of $900$ W/m$^2$ arrives along each trough’s axis of symmetry (perfect tracking)", "Gaps, shading, dust, and reflection losses are ignored"], "model": ["Mirror of one module: $z=g(x,y)=\\dfrac{x^2}{4(1.70)}=\\dfrac{x^2}{6.8}$ over $-2.88\\le x\\le2.88$, $0\\le y\\le12$ (metres)", "Sunlight: $\\mathbf F=(0,0,-900)$ W/m$^2$; focus at height $1.70$ m above the vertex"]}, "photo": {"alt": "Rows of parabolic trough mirrors of Noor Ouarzazate I and II stretching across the desert near Ouarzazate, Morocco", "credit": "Richard Allaway", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/", "page": "https://commons.wikimedia.org/wiki/File:Noor_1_and_2_-_Ouarzazate_Solar_Power_Station_(48962353822).jpg", "file": "w08-p2.jpg"}, "figure": {"alt": "Cross-section of the parabolic trough with vertical sunbeams reflecting to the focus and unit normals drawn at the centre and rim", "caption": "Cross-section of one trough (metres, to scale): $z=x^2/6.8$, aperture $5.76$ m, focus $1.70$ m above the vertex. Orange arrows are upward unit normals.", "file": "w08-p2"}}, {"title": "Walk or run to class in the rain?", "context": "A winter storm rolls in off Monterey Bay just as you leave a UC Santa Cruz lecture hall for a class 100 m away, with no umbrella. Should you walk or run? Physicists still publish on this question: in 2012 F. Bocci showed that the best strategy depends on the shape of the body and on the wind. Flux integrals settle the windless case.", "model": "Typical heavy-rain intensity and drop speed are published; the cylindrical body, still air, and constant speed are assumptions.", "sources": ["usgsrain", "bocci2012"], "work": "Sketch the cylinder from the side and from above, with the rain velocity $(-v,0,-u)$ that the walker sees. Parametrize the side by $\\Phi(\\theta,z)=(0.15\\cos\\theta,0.15\\sin\\theta,z)$ with its domain, and decide whether $\\Phi_\\theta\\times\\Phi_z$ points outward or inward; what happens if you list the parameters in the order $(z,\\theta)$? Compute the flux of $\\mathbf F$ through the top disk with the upward normal and explain its sign. On the front half ($\\cos\\theta>0$), water lands at $g=\\rho v\\cos\\theta$ per square metre of shirt per second: compute the scalar surface integral $\\iint g\\,dS$ over the front half and compare it with your answer to (b). Finally explain why the outward flux of $\\mathbf F$ through the whole side is $0$, and why that is not the amount of water you collect.", "questions": [{"prompt": "Enter $\\Phi_\\theta\\times\\Phi_z$ as a function of theta.", "expected": ["0.15*cos(theta)", "0.15*sin(theta)", "0"], "units": "m", "kind": "vector", "tolerance": 1e-05, "hints": ["Φ_θ = (−0.15 sin θ, 0.15 cos θ, 0) and Φ_z = (0, 0, 1).", "Check the direction at θ = 0: does it point away from the axis?"], "id": "w08-p3-a", "label": "a"}, {"prompt": "Walking at v = 1.5 m/s, find the outward flux of F through the front half of the side (cos θ ≥ 0), in millilitres per second (1 m³ = 1,000,000 mL).", "expected": "-10^6*2*0.15*1.7*(0.0152/3600/6.7)*1.5", "units": "mL/s", "kind": "number", "tolerance": 1e-05, "hints": ["On the side, F · (Φ_θ × Φ_z) = −0.15 ρ v cos θ; integrate over −π/2 ≤ θ ≤ π/2 and 0 ≤ z ≤ 1.7.", "ρ = R/u with R = 0.0152/3600 m/s and u = 6.7 m/s. Expect a negative answer."], "id": "w08-p3-b", "label": "b"}, {"prompt": "Find the total water (in mL) that lands on you while you cross the 100 m at constant speed v, as a function of v. Count the top disk and the front half only.", "expected": "10^8*(0.0152/3600)*(pi*0.15^2/v+2*0.15*1.7/6.7)", "units": "mL", "kind": "expression", "tolerance": 1e-05, "hints": ["The trip takes 100/v seconds.", "Per second: R times the disk area through the top, and ρv times 2(0.15)(1.7) through the front."], "id": "w08-p3-c", "label": "c"}], "solution": ["$\\Phi_\\theta=(-0.15\\sin\\theta,0.15\\cos\\theta,0)$, $\\Phi_z=(0,0,1)$, so $\\Phi_\\theta\\times\\Phi_z=(0.15\\cos\\theta,0.15\\sin\\theta,0)$ on $0\\le\\theta\\le2\\pi$, $0\\le z\\le1.7$. At $\\theta=0$ it is $(0.15,0,0)$, pointing away from the axis: outward. Listing the parameters as $(z,\\theta)$ gives $\\Phi_z\\times\\Phi_\\theta=-(\\Phi_\\theta\\times\\Phi_z)$, the inward normal; to keep the outward orientation, negate it.", "Here $\\rho=R/u=(0.0152/3600)/6.7\\approx6.30\\times10^{-7}$: rain is less than a millionth water by volume. The top disk has upward normal $\\mathbf k$, and $\\mathbf F\\cdot\\mathbf k=-\\rho u=-R$, so its flux is $-R\\pi(0.15)^2\\approx-0.298$ mL/s, the same at any speed. It is negative because rain moves down through a disk oriented up.", "On the side, $\\mathbf F\\cdot(\\Phi_\\theta\\times\\Phi_z)=-0.15\\rho v\\cos\\theta$. Over the front half, \\[\\int_0^{1.7}\\!\\!\\int_{-\\pi/2}^{\\pi/2}-0.15\\rho v\\cos\\theta\\,d\\theta\\,dz=-2(0.15)(1.7)\\rho v\\approx-0.482\\text{ mL/s}\\] at $v=1.5$ m/s. The scalar integral $\\iint g\\,dS$ with $dS=0.15\\,d\\theta\\,dz$ gives $+0.482$ mL/s: the same size, but positive, because scalar integrals carry no orientation. The back half has outward flux $+0.482$, so the whole side gives $0$ (a constant field enters and leaves equally), but your body blocks the rain, so the back stays dry and only the inward flux wets you.", "Total: $W(v)=\\dfrac{100}{v}\\big(R\\pi(0.15)^2+2(0.15)(1.7)\\rho v\\big)\\times10^6=\\dfrac{29.85}{v}+32.14$ mL. Walking ($v=1.5$) collects about $52$ mL, running ($v=5$) about $38$ mL. The front term does not depend on speed: you sweep out the same rainy volume however fast you go. Running only shortens the time the top is exposed."], "reflection": "A 2 m/s tailwind blows the rain forward, in your direction of travel. At what running speed does the front of your shirt stay dry, and what does this suggest about Bocci’s finding that shape and wind matter?", "extension": false, "id": "w08-p3", "discussionSolution": "In your frame the rain’s horizontal velocity is 2 − v, which is zero at v = 2 m/s: then only the top gets wet. Faster running wets your front, slower wets your back. With wind an optimal speed can exist, and how much it helps depends on the ratio of top area to front area, that is, on the body’s shape.", "modelSpec": {"data": ["Heavy rain (typical): intensity $1.52$ cm/h", "Median drop diameter $2.05$ mm; fall velocity $6.7$ m/s"], "assume": ["Your body is a vertical cylinder of radius $0.15$ m and height $1.7$ m", "Still air: rain falls straight down at $u=6.7$ m/s; you move in the $+x$ direction at constant speed $v$", "Rain only lands on surfaces moving into it; your body shelters its back half", "The class is $100$ m away"], "model": ["Rain rate $R=0.0152/3600$ m/s; water fraction of the air $\\rho=R/u$", "In your frame, rain velocity $(-v,0,-u)$; water-flux field $\\mathbf F=\\rho\\,(-v,0,-u)$ (m$^3$ of water per m$^2$ per s)", "Body: side $x^2+y^2=0.15^2$, $0\\le z\\le1.7$, and top disk at $z=1.7$"]}, "photo": {"alt": "A rain-soaked footbridge through misty redwood and oak forest on the UC Santa Cruz campus", "credit": "Busition", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/", "page": "https://commons.wikimedia.org/wiki/File:UC_Santa_Cruz_Bridge.jpg", "file": "w08-p3.jpg"}, "figure": {"alt": "Side view of a cylinder representing a walker, with slanted rain arrows in the walker’s frame; the top disk and the front half are highlighted", "caption": "The model in the walker’s frame: rain arrives with velocity $(-v,0,-u)$. The top disk and the front half (teal) are wetted; the back half is sheltered.", "file": "w08-p3"}}, {"title": "How fast is the universe making room?", "context": "Distant galaxies are moving apart, each at a speed proportional to its distance: Hubble’s law, $\\mathbf v=H_0\\mathbf r$. Two of the best measurements of $H_0$ disagree, the “Hubble tension”: the Planck satellite’s map of the early universe gives 67.4 km/s per megaparsec, while Cepheid stars and supernovae (the SH0ES team, using the Hubble Space Telescope) give 73.04. A flux integral turns $H_0$ into the rate at which a region of space gains volume.", "model": "The values of the Hubble constant are published; treating the galaxies as a smooth fluid moving exactly with the Hubble flow is a model.", "sources": ["planck2018", "shoes2022", "pdgastro"], "work": "Sketch $W$ with a few velocity arrows on its dome and on its base. Give the outward unit normal on the dome and on the base, and compute $\\mathbf v\\cdot\\mathbf n$ on each without parametrizing. Explain why the base contributes nothing even though the galaxies on it are moving. Compare the total outward flux with the volume of $W$: what is the ratio, and what does it mean for a region carried along by the flow? Finally, for a sphere of radius $a$ centred on another galaxy at position $\\mathbf p$, write $\\mathbf v=H(\\mathbf r-\\mathbf p)+H\\mathbf p$ and use symmetry to explain why its flux matches a sphere centred on us.", "questions": [{"prompt": "Find the outward flux of v through the dome (the curved part only), as a function of a.", "expected": "2*pi*0.0689*a^3", "units": "Mpc³/Gyr", "kind": "expression", "tolerance": 0.002, "hints": ["On the dome n = r/a, so v · n = H a everywhere.", "Multiply by the hemisphere’s area 2πa²."], "id": "w08-p4-a", "label": "a"}, {"prompt": "Find (total outward flux through dome and base) divided by the volume of W.", "expected": "3*0.0689", "units": "per Gyr", "kind": "number", "tolerance": 1e-05, "hints": ["On the base the outward normal is (0, 0, −1), and v · n = −H z = 0 there.", "The half-ball’s volume is (2/3)πa³."], "decimals": 3, "id": "w08-p4-b", "label": "b"}, {"prompt": "Find the outward flux of $\\mathbf v$ through the sphere of radius $a$ centred on another galaxy at position $\\mathbf p$, as a function of a.", "expected": "4*pi*0.0689*a^3", "units": "Mpc³/Gyr", "kind": "expression", "tolerance": 0.002, "hints": ["On this sphere n = (r − p)/a, so v · n = H a + H p · n.", "The constant field H p has zero net flux through the sphere: p · n is odd under n → −n."], "id": "w08-p4-c", "label": "c"}], "solution": ["On the dome $\\mathbf n=\\mathbf r/a$ and $\\mathbf v\\cdot\\mathbf n=H\\,\\mathbf r\\cdot\\mathbf r/a=Ha$, a constant, so the flux is $Ha\\cdot2\\pi a^2=2\\pi Ha^3\\approx0.433\\,a^3$ Mpc$^3$/Gyr with $H=0.0689$ Gyr$^{-1}$.", "On the base $z=0$, the outward normal points down, $\\mathbf n=(0,0,-1)$, and $\\mathbf v\\cdot\\mathbf n=-Hz=0$: galaxies in that plane move along it, not across it. Total outward flux $=2\\pi Ha^3$.", "Dividing by the volume $\\tfrac23\\pi a^3$ gives $3H\\approx0.207$ per Gyr: any region carried by the flow gains about 21% of its volume per billion years at today’s rate (with the SH0ES value, $3\\times0.0747\\approx0.224$). The ratio does not depend on $a$.", "On the sphere about $\\mathbf p$, $\\mathbf v\\cdot\\mathbf n=Ha+H\\,\\mathbf p\\cdot\\mathbf n$. The first term gives $4\\pi Ha^3$; the second integrates to zero because opposite points have opposite $\\mathbf n$. So the flux is $4\\pi Ha^3$, the same as for a sphere centred on the Milky Way: every galaxy sees the same expansion, and there is no centre."], "reflection": "The ratio in (b) was the same for the half-ball and for any sphere. Guess the ratio for a cube of side s centred on us, check it face by face, and say what general theorem this previews.", "extension": false, "id": "w08-p4", "discussionSolution": "Also 3H. For the cube centred on us, the face x = s/2 has v · n = Hs/2 and area s², so it contributes Hs³/2; six faces give 3Hs³, and dividing by the volume s³ gives 3H = div v. The Divergence Theorem says that the outward flux through any closed surface equals the integral of div v over the enclosed volume.", "modelSpec": {"data": ["Planck 2018: $H_0=67.4\\pm0.5$ km/s/Mpc", "SH0ES 2022: $H_0=73.04\\pm1.04$ km/s/Mpc", "Conversion: $100$ km/s/Mpc $=(9.777752$ Gyr$)^{-1}$, so $67.4$ km/s/Mpc $\\approx0.0689$ Gyr$^{-1}$"], "assume": ["Galaxies move exactly with the Hubble flow (no local motions), with the Milky Way at the origin", "Use the Planck value $H=0.0689$ Gyr$^{-1}$; lengths in Mpc, times in Gyr"], "model": ["Velocity field: $\\mathbf v=H(x,y,z)$ Mpc/Gyr", "Region $W$: the half-ball $x^2+y^2+z^2\\le a^2$, $z\\ge0$ (a dome and a flat base disk in the plane $z=0$)"]}, "photo": {"alt": "The Hubble Ultra Deep Field: thousands of distant galaxies of many shapes and colours scattered across a black sky", "credit": "NASA and the European Space Agency", "license": "Public domain", "licenseUrl": "", "page": "https://commons.wikimedia.org/wiki/File:Hubble_ultra_deep_field.jpg", "file": "w08-p4.jpg"}, "figure": {"alt": "Cross-section of the half-ball region with radial velocity arrows growing with distance from the centre, including arrows lying along the flat base", "caption": "The region $W$ (cross-section): Hubble-flow arrows $\\mathbf v=H\\mathbf r$ on the dome and along the base $z=0$.", "file": "w08-p4"}}, {"title": "Saharan dust across the Atlantic", "context": "Every year the trade winds lift dust off the Sahara and carry it west across the Atlantic. Using NASA’s CALIPSO satellite, which tracked the dust in three dimensions from 2007 to 2013, a team led by Hongbin Yu estimated how much dust crosses “curtains” of air at fixed longitudes, and how much falls on the Amazon rainforest, where its phosphorus acts as fertilizer.", "model": "The yearly dust totals are published multi-year averages; the curtain size, horizontal westward motion, and steady state are assumptions.", "sources": ["saharadust"], "work": "Sketch the curtain at $15^\\circ$W and the box between it and the curtain at $35^\\circ$W, marking which way each outward normal points. For the tilted curtain $x=g(y,z)=-z/5$, compute $\\Phi_y\\times\\Phi_z$ for $\\Phi(y,z)=(g(y,z),y,z)$, decide whether it points east or west, and write the westward vector area element. Explain why tilting the curtain does not change the flux when the dust moves horizontally (compare the curtain with its shadow on the plane $x=0$). Then write the budget for the closed box (east face, west face, bottom, top, sides) and explain why, in steady state, the total outward flux must be zero.", "questions": [{"prompt": "What is the average westward dust flux (mass per square metre per year) through the 15°W curtain?", "expected": "182*10^9/(3*10^6*5*10^3)", "units": "kg/(m²·yr)", "kind": "number", "tolerance": 1e-05, "hints": ["182 million tonnes is 1.82e11 kg.", "The curtain is 3000 km by 5 km; convert both to metres."], "id": "w08-p5-a", "label": "a"}, {"prompt": "Find the westward flux of the dust through the tilted curtain x = −z/5 (same y and z ranges), in millions of tonnes per year.", "expected": "182", "units": "Mt/yr", "kind": "number", "tolerance": 1e-05, "hints": ["With the westward element (−1, g_y, g_z) dy dz, F · dS = f(y, z) dy dz.", "That is the same integrand, over the same rectangle, as for the vertical curtain."], "id": "w08-p5-b", "label": "b"}, {"prompt": "How much dust per year falls into the ocean between 15°W and 35°W, in millions of tonnes?", "expected": "182-132", "units": "Mt/yr", "kind": "number", "tolerance": 1e-05, "hints": ["Outward flux: −182 through the east face (dust enters) and +132 through the west face.", "The bottom’s outward normal points down; top and sides carry nothing in the model."], "id": "w08-p5-c", "label": "c"}], "solution": ["$182$ million tonnes $=1.82\\times10^{11}$ kg per year through $3\\times10^6\\cdot5\\times10^3=1.5\\times10^{10}$ m$^2$ gives about $12.13$ kg per m$^2$ per year: the flux of the mass-flux field divided by the area.", "For $\\Phi(y,z)=(-z/5,y,z)$, $\\Phi_y=(0,1,0)$ and $\\Phi_z=(-\\tfrac15,0,1)$, so $\\Phi_y\\times\\Phi_z=(1,0,\\tfrac15)$, which points east. The westward element is $(-1,0,-\\tfrac15)\\,dy\\,dz$, and with $\\mathbf F=(-f,0,0)$, $\\mathbf F\\cdot d\\mathbf S=f\\,dy\\,dz$: the same integral as for the vertical curtain. Only the projection onto the plane perpendicular to the flow matters, so the flux is still $182$ Mt/yr.", "For the box, outward fluxes are $-182$ (east face, dust entering), $+132$ (west face), $0$ (top and sides, by assumption), and the bottom, whose outward normal points down, carries the deposition $D$. No dust is created or stored inside in steady state, so $-182+132+D=0$ and $D=50$ Mt/yr.", "Of the 182 Mt/yr leaving Africa, about 27.7 Mt/yr ($15\\%$) later falls on the Amazon basin and about 43 Mt/yr reaches the Caribbean."], "reflection": "The bowed or tilted curtain gave the same flux as the flat one. What physical assumption made that true, and would it still hold if dust were settling downward between the two curtains?", "extension": true, "id": "w08-p5", "discussionSolution": "The dust motion was assumed horizontal and steady, so no dust crosses the region between the two curtains’ surfaces: together with the top, bottom, and side strips they enclose no source or sink. If dust settles out between them, the region loses dust through its floor, and the farther (westward) curtain carries slightly less.", "modelSpec": {"data": ["Dust carried past $15^\\circ$W: $182$ million tonnes per year", "Still airborne at $35^\\circ$W: $132$ million tonnes per year", "Falling on the Amazon basin: $27.7$ million tonnes per year; past $75^\\circ$W: about $43$ million"], "assume": ["The curtain at $15^\\circ$W is a vertical rectangle $3000$ km wide (north–south) and $5$ km tall", "Dust moves horizontally westward; nothing crosses the top or the north and south sides of the box between $15^\\circ$W and $35^\\circ$W", "Steady state: the yearly averages do not change"], "model": ["$x$ east, $y$ north, $z$ up (km); curtain: $x=0$, $0\\le y\\le3000$, $0\\le z\\le5$", "Dust mass flux: $\\mathbf F=(-f(y,z),0,0)$, with $\\iint f\\,dy\\,dz=182$ Mt/yr over the curtain", "Tilted curtain: $x=-z/5$ over the same $y$, $z$ rectangle"]}, "figure": {"alt": "Schematic of the Atlantic between West Africa and South America with curtains at 15 degrees west and 35 degrees west and dust arrows", "caption": "Schematic (not to scale): dust crossing the curtains at $15^\\circ$W and $35^\\circ$W, and the closed box between them.", "file": "w08-p5"}}]}, {"week": 9, "title": "Boundaries that know the inside", "subtitle": "It’s Not Easy Being Green", "skills": ["Orient boundaries positively, including regions with holes", "Verify Green’s theorem edge by edge and use it to skip hard line integrals", "Find areas and centroids from boundary data (ellipses, polygons, planimeters)", "Handle singularities by excising a small circle; know when circulation is zero", "Review: sphere symmetry for surface integrals and flux"], "formulas": ["$\\oint_{\\partial D}P\\,dx+Q\\,dy=\\iint_D\\Big(\\dfrac{\\partial Q}{\\partial x}-\\dfrac{\\partial P}{\\partial y}\\Big)dA$, $\\partial D$ positively oriented (region on the left), $P,Q$ continuously differentiable on an open set containing $D$", "$A=\\oint_{\\partial D}x\\,dy=-\\oint_{\\partial D}y\\,dx=\\tfrac12\\oint_{\\partial D}x\\,dy-y\\,dx$", "Flux form: $\\oint_{\\partial D}\\mathbf F\\cdot\\mathbf n\\,ds=\\oint_{\\partial D}F_1\\,dy-F_2\\,dx=\\iint_D\\Big(\\dfrac{\\partial F_1}{\\partial x}+\\dfrac{\\partial F_2}{\\partial y}\\Big)dA$"], "sources": ["noaastations", "bermuda", "orange", "haiyan", "waterpolo", "agulhas"], "problems": [{"title": "Measuring the Bermuda Triangle from its edges", "context": "Since a 1964 magazine article, the “Bermuda Triangle” between Miami, Bermuda, and San Juan has been blamed for vanished ships and planes; NOAA finds no evidence that disappearances there are any more frequent than elsewhere. Its shape is still a good test of a remarkable idea. Before computers, chart-makers measured areas by tracing a boundary with a planimeter, and today mapping software finds areas and centers from boundary coordinates alone. How can the edge know what is inside?", "model": "The three station positions are published; the vertices, the flat chart, the rounding, and the idealized planimeter are modeling choices.", "sources": ["noaastations", "bermuda"], "work": "Orient the triangle’s boundary positively (in which order are the vertices visited?) and parametrize each edge for $0\\le t\\le1$. State the hypotheses of Green’s theorem and check them for the planimeter field; why must $|y|<L$ on the whole region? Show the wheel roll is $A/L$ for any traced region, and say what the wheel shows if the operator traces clockwise. Verify part (c) with the double integral $\\iint_T2x\\,dA$, then find the centroid’s $\\bar x=\\frac1{2A}\\oint x^2\\,dy$ and say where it is. Review: compute the scalar integral $\\int x\\,ds$ along the Miami–San Juan edge.", "questions": [{"prompt": "Use $A=\\tfrac12\\oint x\\,dy-y\\,dx$ with $x=6\\cos t$, $y=4\\sin t$ to find the area of the calibration ellipse.", "expected": "24*pi", "units": "cm²", "kind": "number", "tolerance": 1e-05, "hints": ["x dy − y dx = (6 cos t)(4 cos t) dt − (4 sin t)(−6 sin t) dt = 24 dt.", "Integrate over 0 ≤ t ≤ 2π and halve."], "id": "w09-p1-a", "label": "a"}, {"prompt": "Find the wheel roll when the tracer goes once counterclockwise around the triangle.", "expected": "11.3", "units": "cm", "kind": "number", "tolerance": 1e-05, "hints": ["For P = −y/L and Q = √(L² − y²)/L, Q depends on y only, so Q_x − P_y = 1/L.", "So the roll is (area)/L; the triangle’s area is half the cross product of the edge vectors from M."], "id": "w09-p1-b", "label": "b"}, {"prompt": "Compute $\\oint_{\\partial T}x^2\\,dy$ edge by edge, with $\\partial T$ positively oriented.", "expected": "2260", "units": "cm³", "kind": "number", "tolerance": 1e-05, "hints": ["Edge M to S: x = 14t, dy = −8 dt. Edge S to B: x = 14 + 2t, dy = 15 dt. Edge B to M: x = 16 − 16t, dy = −7 dt.", "The three pieces are −1568/3, 3380, and −1792/3."], "id": "w09-p1-c", "label": "c"}], "solution": ["Counterclockwise order is M $\\to$ S $\\to$ B $\\to$ M, since $(14,-8)\\times(16,7)=14\\cdot7+8\\cdot16=226>0$. Area: $A=\\tfrac12(226)=113$ cm$^2$, i.e. $1.13$ million km$^2$ (the spherical triangle through the three stations has about $1.15$ million km$^2$).", "Ellipse: $\\tfrac12\\int_0^{2\\pi}24\\,dt=24\\pi\\approx75.40$ cm$^2$. Planimeter: $P=-y/L$, $Q=\\sqrt{L^2-y^2}/L$ are continuously differentiable where $|y|<L$, so with $L=10$ cm and $-8\\le y\\le7$ Green applies: roll $=\\iint_T(0+\\tfrac1L)\\,dA=A/L=11.3$ cm. The awkward $\\sqrt{L^2-y^2}\\,dy$ term never needs integrating. Tracing clockwise reverses the boundary, and the wheel reads $-11.3$ cm.", "Edges: $\\int_0^1(14t)^2(-8)\\,dt=-\\tfrac{1568}3$; $\\int_0^1(14+2t)^2(15)\\,dt=15(196+28+\\tfrac43)=3380$; $\\int_0^1(16-16t)^2(-7)\\,dt=-\\tfrac{1792}3$. Total $=2260$ cm$^3$.", "Double integral ($Q=x^2$, $P=0$): $\\iint_T2x\\,dA=2A\\bar x$. Since $\\bar x=(0+14+16)/3=10$ for a triangle, this is $2(113)(10)=2260$, matching. So $\\bar x=10$ cm, about 1,000 km east of Miami; similarly $\\bar y=-\\tfrac13$ cm, a point in open ocean north of Hispaniola.", "Review: on M to S, $\\mathbf c(t)=(14t,-8t)$ has speed $\\sqrt{260}$, so $\\int x\\,ds=\\int_0^1 14t\\sqrt{260}\\,dt=7\\sqrt{260}\\approx112.9$ cm$^2$."], "reflection": "Writers have given the Triangle areas from 1.3 to 3.9 million km². What does that range tell you, and what would you need before trusting any claim that the region is unusually dangerous?", "extension": false, "id": "w09-p1", "discussionSolution": "The “region” has no agreed boundary: its area depends on which vertices a writer chose, so it is a story, not a measurement. Before claiming danger you would need a fixed boundary, counts of incidents, and the amount of shipping and air traffic inside it, compared with other busy regions. NOAA finds no evidence of excess losses.", "modelSpec": {"data": ["NOAA stations: Virginia Key (Miami) $25.73^\\circ$ N $80.16^\\circ$ W; Bermuda $32.37^\\circ$ N $64.70^\\circ$ W; San Juan $18.46^\\circ$ N $66.12^\\circ$ W", "Vertices (Gaddis, 1964): Miami, San Juan, Bermuda"], "assume": ["A flat chart: east–west and north–south distances in km at latitude $25.5^\\circ$ N, drawn at 1 cm $=100$ km", "Vertices rounded to the nearest 100 km", "Idealized linear planimeter: the arm (length $L=10$ cm) slides along a rail on the $x$-axis; the wheel at the tracer rolls by the motion perpendicular to the arm"], "model": ["Triangle $T$ (cm): M $=(0,0)$, S $=(14,-8)$, B $=(16,7)$", "Wheel roll: $\\dfrac1L\\oint_C-y\\,dx+\\sqrt{L^2-y^2}\\,dy$", "Calibration ellipse: $x=6\\cos t$, $y=4\\sin t$ cm, $0\\le t\\le2\\pi$"]}, "photo": {"alt": "A Keuffel and Esser polar planimeter, with its tracing arm and measuring wheel, in a green-lined case in front of a map", "credit": "Cantons-de-l'Est", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "page": "https://commons.wikimedia.org/wiki/File:Planim%C3%A8tre_Keuffel_%26_Esser.jpg", "file": "w09-p1.jpg"}, "figure": {"alt": "Chart of the triangle with vertices Miami at the origin, San Juan at (14, -8), and Bermuda at (16, 7), a planimeter rail along the x-axis with an arm to the tracer, and a calibration ellipse", "caption": "The chart model (1 cm $=100$ km) with the idealized planimeter: the arm’s foot slides on the rail ($y=0$); the wheel at the tracer rolls by the motion perpendicular to the arm.", "file": "w09-p1"}}, {"title": "Every seat in the Roman theatre at Orange", "context": "The Roman theatre at Orange, in southern France, still has its stone seating: a half-ring wrapped around a semicircular orchestra, facing the stage. How much seating area is there, and how far from the front of the stage does the average spectator sit? A surveyor’s software answers both questions by walking the boundary.", "model": "Both diameters are published; the exact half-ring, rounded radii, and flat plan view are assumptions.", "sources": ["orange"], "work": "Sketch $D$, mark its four boundary pieces, and orient each one so that $D$ stays on the left. Explain why the inner arc must be traversed clockwise. Which pieces contribute to $-\\tfrac12\\oint y^2\\,dx$, and why do the two straight pieces contribute nothing? Use Green’s theorem to turn the area and the first-moment boundary integrals into double integrals, and evaluate them in polar coordinates. Check the outer-arc piece directly with a parametrization. Finally find $\\bar y$, and estimate the capacity at $0.5$ m$^2$ per spectator.", "questions": [{"prompt": "Find the seating area $A$.", "expected": "1239.5*pi", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["Green’s theorem with ½(x dy − y dx) turns the boundary integral into ∬ 1 dA.", "In polar coordinates: ∫₀^π ∫ from 15 to 52 of r dr dθ."], "id": "w09-p2-a", "label": "a"}, {"prompt": "Find the inner arc’s contribution to $-\\tfrac12\\oint_{\\partial D}y^2\\,dx$.", "expected": "-2250", "units": "m³", "kind": "number", "tolerance": 1e-05, "hints": ["Positively oriented, the inner arc runs clockwise from (−15, 0) to (15, 0): x = 15 cos t, y = 15 sin t, with t going from π to 0.", "−½ y² dx = (15³/2) sin³t dt, and ∫₀^π sin³t dt = 4/3."], "id": "w09-p2-b", "label": "b"}, {"prompt": "Find the first moment $M=-\\tfrac12\\oint_{\\partial D}y^2\\,dx=\\iint_D y\\,dA$.", "expected": "2/3*(52^3-15^3)", "units": "m³", "kind": "number", "tolerance": 1e-05, "hints": ["Green with P = −y²/2, Q = 0 gives Q_x − P_y = y.", "∬ y dA = ∫₀^π sin θ dθ · ∫ from 15 to 52 of r² dr."], "id": "w09-p2-c", "label": "c"}], "solution": ["$D$: $15\\le r\\le52$, $0\\le\\theta\\le\\pi$. Positive boundary: the segment from $(15,0)$ to $(52,0)$; the outer arc counterclockwise to $(-52,0)$; the segment to $(-15,0)$; the inner arc clockwise back to $(15,0)$. On the inner arc the region lies outside the small circle, so keeping it on the left means going clockwise.", "Area: $A=\\iint_D1\\,dA=\\int_0^\\pi\\!\\int_{15}^{52}r\\,dr\\,d\\theta=\\tfrac\\pi2(52^2-15^2)=1239.5\\pi\\approx3894.0$ m$^2$.", "On the segments $y=0$, so $y^2\\,dx=0$. Outer arc: $x=52\\cos t$, $y=52\\sin t$, $0\\le t\\le\\pi$, gives $-\\tfrac12\\int_0^\\pi52^2\\sin^2t(-52\\sin t)\\,dt=\\tfrac{52^3}2\\cdot\\tfrac43=\\tfrac23(52^3)$. Inner arc (clockwise): $-\\tfrac23(15^3)=-2250$.", "Green: $M=\\iint_D y\\,dA=\\int_0^\\pi\\sin\\theta\\,d\\theta\\int_{15}^{52}r^2\\,dr=\\tfrac23(52^3-15^3)\\approx91{,}488.7$ m$^3$, matching the two arcs. So $\\bar y=M/A\\approx23.5$ m from the stage line.", "Capacity: $3894/0.5\\approx7800$ spectators, a little above the published 5,850 to 7,300; aisles, stairs, and the stage-side walls take part of the plan area."], "reflection": "Real Roman seating rises in stone steps away from the stage. Is the plan-view area you found more or less than the actual stone seat surface, and is $\\bar y$ the same as the average distance from a seat to the actors?", "extension": false, "id": "w09-p2", "discussionSolution": "The stepped seats rise away from the stage, so the actual stone surface (seat tops plus risers) is larger than the plan-view area, which is a projection. $\\bar y$ is only the average horizontal distance from the stage line; the distance to the actors also includes sideways offset and the height of the upper rows.", "modelSpec": {"data": ["Seating diameter: $103.63$ m", "Orchestra diameter: $29.9$ m", "Capacity: 5,850 to 7,300"], "assume": ["The seating is a flat half-ring in plan view, with radii rounded to $15$ m and $52$ m", "The front of the stage is the line $y=0$; aisles and stairs are ignored"], "model": ["$D$: $15\\le r\\le52$, $0\\le\\theta\\le\\pi$ (metres)", "Area $A=\\tfrac12\\oint_{\\partial D}x\\,dy-y\\,dx$; first moment $M=-\\tfrac12\\oint_{\\partial D}y^2\\,dx$; $\\bar y=M/A$"]}, "photo": {"alt": "Wide view of the Roman theatre at Orange: curved rows of stone seating wrap around the semicircular orchestra, facing the tall stage wall", "credit": "Benh LIEU SONG (Flickr)", "license": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "page": "https://commons.wikimedia.org/wiki/File:Roman_Theatre_in_Orange_2008.jpg", "file": "w09-p2.jpg"}, "figure": {"alt": "Plan view of a half-ring seating area between radii 15 m and 52 m above the stage line", "caption": "Plan view of the model seating $D$, with the stage front along $y=0$.", "file": "w09-p2"}}, {"title": "Circulation around Typhoon Haiyan", "context": "Typhoon Haiyan crossed the central Philippines on 8 November 2013 with 10-minute winds of 65 m/s (about 230 km/h). Japan’s Meteorological Agency, the regional center for the western Pacific, reported storm-force winds out to 150 km from the center. Outside the eye, the wind is roughly an ideal vortex whose speed falls off like 1/r. What is its circulation, and does the shape of the loop matter?", "model": "The wind radii and peak wind are published; the ideal-vortex model, its calibration, and the loops are assumptions.", "sources": ["haiyan"], "work": "Compute $Q_x-P_y$ for $r>0$. Explain why Green’s theorem on the disk $r\\le150$ km would wrongly predict zero circulation in part (a). For part (b), excise a small circle $C_\\varepsilon$ around the center, orient the boundary of the region between $C_\\varepsilon$ and the ellipse positively, and conclude without parametrizing the ellipse. Explain part (c) with Green’s theorem. Model check: what wind speed does the model predict at JMA’s gale radius of 460 km, and at what radius does it reach 65 m/s? What do these say about the 1/r model?", "questions": [{"prompt": "Find the circulation of the wind around the circle of radius 150 km centered on the eye, counterclockwise.", "expected": "27000*pi", "units": "km²/h", "kind": "number", "tolerance": 1e-05, "hints": ["On the circle the wind is tangent, counterclockwise, with speed 90 km/h.", "Circulation = (speed) × (length of the circle)."], "id": "w09-p3-a", "label": "a"}, {"prompt": "Find the circulation around the ellipse $x^2/300^2+y^2/200^2=1$, traversed clockwise.", "expected": "-27000*pi", "units": "km²/h", "kind": "number", "tolerance": 1e-05, "hints": ["Between the ellipse and a small circle the curl is zero, so the two loops (both counterclockwise) have equal circulation.", "Clockwise reverses the sign."], "id": "w09-p3-b", "label": "b"}, {"prompt": "Find the circulation around the circle of radius 100 km centered at (420, 0) km, counterclockwise.", "expected": "0", "units": "km²/h", "kind": "number", "tolerance": 1e-05, "hints": ["This circle does not enclose the eye.", "The field is smooth on the disk it bounds, and its curl is zero there."], "id": "w09-p3-c", "label": "c"}], "solution": ["For $r>0$, with $P=-\\tfrac{\\Gamma}{2\\pi}\\tfrac{y}{x^2+y^2}$ and $Q=\\tfrac{\\Gamma}{2\\pi}\\tfrac{x}{x^2+y^2}$, both partials equal $\\tfrac{\\Gamma}{2\\pi}\\tfrac{y^2-x^2}{(x^2+y^2)^2}$, so $Q_x-P_y=0$. But the field is undefined at the center, which lies in every disk around the eye, so Green’s theorem does not apply there.", "On $r=150$: speed $\\Gamma/(2\\pi\\cdot150)=90$ km/h, so $\\Gamma=2\\pi(150)(90)=27000\\pi\\approx84{,}823$ km$^2$/h, the same on every circle about the eye.", "Let $R_\\varepsilon$ lie between the ellipse and $C_\\varepsilon$ ($\\varepsilon<200$). Its positive boundary is the ellipse counterclockwise plus $C_\\varepsilon$ clockwise. The field is smooth on $R_\\varepsilon$ with zero curl, so $\\oint_{\\text{ellipse, ccw}}=\\oint_{C_\\varepsilon,\\text{ccw}}=\\Gamma$. Clockwise: $-27000\\pi\\approx-84{,}823$ km$^2$/h.", "The disk $(x-420)^2+y^2\\le100^2$ avoids the center, so Green applies and gives $\\iint0\\,dA=0$.", "Model check: at $460$ km the model gives $90\\cdot150/460\\approx29$ km/h $\\approx8$ m/s, but JMA reported gale winds ($\\ge15$ m/s) that far north; real winds fall off more slowly than $1/r$. The model reaches 65 m/s at $150\\cdot25/65\\approx58$ km, while the real eyewall was much closer to the center. The ideal vortex is only a rough description outside the core."], "reflection": "The circulation around any loop that encloses the eye once is the same. What would it be for a loop that circles the eye twice, and what does that suggest about what the circulation “counts”?", "extension": false, "id": "w09-p3", "discussionSolution": "Twice the circulation, $2\\Gamma$: excising the center shows that any loop’s circulation is $\\Gamma$ times the number of times it winds counterclockwise around the eye. The circulation counts the vorticity concentrated in the core (here idealized as a point), not the details of the loop.", "modelSpec": {"data": ["Maximum 10-minute wind: $65$ m/s; central pressure $895$ hPa", "Storm-force winds ($\\ge25$ m/s $=90$ km/h) out to $150$ km", "Gale winds ($\\ge15$ m/s) out to $460$ km (north), $330$ km (south)"], "assume": ["Outside the eye, the wind is an ideal counterclockwise vortex, calibrated so its speed is $90$ km/h at $r=150$ km", "The model is not valid in the eye; the field is undefined at the center", "Flat map in km, eye at the origin"], "model": ["$\\mathbf v(x,y)=\\dfrac{\\Gamma}{2\\pi}\\,\\dfrac{(-y,\\ x)}{x^2+y^2}$ km/h, with speed $\\Gamma/(2\\pi r)$", "Loops: the circle $r=150$; the ellipse $x^2/300^2+y^2/200^2=1$; the circle of radius $100$ about $(420,0)$"]}, "photo": {"alt": "Typhoon Haiyan seen from the International Space Station: a vast spiral of cloud over the western Pacific, with part of the station at the edge", "credit": "NASA/Karen Nyberg", "license": "Public domain", "licenseUrl": "", "page": "https://commons.wikimedia.org/wiki/File:Typhoon_Haiyan_viewed_from_International_Space_Station.jpg", "file": "w09-p3.jpg"}, "figure": {"alt": "Wind arrows circling counterclockwise around the eye, with the 150 km circle, an ellipse around the eye, and a small circle to the east that does not enclose the eye", "caption": "The ideal-vortex model outside the eye (arrows), and the three loops of parts (a)–(c). Map in km.", "file": "w09-p3"}}, {"title": "Holding a water polo ball underwater", "context": "In water polo, holding the ball underwater is a foul, and it is hard to do anyway. The rules fix the ball’s size and mass. How hard does the water push back, and how is the ball’s mass spread around a spin axis? Both questions are sphere integrals that symmetry finishes almost instantly. (This problem reviews Weeks 7 and 8 for Quiz 3.)", "model": "The ball’s size and mass limits are published; the thin shell, the chosen values, and the still water are assumptions.", "sources": ["waterpolo"], "work": "Explain, without parametrizing, why $\\iint_Sx^2\\,dS=\\iint_Sy^2\\,dS=\\iint_Sz^2\\,dS$ for a sphere centered at the origin, and use $x^2+y^2+z^2=R^2$ to evaluate them. Find the outward unit normal $\\mathbf n$ on $S$ and use it with the symmetry result to compute the flux of $(0,0,z)$; why must $\\mathbf n$ point outward here? Then find the ball’s moment of inertia $I$ and compare it with $\\tfrac25mR^2$ for a solid ball of the same mass. Explain why $\\iint_S z\\,dS=0$ but $\\iint_S z\\,n_z\\,dS>0$.", "questions": [{"prompt": "Enter $\\iint_S x^2\\,dS$ for a sphere of radius r centered at the origin, as a function of r.", "expected": "4*pi*r^4/3", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["The three integrals of x², y², z² are equal, and they add up to the integral of r² over the sphere.", "The sphere’s area is 4πr²."], "id": "w09-p4-a", "label": "a"}, {"prompt": "Find the outward flux $\\iint_S(0,0,z)\\cdot\\mathbf n\\,dS$ through the ball’s surface.", "expected": "4*pi*(35/pi)^3/3", "units": "cm³", "kind": "number", "tolerance": 1e-05, "hints": ["On the sphere, n = (x, y, z)/R, so the integrand is z²/R.", "Use part (a) with R = 35/π cm."], "id": "w09-p4-b", "label": "b"}, {"prompt": "Find the downward push needed to hold the ball completely under water and still.", "expected": "9.81*(1000*4*pi*(0.35/pi)^3/3-0.45)", "units": "N", "kind": "number", "tolerance": 1e-05, "hints": ["The water pushes up with ρg times the flux from part (b), converted to m³.", "Gravity already pulls down 0.45 × 9.81 N; the push supplies the rest."], "id": "w09-p4-c", "label": "c"}], "solution": ["Rotating the axes (x to y to z) maps the sphere and its area element to themselves, so the three integrals are equal. Their sum is $\\iint_S R^2\\,dS=R^2(4\\pi R^2)$, so each is $\\tfrac43\\pi R^4$.", "Outward $\\mathbf n=(x,y,z)/R$, so $(0,0,z)\\cdot\\mathbf n=z^2/R$ and the flux is $\\tfrac1R\\cdot\\tfrac43\\pi R^4=\\tfrac43\\pi R^3$, the ball’s volume. With $R=0.70/(2\\pi)=35/\\pi\\approx11.14$ cm, it is about $5792$ cm$^3$. An inward normal would flip the sign; the pressure force on the ball is computed with the outward normal.", "Up-thrust: $1000(9.81)(0.005792)\\approx56.82$ N. Weight: $0.45(9.81)\\approx4.41$ N. Push: about $52.41$ N, roughly the weight of a 5.3 kg mass.", "Spin: $I=\\frac{m}{4\\pi R^2}\\iint_S(x^2+y^2)\\,dS=\\frac{m}{4\\pi R^2}\\cdot\\frac83\\pi R^4=\\tfrac23mR^2\\approx0.00372$ kg·m$^2$, larger than $\\tfrac25mR^2$ because a shell keeps all its mass at the full radius.", "$\\iint_S z\\,dS=0$ because the top and bottom hemispheres cancel; in $z\\,n_z=z^2/R$ both factors change sign together, so every part contributes positively."], "reflection": "The up-thrust equals ρg times the ball’s volume. Would the same be true for a submerged cube or a cylinder, and why does the sphere’s symmetry make it so quick here?", "extension": false, "id": "w09-p4", "discussionSolution": "Yes: for any closed surface the up-thrust is $\\rho g\\iint_S(0,0,z)\\cdot\\mathbf n\\,dS$, which equals ρg times the enclosed volume (a fact the divergence theorem will explain). For a sphere, symmetry lets us compute that flux without the general theorem, because x², y², and z² have equal integrals.", "modelSpec": {"data": ["Ball mass: $400$ to $450$ g", "Men’s ball circumference: $0.68$ to $0.71$ m"], "assume": ["The ball is a thin uniform spherical shell with circumference $0.70$ m and mass $m=0.45$ kg", "Water density $1000$ kg/m$^3$, $g=9.81$ m/s$^2$; the ball is fully submerged and still"], "model": ["$S$: $x^2+y^2+z^2=R^2$, $R=0.70/(2\\pi)$ m $=35/\\pi$ cm, $z$ measured upward from the ball’s center", "Water’s up-thrust: $\\rho g\\iint_S(0,0,z)\\cdot\\mathbf n\\,dS$ with $\\mathbf n$ outward", "Spin about the $z$-axis: $I=\\dfrac{m}{4\\pi R^2}\\iint_S(x^2+y^2)\\,dS$"]}, "photo": {"alt": "A water polo goalkeeper in a red cap reaches as the ball splashes into the net", "credit": "Ryanjo at English Wikipedia", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "page": "https://commons.wikimedia.org/wiki/File:Water_Polo_Lob.jpg", "file": "w09-p4.jpg"}, "figure": {"alt": "Cross-section of a ball under water, with the z-axis, outward normal arrows, and the water surface above", "caption": "The ball as a sphere of radius $R=35/\\pi$ cm, fully under water, with outward normals.", "file": "w09-p4"}}, {"title": "Agulhas rings: the loop with the most spin", "context": "Off the southern tip of Africa, the Agulhas Current loops back on itself and pinches off giant rings of warm water, about six a year, each 200 to 280 km across and reaching about 1,100 m deep. They drift into the Atlantic, carrying Indian Ocean heat and salt. Inside a ring the water spins; at its edge the spin dies away. Which loop captures the most circulation?", "model": "Ring sizes and rotation sense are published; the swirl profile and its peak speed of about 1 m/s are assumptions.", "sources": ["agulhas"], "work": "Explain why maximizing $\\oint_C\\mathbf u\\cdot d\\mathbf r$ over positively oriented simple closed loops is the same as maximizing $\\iint_D(Q_x-P_y)\\,dA$ over regions $D$, and prove that the disk $r\\le a$ wins: compare any region $D$ with $D\\cap\\{r\\le a\\}$. Check part (b) directly on the circle $r=a$. Flux form: compute the outward flux $\\oint\\mathbf u\\cdot\\mathbf n\\,ds$ across $r=a$ directly, using $\\mathbf n\\,ds=(dy,-dx)$, and compare with $\\iint\\operatorname{div}\\mathbf u\\,dA$.", "questions": [{"prompt": "Enter $Q_x-P_y$ for $\\mathbf u=(P,Q)$ as a function of r.", "expected": "2*6.6/90*(1-r^2/8100)", "units": "1/h", "kind": "expression", "tolerance": 1e-05, "hints": ["Write u = g(r)(−y, x) with g = (6.6/90)(1 − r²/16200).", "Then Q_x − P_y = 2g + r g′(r)."], "id": "w09-p5-a", "label": "a"}, {"prompt": "Find the largest possible circulation around a positively oriented simple closed loop inside the ring.", "expected": "594*pi", "units": "km²/h", "kind": "number", "tolerance": 1e-05, "hints": ["The curl is positive exactly for r < 90 km.", "Integrate the curl over that disk, or use circulation = 2πr × speed at r = 90."], "id": "w09-p5-b", "label": "b"}, {"prompt": "Find the circulation around the ring’s edge, the circle $r=90\\sqrt2$ km, counterclockwise.", "expected": "0", "units": "km²/h", "kind": "number", "tolerance": 1e-05, "hints": ["At the edge the swirl speed is zero.", "Equivalently, the negative curl in the outer band cancels the positive core."], "id": "w09-p5-c", "label": "c"}], "solution": ["With $g(r)=\\frac{V_0}{a}\\big(1-\\frac{r^2}{2a^2}\\big)$ and $\\mathbf u=g(-y,x)$: $Q_x-P_y=2g+rg^{\\prime}=\\frac{2V_0}{a}\\big(1-\\frac{r^2}{a^2}\\big)=\\frac{2(6.6)}{90}\\big(1-\\frac{r^2}{8100}\\big)$ per hour: positive in the core, negative outside $r=a=90$ km.", "For any region $D$, $\\iint_D(Q_x-P_y)\\le\\iint_{D\\cap\\{r\\le a\\}}(Q_x-P_y)\\le\\iint_{r\\le a}(Q_x-P_y)$, because the dropped outer part is negative and the added inner part is positive. Maximum: $2\\pi\\int_0^{90}\\frac{13.2}{90}\\big(1-\\frac{r^2}{8100}\\big)r\\,dr=\\pi(6.6)(90)=594\\pi\\approx1866$ km$^2$/h. Check: at $r=90$ the speed is $3.3$ km/h and $2\\pi(90)(3.3)=594\\pi$.", "At $r=90\\sqrt2$, $1-r^2/(2a^2)=0$, so the speed and the circulation are $0$: the ring’s negative outer vorticity exactly cancels its core.", "Flux form: on $r=a$, $\\mathbf u$ is tangent, so $\\mathbf u\\cdot\\mathbf n=0$ and the outward flux is $0$; also $\\operatorname{div}\\mathbf u=0$, so both sides of the flux form of Green agree."], "reflection": "A ring full of spinning water has zero circulation around its edge. How is that possible, and why might a ring like this hold together while it drifts across an ocean?", "extension": true, "id": "w09-p5", "discussionSolution": "Circulation measures the net vorticity inside the loop: the core spins one way and a surrounding band spins the other way, and the two cancel at the edge. Outside the ring the water is barely disturbed, so the ring is a self-contained (“shielded”) vortex that can travel for months without spreading its spin to the surrounding ocean.", "modelSpec": {"data": ["About six rings a year, $200$ to $280$ km across, reaching about $1100$ m deep", "Rings are anticyclonic (counterclockwise in the Southern Hemisphere)"], "assume": ["Surface swirl speed $v(r)=V_0\\dfrac ra\\Big(1-\\dfrac{r^2}{2a^2}\\Big)$ with $a=90$ km, $V_0=6.6$ km/h (peak about $1$ m/s)", "The ring ends where the swirl stops, at $r=a\\sqrt2\\approx127$ km"], "model": ["$\\mathbf u(x,y)=\\dfrac{6.6}{90}\\Big(1-\\dfrac{x^2+y^2}{16200}\\Big)(-y,\\ x)$ km/h, for $x^2+y^2\\le16200$"]}, "figure": {"alt": "Graph of the model swirl speed of an Agulhas ring against distance from the center, rising to a peak and falling to zero at the ring edge", "caption": "Model swirl speed across the ring; the swirl stops at the ring edge, $r=90\\sqrt2\\approx127$ km.", "file": "w09-p5"}}]}, {"week": 10, "title": "Curl at work", "subtitle": "Curl Power", "skills": ["Compute curl and read it as local rotation: rigid rotation has curl $2\\Omega$, circulation per unit area, paddle-wheel axis", "Use Stokes’ theorem in both directions, with compatible orientations, choosing the easiest surface", "Find potentials by successive integration and use them along any path", "Recognize when zero curl is not enough: removing a line versus a point", "Decide which fields are curls (div curl = 0), build a vector potential, and use it"], "formulas": ["$\\nabla\\times\\mathbf F=\\big(\\partial_yF_3-\\partial_zF_2,\\ \\partial_zF_1-\\partial_xF_3,\\ \\partial_xF_2-\\partial_yF_1\\big)$", "$\\iint_S(\\nabla\\times\\mathbf F)\\cdot d\\mathbf S=\\oint_{\\partial S}\\mathbf F\\cdot d\\mathbf r$ (right-hand rule)", "$\\nabla\\cdot(\\nabla\\times\\mathbf F)=0$; on all of $\\mathbb R^3$: $\\mathbf G=\\nabla\\times\\mathbf A\\iff\\nabla\\cdot\\mathbf G=0$", "Divergence Theorem: $\\iint_{\\partial W}\\mathbf F\\cdot\\mathbf n\\,dS=\\iiint_W\\nabla\\cdot\\mathbf F\\,dV$"], "sources": ["iersconst", "earth", "montereylat", "qispec", "lhcdesign", "lhcquad", "esacluster", "uafelectrojet", "earthheat"], "problems": [{"title": "Earth’s spin as a curl", "context": "Earth turns once each sidereal day, carrying the air, the oceans, and Monterey Bay along with it. Seen from space, everything on the planet shares one rigid rotation. That rotation has a curl, and the curl’s local vertical part is what slowly turns the swing of a Foucault pendulum and gives large ocean eddies and storms their preferred direction of spin.", "model": "The rotation rate, radius, and Monterey’s latitude are published; perfect rigid rotation and a spherical Earth are assumptions, and winds and currents relative to the ground are ignored.", "sources": ["iersconst", "earth", "montereylat"], "work": "Check that $\\boldsymbol\\Omega=(0,0,\\Omega)$ gives $\\mathbf v=\\boldsymbol\\Omega\\times\\mathbf r=\\Omega(-y,x,0)$. The parallel $C$ through Monterey is the circle at height $z=R\\sin L$. Earth carries it eastward: show that this is counterclockwise seen from above the North Pole, and that the compatible normal on the polar cap $S$ north of $C$ points away from Earth’s centre. Compute the flux of $\\nabla\\times\\mathbf v$ through $S$ three ways: directly, using $\\mathbf n=\\mathbf r/R$ and the cap’s symmetry about the axis (with $dS=R^2\\sin\\phi\\,d\\phi\\,d\\theta$ and the right range of $\\phi$); through the flat disk spanning $C$; and as the circulation around $C$. Then take a tiny horizontal circle of radius $\\epsilon$ centred at Monterey: what does (circulation)/(area) tend to as $\\epsilon\\to0$? Use it to predict how long a Foucault pendulum at Monterey would take to turn its swing once around (it turns at $\\Omega\\sin L$).", "questions": [{"prompt": "For $\\mathbf v=w(-y,x,0)$ (rotation at rate $w$ about the $z$-axis), enter $\\nabla\\times\\mathbf v$.", "expected": ["0", "0", "2*w"], "units": "rad/s", "kind": "vector", "tolerance": 1e-05, "hints": ["The first two components involve z-derivatives and F_3 = 0, so they vanish.", "Third component: d(wx)/dx − d(−wy)/dy."], "id": "w10-p1-a", "label": "a"}, {"prompt": "Find the circulation of Earth’s rotational velocity around Monterey’s parallel (36.605° N), taken eastward. Give km²/s.", "expected": "2*pi*7.292115e-5*6371^2*cos(36.605*pi/180)^2", "units": "km²/s", "kind": "number", "tolerance": 1e-05, "hints": ["Along the parallel the velocity is tangent to it, with speed Omega R cos L.", "Or use Stokes with the flat disk: (2 Omega) times π(R cos L)²."], "id": "w10-p1-b", "label": "b"}, {"prompt": "A tiny paddle wheel is carried by the rigidly rotating air at Monterey. Its spin rate about its axle is half the component of the curl along the axle. Which axle direction makes it spin fastest?", "expected": "1", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["The curl is the same vector 2 Omega k at every point of Earth.", "The component of a fixed vector along a unit axle is largest when the axle points along it."], "options": ["Straight up (the local vertical at Monterey)", "Parallel to Earth’s axis: pointing north, tilted up 36.6° from the horizontal", "Horizontal, pointing east", "All directions spin equally, because the rotation is rigid"], "id": "w10-p1-c", "label": "c"}], "solution": ["$\\nabla\\times\\mathbf v=\\big(0-0,\\ 0-0,\\ \\partial_x(\\Omega x)-\\partial_y(-\\Omega y)\\big)=(0,0,2\\Omega)=2\\boldsymbol\\Omega$ at every point: twice the angular velocity.", "$C$: $(R\\cos L\\cos t,R\\cos L\\sin t,R\\sin L)$ with $t$ increasing eastward, counterclockwise seen from above. With the thumb pointing away from Earth’s centre on the cap (upward on the flat disk), the fingers curl this way, so these orientations are compatible.", "Directly: $(\\nabla\\times\\mathbf v)\\cdot\\mathbf n=2\\Omega z/R$ and the cap is $0\\le\\phi\\le\\pi/2-L$, so \\[\\iint_S\\frac{2\\Omega z}{R}dS=\\frac{2\\Omega}{R}\\int_0^{2\\pi}\\!\\!\\int_0^{\\pi/2-L}R^3\\cos\\phi\\sin\\phi\\,d\\phi\\,d\\theta=2\\pi\\Omega R^2\\cos^2L.\\] Flat disk: $2\\Omega\\cdot\\pi(R\\cos L)^2$. Circulation: speed $\\Omega R\\cos L$ times length $2\\pi R\\cos L$. All three give $2\\pi(7.292115\\times10^{-5})(6371)^2\\cos^2(36.605^\\circ)\\approx11{,}984.67$ km$^2$/s.", "For a tiny horizontal circle at Monterey, (circulation)/(area) $\\to(\\nabla\\times\\mathbf v)\\cdot\\mathbf n_{\\rm up}=2\\Omega\\sin L\\approx8.70\\times10^{-5}$ s$^{-1}$, where $\\mathbf n_{\\rm up}=\\mathbf r/R$ makes angle $90^\\circ-L$ with the axis. A Foucault pendulum turns at half that, $\\Omega\\sin L$, so once around takes $2\\pi/(\\Omega\\sin L)\\approx1.445\\times10^5$ s $\\approx40.1$ hours.", "A paddle wheel with unit axle $\\mathbf u$ spins at $\\tfrac12(\\nabla\\times\\mathbf v)\\cdot\\mathbf u=\\Omega\\,\\mathbf k\\cdot\\mathbf u$: fastest ($\\Omega$) for an axle parallel to Earth’s axis, $\\Omega\\sin L$ for a vertical axle, and zero for any axle perpendicular to Earth’s axis, such as one pointing east."], "reflection": "What is the vertical component of the curl at the equator, and what would a Foucault pendulum there do? What happens in Antarctica?", "extension": false, "id": "w10-p1", "discussionSolution": "At the equator the local vertical is perpendicular to Earth’s axis, so the vertical component of the curl, $2\\Omega\\sin0$, is zero and a Foucault pendulum’s swing does not turn. In the Southern Hemisphere sin L < 0, so it turns the other way (counterclockwise seen from above); at the South Pole it turns once per sidereal day, $2\\pi/\\Omega\\approx23.93$ hours.", "modelSpec": {"data": ["Earth’s angular velocity: $\\Omega=7.292115\\times10^{-5}$ rad/s", "Earth’s mean radius: $R=6371$ km", "Monterey Harbor latitude: $L=36.605^\\circ$ N"], "assume": ["Earth and everything on it rotate rigidly; winds and currents relative to the ground are ignored", "Earth is a perfect sphere centred at the origin, with the $z$-axis through the North Pole"], "model": ["Velocity seen from space: $\\mathbf v=\\boldsymbol\\Omega\\times\\mathbf r$ with $\\boldsymbol\\Omega=(0,0,\\Omega)$", "Monterey’s parallel $C$: the circle $x^2+y^2=(R\\cos L)^2$, $z=R\\sin L$", "Polar cap $S$: the part of $x^2+y^2+z^2=R^2$ with $z\\ge R\\sin L$"]}, "photo": {"alt": "Star trails circling the north celestial pole above the Gemini North telescope dome on Maunakea, Hawaii: a long exposure that records Earth’s rotation", "credit": "International Gemini Observatory/NOIRLab/NSF/AURA/T. Matsopoulos", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/", "page": "https://commons.wikimedia.org/wiki/File:Star_Trails_Above_Gemini_North_(iotw2506a).jpg", "file": "w10-p1.jpg"}, "figure": {"alt": "Earth in cross-section with its rotation axis, the parallel through Monterey, the polar cap above it, and paddle wheels with different axle directions", "caption": "The model: Earth rotating rigidly about the $z$-axis, Monterey’s parallel $C$ at latitude $L$, and the polar cap $S$ (teal) that it bounds.", "file": "w10-p1"}}, {"title": "Charging a phone through thin air", "context": "Lay a phone on a Qi charging pad and it charges with no plug. A coil in the pad drives a rapidly oscillating magnetic field; the changing field creates a circulating electric field, which pushes current around a coil in the phone. Faraday’s law, written in the language of Stokes’ theorem, says exactly how much push the phone gets.", "model": "The coil size and frequency are published for one Qi reference design; the uniform field, its 1 mT amplitude, and the loop shapes are assumptions.", "sources": ["qispec"], "work": "Check that the model field satisfies Faraday’s law $\\nabla\\times\\mathbf E=-\\partial\\mathbf B/\\partial t$. Parametrize the flat loop $x^2+y^2=0.02^2$, $z=0$, counterclockwise seen from above, compute $\\oint\\mathbf E\\cdot d\\mathbf r$ directly, and confirm it with Stokes’ theorem on the flat disk, stating which normal the right-hand rule pairs with this direction. Explain why this loop, whose plane is perpendicular to $\\nabla\\times\\mathbf E$, has nonzero circulation, while a loop standing vertically in the plane $x=0$ (a phone on its edge) has none. For the tilted loop $C$, describe its shape, explain why a direct parametrization is unpleasant, choose the planar surface it bounds, and write that surface’s upward vector area element. Why does the answer not depend on the tilt, even though $C$ is longer than the flat circle?", "questions": [{"prompt": "Enter $\\nabla\\times\\mathbf E$ for $\\mathbf E=\\tfrac b2(y,-x,0)$.", "expected": ["0", "0", "-b"], "units": "V/m²", "kind": "vector", "tolerance": 1e-05, "hints": ["Only the third component survives: d(−bx/2)/dx − d(by/2)/dy.", "Compare with −dB/dt = (0, 0, −b)."], "id": "w10-p2-a", "label": "a"}, {"prompt": "Find $\\oint\\mathbf E\\cdot d\\mathbf r$ around the flat loop of radius 0.02 m, counterclockwise seen from above, as a function of b.", "expected": "-0.0004*pi*b", "units": "V", "kind": "expression", "tolerance": 1e-05, "hints": ["With r(t) = (0.02 cos t, 0.02 sin t, 0), E · r′ = −(b/2)(0.02)².", "Integrate over 0 ≤ t ≤ 2π; the sign is Lenz’s law."], "id": "w10-p2-b", "label": "b"}, {"prompt": "For the tilted loop C, find the peak size of the EMF (the circulation of E) during a cycle, in volts.", "expected": "2*pi*140000*0.001*pi*0.02^2", "units": "V", "kind": "number", "tolerance": 1e-05, "hints": ["Stokes on the planar patch z = 0.004 + 0.36y over the disk: the vector area element is (0, −0.36, 1) dA.", "Then |EMF| = |b| times π(0.02)², and |b| peaks at 0.001 × 2π × 140000 T/s."], "id": "w10-p2-c", "label": "c"}], "solution": ["$\\nabla\\times\\mathbf E=\\big(0,\\,0,\\,\\partial_x(-bx/2)-\\partial_y(by/2)\\big)=(0,0,-b)=-\\partial\\mathbf B/\\partial t$, so the model field obeys Faraday’s law.", "On $\\mathbf r(t)=(0.02\\cos t,0.02\\sin t,0)$, $\\mathbf E\\cdot\\mathbf r^\\prime=\\tfrac b2\\big(0.02\\sin t(-0.02\\sin t)-0.02\\cos t(0.02\\cos t)\\big)=-\\tfrac b2(0.0004)$, so $\\oint\\mathbf E\\cdot d\\mathbf r=-0.0004\\pi b$ V. Stokes: counterclockwise from above pairs with the upward normal $\\mathbf k$, and $(\\nabla\\times\\mathbf E)\\cdot\\mathbf k=-b$ times the area $0.0004\\pi$ gives the same.", "This loop’s normal is parallel to $\\nabla\\times\\mathbf E$, the best case. A loop in the plane $x=0$ has normal $(1,0,0)$, perpendicular to $\\nabla\\times\\mathbf E$, so the flux through its disk, and hence its EMF, is $0$: an upright phone does not charge.", "$C$ is an ellipse in the tilted plane whose shadow is the circle of radius $0.02$; parametrizing it means carrying $z=0.004+0.36\\cdot0.02\\sin t$ through the dot product. Instead take the planar patch $z=0.004+0.36y$ over the disk, with upward element $(0,-0.36,1)\\,dA$: $(\\nabla\\times\\mathbf E)\\cdot(0,-0.36,1)=-b$, so the EMF is $-b\\pi(0.02)^2$, the same as the flat loop. Only the vertical component of the vector area meets the vertical curl.", "With $B=0.001\\sin(2\\pi\\cdot140000\\,t)$, $|b|$ peaks at $0.001(2\\pi)(140000)\\approx879.6$ T/s, so the peak EMF is $879.6\\times\\pi(0.02)^2\\approx1.105$ V per turn."], "reflection": "A real receiver coil has several turns, and a phone may lie tilted on the pad as a whole. How does the EMF scale with the number of turns, and why would a circular coil tilted by 30° get less EMF than the model loop C?", "extension": false, "id": "w10-p2", "discussionSolution": "Each turn is a loop with the same flux change, so the EMF is multiplied by the number of turns. A circle of radius r tilted by 30° has vector area πr² n with a vertical component πr² cos 30°, so the flux of the vertical field, and the EMF, drop by the factor cos 30° ≈ 0.87. The model loop C instead kept a full disk as its shadow, which is why its EMF did not change.", "modelSpec": {"data": ["Qi reference transmitter design A2: coil outer diameter $40$ mm, inner diameter $19$ mm, $2\times10$ turns", "Fixed operating frequency: $140$ kHz"], "assume": ["Over the coil the magnetic field is vertical and uniform: $\\mathbf B=(0,0,B(t))$ with $B(t)=0.001\\sin(2\\pi\\cdot140000\\,t)$ T", "The receiver loop has a single turn; edge effects are ignored"], "model": ["Faraday’s law: $\\nabla\\times\\mathbf E=-\\partial\\mathbf B/\\partial t$; with $b=B^\\prime(t)$ (T/s), the induced field is $\\mathbf E=\\tfrac b2(y,-x,0)$ V/m", "EMF of a loop $=\\oint\\mathbf E\\cdot d\\mathbf r$", "Tilted loop $C$: where the plane $z=0.004+0.36y$ meets the cylinder $x^2+y^2=0.02^2$ (metres), counterclockwise seen from above"]}, "photo": {"alt": "A smartphone lying on a black wireless charging pad, its screen showing a charging symbol", "credit": "LG Electronics", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/", "page": "https://commons.wikimedia.org/wiki/File:Inductive_charging_of_LG_smartphone_(2).jpg", "file": "w10-p2.jpg"}, "figure": {"alt": "Three-dimensional sketch of the flat circular loop on the pad, the tilted elliptical loop above it on the same cylinder, and vertical magnetic field arrows", "caption": "The model: a uniform vertical field over the pad’s coil, the flat loop at $z=0$, and the tilted loop $C$ on the cylinder $x^2+y^2=0.02^2$.", "file": "w10-p2"}}, {"title": "Which magnetic fields can steer the LHC?", "context": "The Large Hadron Collider at CERN, on the French–Swiss border, steers two proton beams around a 27 km ring with 1232 superconducting dipole magnets and focuses them with hundreds of quadrupole magnets. Inside the beam pipe there is no current and, as everywhere in nature, no magnetic monopoles. Those two facts decide which magnetic fields are possible at all, and they explain why no single magnet can focus a beam in every direction at once.", "model": "The ring size, dipole field, quadrupole gradient, and beam-screen size are published; ideal two-dimensional magnet fields and the search-coil geometry are assumptions.", "sources": ["lhcdesign", "lhcquad"], "work": "Prove that $\\nabla\\cdot(\\nabla\\times\\mathbf F)=0$ for every $C^2$ field $\\mathbf F$, and explain why a field with nonzero divergence can never be a curl, and so never a magnetic field. For each option in part (a), compute its divergence and curl. A proton moving along $+z$ feels a force proportional to $\\mathbf k\\times\\mathbf B$: compute it for $\\mathbf B=G(y,x,0)$ and show that the quadrupole pushes protons toward the axis in one transverse direction and away from it in the other. To find $\\mathbf A$ in (b), write the three component equations of $\\nabla\\times\\mathbf A=\\mathbf B$ with $A_1=0$, integrate them in $x$, and choose the leftover functions of $(y,z)$. Use Stokes’ theorem, after cutting a closed surface into two patches along a curve, to explain why the flux of any curl, and so of $\\mathbf B$, through every closed surface is $0$. Finally, the quadrupole field is also a gradient: find $\\psi$ with $\\nabla\\psi=\\mathbf B$.", "questions": [{"prompt": "Inside the beam screen there is no current, so a magnetic field there must have zero divergence and zero curl. With G = 223 T/m, which field is possible?", "expected": "2", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["Divergence must be 0: that already rules out two options.", "Of the remaining two, one has curl (0, 0, 2G), which would need a current in the beam pipe."], "options": ["$G(x,y,0)$", "$G(-y,x,0)$", "$G(y,x,0)$", "$G(x,y,-z)$"], "id": "w10-p3-a", "label": "a"}, {"prompt": "Find a vector potential $\\mathbf A=(0,A_2,A_3)$ with $\\nabla\\times\\mathbf A=223\\,(y,x,0)$. Enter its three components.", "expected": ["0", "0", "223*(y^2-x^2)/2"], "units": "T·m", "kind": "vector", "tolerance": 1e-05, "hints": ["With A_1 = 0, the second component of the curl is −dA_3/dx, so A_3 = −223x²/2 + g(y, z).", "The first component dA_3/dy − dA_2/dz must equal 223y; the third, dA_2/dx, must be 0."], "semantic": "curl", "curlTarget": ["223*y", "223*x", "0"], "firstComponentZero": true, "id": "w10-p3-b", "label": "b"}, {"prompt": "A rectangular search coil lies in the plane y = 0, from x = 0 to x = 0.017 m and along 1 m of the quadrupole. Find the magnetic flux through it in the +y direction, in webers.", "expected": "223*0.017^2/2", "units": "Wb", "kind": "number", "tolerance": 1e-05, "hints": ["Through the plane y = 0 the flux density is B_y = 223x.", "Integrate 223x over 0 ≤ x ≤ 0.017 and 0 ≤ z ≤ 1, or use the circulation of A around the coil."], "id": "w10-p3-c", "label": "c"}], "solution": ["$\\nabla\\cdot(\\nabla\\times\\mathbf F)=\\partial_x(\\partial_yF_3-\\partial_zF_2)+\\partial_y(\\partial_zF_1-\\partial_xF_3)+\\partial_z(\\partial_xF_2-\\partial_yF_1)=0$ because mixed partials of $C^2$ functions are equal. So $\\nabla\\cdot\\mathbf G\\ne0$ rules out $\\mathbf G=\\nabla\\times\\mathbf A$: $G(x,y,0)$ has divergence $2G$ and $G(x,y,-z)$ has divergence $G$. $G(-y,x,0)$ has divergence $0$ but curl $(0,0,2G)\\ne\\mathbf0$, which would require current. $G(y,x,0)$ has divergence $0$ and curl $(0-0,0-0,G-G)=\\mathbf0$: possible.", "$\\mathbf k\\times G(y,x,0)=G(-x,y,0)$: a proton displaced in $x$ is pushed back toward the axis (focusing), but one displaced in $y$ is pushed farther out (defocusing). A linear field that focused in both directions would be $\\propto(-y,x,0)$ in $\\mathbf B$, which has nonzero curl. That is why accelerators alternate quadrupoles of opposite orientation.", "With $A_1=0$: $\\partial_yA_3-\\partial_zA_2=Gy$, $-\\partial_xA_3=Gx$, $\\partial_xA_2=0$. So $A_3=-Gx^2/2+g(y,z)$ and $A_2=h(y,z)$, and the first equation becomes $g_y-h_z=Gy$; take $g=Gy^2/2$, $h=0$. Then $\\mathbf A=\\big(0,0,\\tfrac{223}{2}(y^2-x^2)\\big)$; check: $\\nabla\\times\\mathbf A=(223y,\\ 223x,\\ 0)$. (For the dipole, $(0,0,-8.33x)$ works.) Since $\\mathbf B=\\nabla(Gxy)$ as well, the quadrupole field is both a gradient and a curl: in a current-free region it has zero curl and zero divergence.", "Flux through the coil: $\\int_0^1\\!\\int_0^{0.017}223x\\,dx\\,dz=223(0.017)^2/2\\approx0.0322$ Wb. Stokes check: with normal $+\\mathbf j$, the boundary runs up $z$ along $x=0$ (where $A_3=0$) and down $z$ along $x=0.017$, where $A_3=-223(0.017)^2/2$, giving $+223(0.017)^2/2$; the $x$-edges have $\\mathbf A\\cdot d\\mathbf r=0$.", "For a closed surface, cut it along a closed curve into two patches. Stokes gives each patch’s flux of $\\nabla\\times\\mathbf A$ as the circulation of $\\mathbf A$ around the cut, traversed in opposite directions for the two patches, so the total is $0$. Hence $\\mathbf B$ has zero flux through every closed surface: no magnetic monopoles."], "reflection": "The LHC dipoles have field 8.33 T. Is the uniform field (0, 8.33, 0) a curl, a gradient, both, or neither? Give a vector potential and a scalar potential if they exist.", "extension": false, "id": "w10-p3", "discussionSolution": "Both. Its divergence and curl are zero. A vector potential is (0, 0, −8.33x) (curl = (0, 8.33, 0)), and a scalar potential is $\\psi=8.33y$. Any constant field is a gradient and a curl on all of R³.", "modelSpec": {"data": ["Ring circumference $26{,}658.883$ m; $1232$ main dipoles with field $8.33$ T", "$408$ main arc quadrupoles, nominal gradient $223$ T/m", "Beam screen in the arcs: $36.9$ mm wide, $46.5$ mm high"], "assume": ["No current flows inside the beam screen, so there $\\nabla\\cdot\\mathbf B=0$ and $\\nabla\\times\\mathbf B=\\mathbf 0$", "Magnet fields are ideal and independent of position along the beam", "A rectangular search coil (hypothetical) lies in the plane $y=0$, $0\\le x\\le0.017$ m, along $1$ m of a quadrupole"], "model": ["Beam along $+z$; dipole field $(0,8.33,0)$ T; quadrupole field $\\mathbf B=G(y,x,0)$, $G=223$ T/m, $x,y$ in metres", "Magnetic force on a proton moving along $+z$: proportional to $\\mathbf k\\times\\mathbf B$", "Vector potential: any $\\mathbf A$ with $\\nabla\\times\\mathbf A=\\mathbf B$"]}, "photo": {"alt": "The LHC tunnel during installation, with the blue cryostats of superconducting magnets lining one side", "credit": "alpinethread", "license": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "page": "https://commons.wikimedia.org/wiki/File:LHC_dipole_magnets.jpg", "file": "w10-p3.jpg"}, "figure": {"alt": "Cross-section of the quadrupole field: hyperbolic field lines with arrows, the rectangular beam screen, and the search-coil segment along the x-axis", "caption": "Field lines of $\\mathbf B=G(y,x,0)$ in the beam-pipe cross-section (millimetres), the $36.9\\times46.5$ mm beam screen, and the search coil (orange) in the plane $y=0$.", "file": "w10-p3"}}, {"title": "What lights up the aurora?", "context": "The aurora over Alaska glows where fast electrons crash into the upper atmosphere. ESA’s Cluster satellites found that the electrons are first accelerated to energies of several thousand electronvolts in narrow electric structures thousands of kilometres up, while they spiral around Earth’s magnetic field lines. Lower down, the auroral electrojet, a current of up to half a million amperes, flows east–west near 100 km altitude, and its magnetic field reaches the ground.", "model": "The electron energies, current size, and altitude are published typical values; the force field, the spiral path, and the straight-line current are models.", "sources": ["esacluster", "uafelectrojet"], "work": "Show that $\\nabla\\times\\mathbf F=\\mathbf 0$ on all of $\\mathbb R^3$, then find $f$ with $\\nabla f=\\mathbf F$ by successive integration, carrying the unknown $g(y,z)$ and then $h(z)$ explicitly. Explain why the electron’s energy gain along the spiral needs only its endpoints, and check that the answer is “several keV.” For the electrojet field, show that $\\nabla\\times\\mathbf B=\\mathbf 0$ everywhere off the current line; then compute $\\oint\\mathbf B\\cdot d\\mathbf r$ around a circle of radius $\\rho$ about the line, and use it to find the field strength on the ground directly below the current, in nanotesla. Explain why zero curl and a nonzero circulation do not contradict each other here, and why the point-source field $\\mathbf r/|\\mathbf r|^3$, defined on $\\mathbb R^3$ minus a point, has no such problem.", "questions": [{"prompt": "Find a potential $f$ with $\\nabla f=\\mathbf F=(2xz,\\ 2yz,\\ x^2+y^2-2)$.", "expected": "x^2*z+y^2*z-2*z", "units": "keV", "kind": "potential", "tolerance": 1e-05, "hints": ["Integrate 2xz in x: f = x²z + g(y, z). Then f_y = 2yz forces g = y²z + h(z).", "Finally f_z = x² + y² + h′(z) must equal x² + y² − 2."], "id": "w10-p4-a", "label": "a"}, {"prompt": "How much energy (keV) does the electric force give the electron along the spiral c(t) = (0.5 cos t, 0.5 sin t, 3 − t/(2π)), 0 ≤ t ≤ 6π?", "expected": "(0.5^2*0-2*0)-(0.5^2*3-2*3)", "units": "keV", "kind": "number", "tolerance": 1e-05, "hints": ["Work = f(end) − f(start) for a gradient field.", "The spiral starts at (0.5, 0, 3) and ends at (0.5, 0, 0)."], "id": "w10-p4-b", "label": "b"}, {"prompt": "Which of these fields is a gradient on its whole domain?", "expected": "3", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["Two of these have nonzero curl, so they are out at once.", "Zero curl is enough only if every loop in the domain can shrink to a point without leaving the domain."], "options": ["The electrojet field $\\mathbf B$, on $\\mathbb R^3$ minus the current line", "Earth’s rotational velocity $\\Omega(-y,x,0)$, on $\\mathbb R^3$", "The charging pad’s induced field $\\tfrac b2(y,-x,0)$, on $\\mathbb R^3$", "The point-source field $\\mathbf r/|\\mathbf r|^3$, on $\\mathbb R^3$ minus the origin"], "id": "w10-p4-c", "label": "c"}], "solution": ["Componentwise: $\\partial_yF_3-\\partial_zF_2=2y-2y=0$, $\\partial_zF_1-\\partial_xF_3=2x-2x=0$, $\\partial_xF_2-\\partial_yF_1=0$. So $\\mathbf F$ is conservative on the simply connected $\\mathbb R^3$.", "$f=\\int2xz\\,dx=x^2z+g(y,z)$; $f_y=g_y=2yz$ gives $g=y^2z+h(z)$; $f_z=x^2+y^2+h^\\prime(z)=x^2+y^2-2$ gives $h=-2z+C$. So $f=x^2z+y^2z-2z+C$.", "By the fundamental theorem for line integrals the work is $f(0.5,0,0)-f(0.5,0,3)=0-3(0.25-2)=5.25$ keV, “several keV,” no matter how many times the path winds. (Real gyration radii are metres, not hundreds of kilometres; it does not matter.)", "For $\\mathbf B=\\frac{\\mu_0I}{2\\pi}\\frac{(0,-(z-h),y)}{y^2+(z-h)^2}$, the components give $\\nabla\\times\\mathbf B=\\mathbf0$ wherever $y^2+(z-h)^2\\ne0$. On a circle of radius $\\rho$ about the line, $\\mathbf B$ is tangent with size $\\mu_0I/(2\\pi\\rho)$, so $\\oint\\mathbf B\\cdot d\\mathbf r=\\mu_0I\\ne0$ (Ampère’s law). On the ground, $\\rho=h=10^5$ m: $B=\\frac{4\\pi\\times10^{-7}(5\\times10^5)}{2\\pi(10^5)}=10^{-6}$ T $=1000$ nT.", "No contradiction: the domain is $\\mathbb R^3$ minus a line, and a loop around the line cannot shrink to a point without crossing it, so zero curl does not force a potential (any “potential” would have to increase by $\\mu_0I$ each time around). Removing only a point leaves a simply connected domain, since loops slide off the point; $\\mathbf r/|\\mathbf r|^3=\\nabla(-1/|\\mathbf r|)$. The rotation and induced fields have curl $(0,0,2\\Omega)$ and $(0,0,-b)$, so they are not gradients."], "reflection": "A magnetometer on the ground is not directly below the electrojet but 100 km to the side. Using only Ampère’s law and the geometry, how does the field strength there compare with the 1000 nT directly below?", "extension": false, "id": "w10-p4", "discussionSolution": "At the ground point 100 km to the side, the distance to the current is $\\rho=\\sqrt2\\times100$ km, and the field is tangent to the circle of that radius with size $\\mu_0I/(2\\pi\\rho)$: smaller by the factor $1/\\sqrt2$, about 707 nT, and tilted 45° from the horizontal.", "modelSpec": {"data": ["Auroral electrons are accelerated to several keV in structures starting several thousand km up", "Auroral electrojet: mostly east–west near $100$ km altitude, up to about half a million amperes"], "assume": ["Units: lengths in thousands of km, energies in keV; the force field below stands in for a real acceleration structure", "The spiral path is drawn hugely wider than a real gyration (metres) to be visible", "Electrojet: a straight line current $I=5\\times10^5$ A along the $x$-axis (east) at height $h=100$ km over flat ground; $\\mu_0=4\\pi\\times10^{-7}$ T·m/A"], "model": ["Electric force on the electron: $\\mathbf F=(2xz,\\ 2yz,\\ x^2+y^2-2)$ keV per $1000$ km", "Spiral: $\\mathbf c(t)=(0.5\\cos t,\\ 0.5\\sin t,\\ 3-t/(2\\pi))$, $0\\le t\\le6\\pi$", "Electrojet field (SI units): $\\mathbf B=\\dfrac{\\mu_0I}{2\\pi}\\,\\dfrac{(0,\\,-(z-h),\\,y)}{y^2+(z-h)^2}$"]}, "photo": {"alt": "Green and red aurora borealis filling the night sky above silhouetted trees at Wickersham Dome, Alaska", "credit": "FairbanksMike", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/", "page": "https://commons.wikimedia.org/wiki/File:Aurora_Borealis_-_Wickersham_Dome_-_Alaska_-_16_March_2013.jpg", "file": "w10-p4.jpg"}, "figure": {"alt": "Left: a spiral path descending around a vertical line from 3000 km to the ground. Right: circular magnetic field lines around a line current at 100 km altitude above the ground", "caption": "Left: the model spiral path (radius exaggerated). Right: the electrojet as a line current at $h=100$ km, seen end-on, with circular field lines (not to scale).", "file": "w10-p4"}}, {"title": "What Happens Inside Stays Inside", "context": "Earth leaks heat from its interior through every square metre of its surface, from radioactive elements in the rocks and from heat left over from the planet’s formation. Davies and Davies (2010) combined heat-flow measurements with maps of geology and models of cooling ocean floor to estimate the total at 47 terawatts. The Divergence Theorem connects that surface total to what happens inside.", "model": "The total and continental heat flows are published; uniform heat production and the crustal heat-production profile are assumptions.", "sources": ["earthheat", "earth"], "work": "Use $\\mathbf n=\\mathbf r/R$ to find the average outward heat flux. For the thought experiment, compute $\\nabla\\cdot\\mathbf q$ and check the Divergence Theorem on the ball by also computing the surface integral directly. For the crustal column, list its six faces with their outward normals (the bottom’s points down), and say which faces carry heat. Apply the Divergence Theorem to the column to find the heat entering its bottom from the mantle per square metre. Compare the uniform-production $H$ from (b) with the crust’s $2.5\\ \\mu$W/m$^3$ at the surface: what does this suggest about where Earth’s heat-producing elements are?", "questions": [{"prompt": "Find the average outward heat flux through Earth’s surface, in mW/m².", "expected": "47*10^12/(4*pi*6371000^2)*1000", "units": "mW/m²", "kind": "number", "tolerance": 1e-05, "hints": ["The flux through the sphere is 47 TW = 4.7e13 W.", "Divide by the area 4πR² with R = 6.371e6 m."], "id": "w10-p5-a", "label": "a"}, {"prompt": "If the 47 TW were produced uniformly throughout Earth’s volume, with steady flux q = (H/3)(x, y, z), what would H be? Give nW/m³ (1 nW = 1e−9 W).", "expected": "47*10^12/(4/3*pi*6371000^3)*10^9", "units": "nW/m³", "kind": "number", "tolerance": 1e-05, "hints": ["div q = H, so the Divergence Theorem gives H times Earth’s volume = 47 TW.", "Earth’s volume is (4/3)πR³."], "id": "w10-p5-b", "label": "b"}, {"prompt": "Find the heat flux entering the bottom of the continental crust from the mantle, in mW/m².", "expected": "73-25*(1-exp(-3.5))", "units": "mW/m²", "kind": "number", "tolerance": 1e-05, "hints": ["For a column of area A: (outward flux) = 73A − q_m A = A times the integral of H(z) dz from −35 to 0.", "2.5 microwatts per m³ times 10 km is 25 mW/m², so the integral is 25(1 − e^(−3.5)) mW/m²."], "id": "w10-p5-c", "label": "c"}], "solution": ["$\\iint\\mathbf q\\cdot\\mathbf n\\,dS=47$ TW over $4\\pi R^2=5.10\\times10^{14}$ m$^2$ gives an average of $92.15$ mW/m$^2$.", "$\\nabla\\cdot\\big(\\tfrac H3(x,y,z)\\big)=H$. Directly, $\\mathbf q\\cdot\\mathbf n=\\tfrac H3R$ on the sphere, so the flux is $\\tfrac H3R\\cdot4\\pi R^2=H\\cdot\\tfrac43\\pi R^3$: the Divergence Theorem checks. Setting it to $47$ TW gives $H=47\\times10^{12}/(1.083\\times10^{21})\\approx4.34\\times10^{-8}$ W/m$^3=43.39$ nW/m$^3$.", "Column $[0,a]\\times[0,a]\\times[-35,0]$ km with $\\mathbf q=(0,0,q(z))$: the four sides have horizontal normals, so $\\mathbf q\\cdot\\mathbf n=0$; the top has $\\mathbf n=\\mathbf k$ and flux $73A$; the bottom has outward $\\mathbf n=-\\mathbf k$ and flux $-q_mA$. Since $\\nabla\\cdot\\mathbf q=q^\\prime(z)=H(z)$, \\[(73-q_m)A=A\\int_{-35}^0 2.5e^{z/10}\\,dz\\ \\ (\\mu\\text{W/m}^3\\cdot\\text{km})=25(1-e^{-3.5})A\\text{ mW/m}^2,\\] so $q_m=73-24.25\\approx48.75$ mW/m$^2$.", "The crust near the surface produces about $2.5\\ \\mu$W/m$^3$, roughly 60 times the whole-Earth average of $0.043\\ \\mu$W/m$^3$: heat-producing elements are strongly concentrated in the continental crust."], "reflection": "In the crustal column, suppose you had used the upward normal on the bottom face by mistake. What mantle heat flux would you have reported, and how could you tell it was wrong?", "extension": true, "id": "w10-p5", "discussionSolution": "With the wrong normal the bottom term becomes +q_m A, so 73 + q_m = 24.25 and q_m ≈ −48.75 mW/m², a negative value meaning heat flowing down into the mantle. Heat flows from the hot interior upward, so the sign gives the error away; with the outward (downward) normal, the bottom flux is −q_m A, negative because heat enters there.", "modelSpec": {"data": ["Total heat flow out of Earth: $47\\pm2$ TW", "Continents: $13.8$ TW, mean $73$ mW/m$^2$", "Earth’s mean radius $R=6371$ km"], "assume": ["Steady state: heat flux does not change with time", "Thought experiment: heat produced uniformly in the whole Earth", "Continental crust $35$ km thick with heat production $H(z)=2.5\\,e^{z/10}\\ \\mu$W/m$^3$ ($z$ in km, $-35\\le z\\le0$); heat flows only vertically in the crust"], "model": ["Divergence Theorem: $\\iint_{\\partial W}\\mathbf q\\cdot\\mathbf n\\,dS=\\iiint_W\\nabla\\cdot\\mathbf q\\,dV$, with $\\nabla\\cdot\\mathbf q=$ heat production", "Whole Earth (thought experiment): $\\mathbf q=\\tfrac H3(x,y,z)$ on the ball of radius $R$", "Crust: $\\mathbf q=(0,0,q(z))$ with $q^\\prime(z)=H(z)$, surface value $q(0)=73$ mW/m$^2$, mantle input $q(-35)=q_m$"]}, "figure": {"alt": "Left: Earth with outward heat-flux arrows. Right: a column of continental crust with heat entering the bottom and leaving the top", "caption": "Left: heat leaving Earth through its surface. Right: the crustal column; only its top and bottom faces carry heat in the model.", "file": "w10-p5"}}]}]};
